-- =============================================================================
-- Сонсголын асуултын монгол тайлбар  (2026-09-16)
-- =============================================================================
--
-- 415 сонсголын асуултын 413-д «яагаад энэ хариулт зөв бэ» гэсэн монгол
-- тайлбар бичив. Үлдсэн 2 (H41327 №42, №43 — эрүүл мэндийн үзлэгийн тухай
-- хэсэг) нь бичлэгээс баталж чадаагүй тул ЗОРИУД хоосон орхив — таамгаар
-- тайлбар бичихээс татгалзсан.
--
-- Эх сурвалж: HSK-ийн албан ёсны материалд сонсголын эх бичвэр (听力材料)
-- нийтлэгддэггүй. Тиймээс бичлэгийг яриа таних загвараар буулгаж, асуулт
-- бүрд нь хуваарилаад, тэр бичвэрээс тайлбарыг бичсэн. Бичвэрийн ханзны
-- алдааг (жишээ нь 难得 → 男的) засаж, эргэлзээтэй хэллэгийг иш татаагүй.
-- Бичвэр өөрөө хаана ч харагдахгүй — зөвхөн тайлбар харагдана.
--
-- Дахин ажиллуулахад аюулгүй.
-- =============================================================================

begin;

update mock_test_questions as t
   set explanation_mn = v.explanation
  from (values
  ('5ccf9f25-9e9b-4039-a46a-cc7716831292'::uuid, 'Бичлэгт зөвхөн 看不见 (харагдахгүй байна) гэсэн богино өгүүлбэр сонсогдож байна. Энэ утга нь зурагт дүрслэгдсэн үйлдэлтэй тохирч байгаа гэж үзсэн тул хариулт нь √ (зөв) гэж өгөгдсөн. Сонссон утгаа зурагтай нягт тулгаж, ижил санааг илэрхийлж байгаа эсэхийг өөрөө шалгаарай.'),
  ('f4d1e31a-f8ac-4e1e-8796-a3eed3bbe34e'::uuid, 'Бичлэгт зөвхөн 一个电脑 (нэг компьютер) гэсэн үг сонсогдож байна. Хариулт нь × (буруу) гэж өгөгдсөн тул зурагт компьютерээс өөр зүйл, эсвэл өөр тоо дүрслэгдсэн байх магадлалтай. Сонссон үгээ зурагтай тулгаж, яг компьютер харагдаж байгаа эсэхийг нягтлаарай.'),
  ('d6ba2d6a-a481-4f41-a077-eebbd65a92c7'::uuid, 'Бичлэгт зөвхөн 读书 (ном унших) гэсэн үг хэлэгдэж байна. Хариулт × (буруу) гэж өгөгдсөн тул зурагт хүн ном унших бус өөр үйлдэл (жишээ нь бичих, ярих) хийж байгаа байх магадлалтай. Сонссон үгийг зурагт харагдаж буй үйлдэлтэй тулгаж, таарахгүй байгааг олоорой.'),
  ('27ca518d-cd3f-4750-9453-671e48ada5bc'::uuid, 'Бичлэгт 桌子和椅子 (ширээ болон сандал) гэсэн үг сонсогдож байна. Хариулт × (буруу) гэж өгөгдсөн тул зурагт эдгээр эд зүйлийн аль нэг нь дутуу эсвэл өөр эд зүйл дүрслэгдсэн байх магадлалтай. Зурагт яг ширээ, сандал хоёулаа хамт харагдаж байгаа эсэхийг нягтлаарай.'),
  ('9ba412ae-d5a3-4a38-9dce-d6915db861d2'::uuid, 'Бичлэгт зөвхөн 在上面 (дээр нь байна) гэсэн богино өгүүлбэр сонсогдож байна. Хариулт нь √ (зөв) гэж өгөгдсөн тул зурагт дурдсан зүйл өөр зүйлийн яг дээр байрлаж байгаа дүр харагдах ёстой. Сонссон байршлын үгийг зурагтай тулгаж, тохирч байгаа эсэхийг шалгаарай.'),
  ('abe84541-4388-49de-ab20-2d821363188c'::uuid, 'Бичлэгт 不客气,喜欢吗? (Тавгүйрхэх хэрэггүй, таалагдаж байна уу?) гэж асуусан байна. Хариулт C гэж өгөгдсөн тул C зурагт энэ өгүүлбэртэй уялдах, жишээ нь бэлэг өгч буй, таашаал илэрхийлж буй дүр байгаа гэж үзсэн. A, B зургийг ч мөн харж, аль нь энэ яриатай хамгийн сайн тохирохыг өөрөө нягтлаарай.'),
  ('15b07742-9d7c-47ec-8f34-5de13bff46eb'::uuid, 'Бичлэгт 你能听见我说话吗? (Чи миний ярьж байгааг сонсож байна уу?) гэсэн асуулт сонсогдож байна. Хариулт B гэж өгөгдсөн тул B зурагт сонсох, ярих үйлдэлтэй холбоотой дүр байгаа гэж үзсэн. A, C зурагтай тулгаад аль нь энэ агуулгад тохирохгүй байгааг олоорой.'),
  ('f210629c-11aa-4c21-bbad-e11f1742ccda'::uuid, 'Бичлэгт 你前面有几个人? (Чиний өмнө хэдэн хүн байна вэ?) гэсэн асуулт сонсогдож байна. Хариулт C гэж өгөгдсөн тул C зурагт зөв тооны хүн эгнэсэн дүр харагдах ёстой. A, B зурагт хүний тоо өөр байгаа тул тохирохгүй гэж үзэж болно, тиймээс тоог нарийн тоолж зурагтай тулгаарай.'),
  ('f3c21709-1eb6-4999-bbb8-ec8212b55f53'::uuid, 'Бичлэгт 他在睡觉呢? (Тэр унтаж байна уу?) гэсэн асуулт сонсогдож байна. Хариулт A гэж өгөгдсөн тул A зурагт хүн унтаж байгаа дүр харагдах ёстой. B, C зурагт унтахаас өөр үйлдэл (сууж, зогсож гэх мэт) байгаа тул тохирохгүй гэж үзсэн, зурагтай тулгаж баталгаажуулаарай.'),
  ('d50d6c62-6d1e-4794-a2f1-8798381d97ca'::uuid, 'Бичлэгт 今天中午,我们吃米饭 (Өнөөдөр өдийн цагаар бид цагаан будаа идэх болно) гэж хэлсэн байна. Хариулт B гэж өгөгдсөн тул B зурагт цагаан будаа идэж буй дүр харагдах ёстой. A, C зурагт өөр хоол дүрслэгдсэн байх магадлалтай тул 米饭 (цагаан будаа) гэдэг үгэнд анхаарлаа хандуулж зурагтай тулгаарай.'),
  ('6d035fb6-d3e0-4993-b12d-c329a224b008'::uuid, 'Бичлэгт 你看见我的狗了吗? 在那儿呢 (Миний нохойг харсан уу? Тэнд байна) гэсэн яриа сонсогдож байна. Хариулт B гэж өгөгдсөн тул B зурагт нохой дүрслэгдсэн байх ёстой. Бусад зургуудаас 狗 (нохой) гэдэг үгтэй холбоотой дүрийг олж, B зурагтай тулгаж баталгаажуулаарай.'),
  ('f831cd01-01aa-4592-a600-4ffd9932e15b'::uuid, 'Бичлэгт 菜什么时候能做好? 五分钟后 (Хоол хэзээ бэлэн болох вэ? Таван минутын дараа) гэсэн яриа сонсогдож байна. Хариулт E гэж өгөгдсөн тул E зурагт хоол хийж буй эсвэл хоолтой холбоотой дүр харагдах ёстой. 菜 (хоол) гэдэг түлхүүр үгэнд тулгуурлан E зургийг олоорой.'),
  ('3317354f-9247-4f16-ad38-a0f629f349e6'::uuid, 'Бичлэгт 这里太漂亮了。那我们多住几天? (Энд маш үзэсгэлэнтэй юм. Тэгвэл бид хэдэн өдөр илүү амьдрах вэ?) гэсэн яриа сонсогдож байна. Хариулт F гэж өгөгдсөн тул F зурагт үзэсгэлэнтэй газар, буудал зэрэгтэй холбоотой дүр харагдах ёстой. 住 (амьдрах/буудаллах) гэдэг үгэнд анхаарлаа хандуулж F зургийг тулгаарай.'),
  ('7a19860a-8cca-4a56-a607-b742ee0532a0'::uuid, 'Бичлэгт 请在下面写上你的名字。好的,是这里吗? (Доор нэрээ бичнэ үү. За, энд мөн үү?) гэсэн яриа сонсогдож байна. Хариулт A гэж өгөгдсөн тул A зурагт бичиж буй, гарын үсэг зурж буй дүр харагдах ёстой. 写 (бичих) гэдэг үгэнд тулгуурлан A зургийг олоорой.'),
  ('aae6858e-1a20-4f27-8fbd-07280bff2697'::uuid, 'Бичлэгт 你在学习开车? 是的,学了三个星期了 (Чи машин жолоодохыг сурч байна уу? Тийм, гурван долоо хоног сурсан) гэсэн яриа сонсогдож байна. Хариулт D гэж өгөгдсөн тул D зурагт машин жолоодож буй дүр харагдах ёстой. 开车 (машин жолоодох) гэдэг түлхүүр үгэнд тулгуурлан D зургийг тулгаж баталгаажуулаарай.'),
  ('d92a68c6-0d78-49c9-805d-d240c9595f08'::uuid, 'Бичлэгт 小月,明天上午九点见,再见 (Сяоюэ, маргааш өглөө есөн цагт уулзая, баяртай!) гэж хэлээд, 他们明天几点见? (Тэд маргааш хэдэн цагт уулзах вэ?) гэж асуусан байна. 九点 (есөн цаг) гэдгээс шууд A буюу 9:00 гэдэг хариулт зөв гэдгийг батлана. B (11:00), C (19:00) нь бичлэгт огт дурдагдаагүй тул буруу.'),
  ('ef25fc40-9c2a-481a-bfb7-31ce49a02f67'::uuid, 'Бичлэгт эмэгтэй 对不起,我不爱喝茶,有热水吗? (Уучлаарай, би цай уухыг дургүй, халуун ус байна уу?) гэж хэлж, 她想喝什么? (Тэр юу уухыг хүсэж байна вэ?) гэж асуусан байна. 有热水吗 гэдгээс тэр 热水 (халуун ус) хүссэн нь тодорхой тул хариулт C зөв. A (茶/цай) яг эсрэгээрээ дургүй гэж хэлсэн тул хамгийн андуурмаар боловч буруу сонголт юм.'),
  ('6ce510db-9e9e-4014-a15a-c062a7c98d20'::uuid, 'Бичлэгт эмэгтэй 谢谢你!我现在好多了 (Баярлалаа! Би одоо ихээхэн дээрдлээ) гэж хэлж, 她现在怎么样? (Тэр одоо ямар байна вэ?) гэж асуусан байна. 好多了 (ихээхэн дээрдлээ) гэдгээс шууд B хариулт зөв гэдгийг батална. A (баяргүй) нь эсрэг утгатай тул огт таарахгүй.'),
  ('95130802-0dd7-49a0-bc73-2626d6b8f4e6'::uuid, 'Бичлэгт 女儿没在家,她和同学去看电影了 (Охин гэртээ байхгүй, тэр ангийн найзтайгаа кино үзэхээр явсан) гэж хэлж, 女儿去哪儿了? (Охин хаашаа явсан бэ?) гэж асуусан байна. 看电影 (кино үзэх) гэдгээс тэр 电影院 (кино театр) руу явсан гэдгийг ойлгож болно, тиймээс C зөв. A (饭馆儿/ресторан), B (火车站/галт тэрэгний буудал) бичлэгт огт дурдагдаагүй.'),
  ('8bd7e262-0bff-42b3-82d5-0847e596f489'::uuid, 'Бичлэгт 王老师来了,她坐在后面 (Багш Ван ирлээ, тэр хойно суусан) гэж хэлж, 谁坐在后面? (Хэн хойно сууж байна вэ?) гэж асуусан байна. 王老师 (багш Ван) гэдгээс шууд A хариулт зөв гэдгийг батална. B (王小姐) болон C (түүний оюутан) бичлэгт дурдагдаагүй тул буруу.'),
  ('8eebc2ba-5283-4f43-b7ac-bd591fba4137'::uuid, 'Бичлэгт 现在开始第一题 (Одоо нэгдүгээр асуулт эхэлж байна) гэж хэлээд, 左边的比右边的大 (зүүн талынх нь баруун талынхаас том) гэсэн өгүүлбэрийг хоёр удаа давтсан байна. Хариулт нь √ (зөв) гэж өгөгдсөн тул зурагт яг зүүн талын зүйл баруун талынхаас том дүрслэгдсэн байх ёстой. 左, 右, 大 гэдэг үгсийг зурагтай тулгаж шалгаарай.'),
  ('421fd85c-0f9c-4461-a9c5-c7302cfac50e'::uuid, 'Бичлэгт 看,小张跑了第一 (Хараач, Жижиг Жан гүйлтэнд нэгдүгээр байр эзэлсэн) гэж хэлсэн байна. Хариулт нь √ (зөв) гэж өгөгдсөн тул зурагт хүн гүйж түрүүлж буюу тэргүүлж буй дүр харагдах ёстой. 跑了第一 (гүйж нэгдүгээрт орсон) гэдэг утгыг зурагтай тулгаж баталгаажуулаарай.'),
  ('4f992d15-53f1-4b36-8120-1e089dc5aa5d'::uuid, 'Бичлэгт 三,他们两个唱得真好 (Гурав, тэд хоёр маш сайхан дуулж байна) гэж хэлсэн байна. Хариулт нь × (буруу) гэж өгөгдсөн тул зурагт хоёр хүн дуулж бус өөр үйлдэл хийж байгаа, эсвэл ганц хүн байгаа дүр харагдах магадлалтай. 唱 (дуулах) гэдэг үгийг зурагтай тулгаж, таарахгүй байгааг олоорой.'),
  ('95aacc0a-7467-42d3-a35f-bf8c5e44af7f'::uuid, 'Бичлэгт 四,衣服洗完了吗? (Дөрөв, хувцас угаагдаж дуусав уу?) гэсэн асуултыг хоёр удаа давтсан байна. Хариулт нь √ (зөв) гэж өгөгдсөн тул зурагт угаасан хувцас эсвэл угаалгатай холбоотой дүр харагдах ёстой. 洗衣服 (хувцас угаах) гэдэг утгыг зурагтай тулгаарай.'),
  ('752d333e-fd4a-42cd-9189-8172dc1fac28'::uuid, 'Бичлэгт 五,他正在看报纸 (Тав, тэр яг одоо сонин уншиж байна) гэж хэлсэн байна. Хариулт нь × (буруу) гэж өгөгдсөн тул зурагт хүн сонин бус өөр зүйл (ном, утас гэх мэт) харж байгаа дүр харагдах магадлалтай. 报纸 (сонин) гэдэг үгийг зурагтай тулгаж, таарахгүй байгааг олоорой.'),
  ('24f0cd9f-bf3c-415b-8b67-85ccd036f43b'::uuid, 'Бичлэгт 六,这个门怎么打不开? (Зургаа, энэ хаалга яагаад нээгдэхгүй байна вэ?) гэж хэлсэн байна. Хариулт нь √ (зөв) гэж өгөгдсөн тул зурагт хүн хаалга онгойлгож чадахгүй зовж буй дүр харагдах ёстой. 打不开 (нээгдэхгүй байна) гэдэг утгыг зурагтай тулгаж баталгаажуулаарай.'),
  ('c50be0ca-ae03-4f86-97d3-2b816fa91c95'::uuid, 'Бичлэгт 七,足球在那儿,椅子下面 (Долоо, хөлбөмбөгийн бөмбөг тэнд, сандлын доор байна) гэсэн өгүүлбэрийг хоёр удаа давтсан байна. Хариулт нь × (буруу) гэж өгөгдсөн тул зурагт бөмбөг сандлын доор биш өөр газар байгаа дүр харагдах магадлалтай. 椅子下面 (сандлын доор) гэдэг байршлын үгийг зурагтай тулгаарай.'),
  ('28fbe073-6137-4dc4-b8c1-123674ca884e'::uuid, 'Бичлэгт 你笑什么呢?这么高兴! (Чи юунд инээж байна вэ? Ийм их баяртай юм!) гэж хэлсэн байна. Хариулт нь √ (зөв) гэж өгөгдсөн тул зурагт хүн инээж, баяртай дүр харагдах ёстой. 笑 (инээх), 高兴 (баяртай) гэдэг үгсийг зурагтай тулгаж баталгаажуулаарай.'),
  ('9c78bd05-af0f-43fe-966d-96a6feead119'::uuid, 'Бичлэгт 九,我和姐姐都很喜欢猫 (Ес, би болон эгч хоёулаа муурыг маш их таалдаг) гэсэн өгүүлбэрийг хоёр удаа давтсан байна. Хариулт нь × (буруу) гэж өгөгдсөн тул зурагт муур бус өөр амьтан дүрслэгдсэн, эсвэл өөр агуулга харагдах магадлалтай. 猫 (муур) гэдэг үгийг зурагтай тулгаж, таарахгүй байгааг олоорой.'),
  ('c30f2235-a84c-4410-b10b-b836e734fd6b'::uuid, 'Бичлэгт 十,教室里一个学生都没有 (Арав, ангид нэг ч сурагч байхгүй) гэж хэлсэн байна. Хариулт нь × (буруу) гэж өгөгдсөн тул зурагт ангид сурагчид байгаа дүр харагдах магадлалтай, өөрөөр хэлбэл бичлэгийн үгтэй эсрэгээрээ. 一个学生都没有 (нэг ч сурагч байхгүй) гэдэг утгыг зурагтай тулгаж баталгаажуулаарай.'),
  ('ce151155-5074-4963-b902-eb0249baee59'::uuid, 'Бичлэгт 十一,没有茶了,喝杯咖啡吧。好的 (Арван нэг, цай дууссан, кофе уучих. За) гэсэн яриа сонсогдож байна. Хариулт A гэж өгөгдсөн тул A зурагт кофе уучиж буй дүр харагдах ёстой. 咖啡 (кофе) гэдэг түлхүүр үгэнд тулгуурлан A зургийг тулгаж баталгаажуулаарай.'),
  ('434501ba-3413-46f7-95fa-e33d6a45aeea'::uuid, 'Бичлэгт 十二,喂,东西买好了吗? 买好了,你在哪儿呢? (Арван хоёр, байна уу, зүйлсээ худалдаж авч дуусав уу? Авсан, чи хаана байна?) гэсэн утасны яриа сонсогдож байна. Хариулт B гэж өгөгдсөн тул B зурагт утсаар ярьж буй, эсвэл худалдаж авсан зүйлтэй дүр харагдах ёстой. 买 (худалдаж авах), 你在哪儿 (чи хаана байна) гэдэг үгсэд тулгуурлан B зургийг олоорой.'),
  ('23e3fdaa-03dd-4cca-8da0-5cb2e5f8fc6b'::uuid, 'Бичлэгт 十三,你看,我们是不是走错了? 没有,我来过这儿,就是向右走 (Арван гурав, хараач, бид зам андуурчихсан юм биш үү? Үгүй, би энд ирж байсан, зүгээр баруун тийш яв) гэсэн яриа сонсогдож байна. Хариулт F гэж өгөгдсөн тул F зурагт хүмүүс зам заах эсвэл замд явж буй дүр харагдах ёстой. 向右走 (баруун тийш явах) гэдэг үгэнд тулгуурлан F зургийг олоорой.'),
  ('75d1f15b-17d0-4920-9064-4cc01c9a554d'::uuid, 'Бичлэгт 十四,还有多少个题? 还有不少,可能要做到中午 (Арван дөрөв, хэдэн даалгавар үлдсэн бэ? Бас нилээд байна, өдийн цаг хүртэл хийх байх) гэсэн яриа сонсогдож байна. Хариулт C гэж өгөгдсөн тул C зурагт даалгавар хийж, бодож буй дүр харагдах ёстой. 做题 (даалгавар хийх) гэдэг утгад тулгуурлан C зургийг олоорой.'),
  ('26dcf275-fa0a-4dbf-a371-aa298937e86e'::uuid, 'Бичлэгт 十五,好点了吗? 上午吃了药,好多了 (Арван тав, дээрдсэн үү? Өглөө эм уусан, ихээхэн дээрдлээ) гэсэн яриа сонсогдож байна. Хариулт E гэж өгөгдсөн тул E зурагт өвчтэй, эм уусан хүний дүр харагдах ёстой. 吃药 (эм уух), 好多了 (дээрдлээ) гэдэг үгсэд тулгуурлан E зургийг олоорой.'),
  ('a940405c-beba-49ab-9e65-03ed97029e7e'::uuid, 'Бичлэгт 十六,对不起,我来晚了。 没关系,快请进吧 (Арван зургаа, уучлаарай, орой ирлээ. Зүгээр ээ, ороод ир) гэсэн яриа сонсогдож байна. Хариулт A гэж өгөгдсөн тул A зурагт хүн орж ирж буй, угтаж буй дүр харагдах ёстой. 请进 (ороод ир) гэдэг үгэнд тулгуурлан A зургийг олоорой.'),
  ('a20984bc-1441-4ab3-97d0-5fd2464bffd6'::uuid, 'Бичлэгт 十七,你游得真好! 什么时候学的? 七岁,到现在已经二十多年了 (Арван долоо, чи маш сайн сэлж байна! Хэзээ сурсан бэ? Долоон настайдаа, одоо хүртэл хорь гаруй жил боллоо) гэсэн яриа сонсогдож байна. Хариулт D гэж өгөгдсөн тул D зурагт сэлж буй дүр харагдах ёстой. 游 (сэлэх) гэдэг үгэнд тулгуурлан D зургийг олоорой.'),
  ('c0ad005a-46fd-4cc8-bb21-22e245491bef'::uuid, 'Бичлэгт 十八,女儿去学校了? 没有,她今天没课,还没起床 (Арван найм, охин сургууль явсан уу? Үгүй, өнөөдөр хичээлгүй, одоо хүртэл босоогүй байна) гэсэн яриа сонсогдож байна. Хариулт B гэж өгөгдсөн тул B зурагт хэвтэж буй эсвэл дөнгөж сэрж буй хүний дүр харагдах ёстой. 没起床 (босоогүй байна) гэдэг үгэнд тулгуурлан B зургийг олоорой.'),
  ('b0cbcf35-cbe8-4f5f-a6d5-9f65e74a2454'::uuid, 'Бичлэгт 十九,谢谢你送我回来,路上慢点开。 好的,再见! (Арван ес, намайг хүргэж өгсөнд баярлалаа, замдаа аажуу яв. За, баяртай!) гэсэн яриа сонсогдож байна. Хариулт E гэж өгөгдсөн тул E зурагт машинаар хүргэж өгч, салах ёс гүйцэтгэж буй дүр харагдах ёстой. 送我回来 (намайг хүргэж өгөх) гэдэг үгэнд тулгуурлан E зургийг олоорой.'),
  ('871b0c9a-7af8-4e4c-9919-08f2db5984ab'::uuid, 'Бичлэгт 二十,西瓜是八斤,十二块钱。 给你十五,你找我三块吧 (Хорь, тарвас найман жин, арван хоёр юань. Чамд арван таваа өглөө, гурван юаниа буцааж өг) гэсэн яриа сонсогдож байна. Хариулт C гэж өгөгдсөн тул C зурагт тарвас худалдаж авч, мөнгө тоолж буй дүр харагдах ёстой. 西瓜 (тарвас), 钱 (мөнгө) гэдэг үгсэд тулгуурлан C зургийг олоорой.'),
  ('8a079e2f-a56b-4301-854f-cc0d92123dc3'::uuid, 'Эрэгтэй хүнээс өчигдөр авсан алимны тухай асуухад тэрээр «харахад сайхан ч тийм ч амттай биш» гэж хариулсан. Иймд зөв хариулт бол C «不太好吃» буюу амтгүй гэдэг нь тодорхой батлагдана. A «үнэтэй» ба B «жижиг» тухай бичлэгт огт дурдаагүй тул буруу.'),
  ('671bee3a-0633-435f-83eb-b59f96f4e48c'::uuid, 'Нэг хүн «усан онгоцоор тийшээ явъя» гэж санал болгоход нөгөө нь «сайн байна, чиний хэлснээр» гэж зөвшөөрсөн. Тиймээс тэд усан онгоцоор явахаар шийдсэн нь тодорхой тул зөв хариулт B «坐船». Явган явах, такси зэргийг бичлэгт огт дурдаагүй тул A, C буруу.'),
  ('bc45cb06-80b4-4d6c-b855-d8d9c48ef6e9'::uuid, 'Нэг хүн «309 тоот өрөө хаана байна?» гэж асуухад нөгөө нь «би ч бас мэдэхгүй, үйлчлэгчээс асуицгаая» гэж хариулсан. Энэ нь тэд яг 309 тоот өрөөг хайж байгааг тодорхой харуулж байгаа тул зөв хариулт A «309». B «406», C «503» тоог бичлэгт огт дурдаагүй.'),
  ('aa8632f3-022d-42ef-8ff2-15eea15bcdbf'::uuid, 'Эрэгтэй нь эмэгтэйгээс «чи өдөр дундаа бүжиг сурахаар явна уу?» гэж асуухад тэрээр «тийм, хоёр цагт хичээл эхэлнэ» гэж баталсан. Энэ хариултаас эмэгтэй бүжиг сурах хичээлд явахаар төлөвлөж байгаа нь тодорхой тул зөв хариулт A «跳舞». B «хятад хэл сурах», C «унадаг дугуй авах» тухай огт дурдаагүй.'),
  ('24c07ea1-4264-4a2f-8e9d-ce6524ac2e85'::uuid, 'Асуулт эмнэлгийн зөвлөгөөний тухай. Эрэгтэй хүн «эмч миний нүд гэмтэлгүй, хэдэн өдөр сайн амарвал болно гэсэн» гэж хэлж байна. Иймд эмч түүнд ихэвчлэн амарахыг зөвлөсөн нь тодорхой тул зөв хариулт B «多休息». A «их хөдөлгөөн хийх», C «их ус уух» тухай эмч огт хэлээгүй.'),
  ('22a0eb67-469e-4d00-ba6d-72d6b7eecec1'::uuid, 'Ажилтан харилцагчаас «танд юугаар туслах вэ?» гэж эелдгээр асуухад тэрээр «энэ хар өнгийн цагийг үзмээр байна» гэж хариулжээ. Цаг зардаг газар бол ихэвчлэн дэлгүүр байдаг тул зөв хариулт C «商店». Ангид цаг зардаггүй, рестораны ажилтан ч ингэж асуудаггүй тул A, B буруу.'),
  ('f0c770d8-d662-4d77-877c-567ddca88750'::uuid, 'Эмэгтэй хүн «энэ сарын ажил дуусмагц би аялахаар явна» гэж хэлж байгаа бол нөгөө хүн «хаашаа явахаар төлөвлөж байгаа юм бэ?» гэж асуусан. Энэ нь эмэгтэй аялахыг хүсэж байгааг тодорхой харуулж байгаа тул зөв хариулт B «想去旅游». Тэр бүү ярь гэж хэлээгүй, мөн ажил их байгаа гэж бус харин удахгүй дуусна гэж хэлсэн тул A, C буруу.'),
  ('48abbac0-f891-47c2-a648-17cf6a937c87'::uuid, 'Асуулт бол Сяо Бай хэрхэн хайртай залуутайгаа танилцсан тухай. Тэрээр «ангийн найз маань танилцуулсан, тэд хоёр нэг компанид ажилладаг» гэж хэлсэн. Тиймээс түүнийг ангийн найз нь танилцуулсан нь тодорхой тул зөв хариулт C «她同学». Дүү эсвэл эгч тухай огт дурдаагүй тул A, B буруу.'),
  ('b4d67453-0c99-4f5e-8e0e-ad1946ed203f'::uuid, 'Нэг хүн кофе шоп энд ойрхон уу гэж асуухад нөгөө нь «алс биш, маш ойрхон, явган явж болно» гэж хариулсан. Ярианаас тэд яг тэр кофе шопруу явах гэж байгаа нь тодорхой тул зөв хариулт B «咖啡馆儿». Компани, кино театр тухай огт дурдаагүй тул A, C буруу.'),
  ('8c619b0d-e9fa-4974-a9f1-4169bae524e4'::uuid, 'Асуулт эмэгтэйн нөхөр яагаад ирээгүйг тодруулж байна. Тэрээр «тэр бямба гарагт ч ажилдаа явах ёстой болсон тул би ганцаараа ирлээ» гэж тайлбарласан. Иймд нөхөр нь ажилтай, цаг зав байгаагүй нь тодорхой тул зөв хариулт A «没时间». Өвчилсөн, бөмбөг тоглох тухай огт дурдаагүй тул B, C буруу.'),
  ('9f299e73-2f05-43ba-83c6-0a37a18dd154'::uuid, 'Хүү ээждээ «ангийн найзтайгаа сагсан бөмбөг тоглохоор явлаа» гэж хэлэхэд ээж нь «оройтож бүү ир» гэж захисан. Хүү нь «хоёр цаг тоглоод дөрвөн цагт эргэж ирнэ» гэж баталсан тул зөв хариулт C «16:00» (дөрвөн цаг). A «12:00», B «14:00» тухай хэлээгүй.'),
  ('3d24215b-932a-44dc-bab2-9bd3a2ea6a33'::uuid, 'Асуулт маргаашийн цаг агаарын тухай. Телевизээр «маргааш их цас орно» гэж мэдээлсэн бөгөөд иймд гадаа хүйтэн байх тул илүү дулаан хувцас өмсөх хэрэгтэй гэж ярьж байна. Тиймээс зөв хариулт C «会下雪» (цас орно). Наран гарах, бороо орох тухай огт дурдаагүй тул A, B буруу.'),
  ('a4708ab5-1213-458b-983f-df731916ae3b'::uuid, 'Асуулт кино театр хаана байрладагийг тодруулж байна. Тэд «сургуулийн хажууд шинээр нээгдсэн кино театр» гэж хариулсан тул зөв хариулт B «学校旁边». Эмнэлгийн ард, эмийн сангийн урд тухай огт дурдаагүй тул A, C буруу.'),
  ('2e384cc3-2420-4cb2-9343-6f691769b8e4'::uuid, 'Асуулт аравны өдөр хэний төрсөн өдөр болохыг тодруулж байна. Ярианд «10-ны өдөр бол охины нь төрсөн өдөр» гэж шууд хэлсэн тул зөв хариулт A «女儿». Ээж, аав тухай огт дурдаагүй тул B, C буруу.'),
  ('13f0e6a1-3f9c-47d3-aa59-a0c08a58df4c'::uuid, 'Асуулт Сяо Гао ямар хоол дуртайг тодруулж байна. Ярианд «тэр загас идэх дуртай гэж сонссон, загас ав» гэж шууд хэлсэн тул зөв хариулт A «鱼». Өндөг, будаа зэргийг зөвхөн нэмж авах хоол болгон дурдсан бөгөөд Сяо Гаогийн дуртай хоол биш тул B, C буруу.'),
  ('382ae4c5-1114-41d4-9754-aede49260471'::uuid, 'Бичлэгт «аль хэдийн есөн цаг таван минут боллоо, хүү чинь одоо ч унтаж байна уу?» гэж асуухад «тэр эрт босчихсон, одоо шүдээ угааж, нүүрээ угааж байна» гэж хариулсан. Энэ дүрслэлтэй тохирох зургийг сонгож тулгаж үз.'),
  ('ff9ba5fb-0a25-4263-93d7-8c61ae0a2ff6'::uuid, 'Бичлэгт «хятад хэлний ном хаана байгааг харсан уу, би дасгалаа хийх гэсэн юм» гэж асуухад «сандал дээр ном байна, чинийх үү?» гэж хариулсан. Энэ дүрслэлтэй тохирох зургийг сонгож тулгаж үз.'),
  ('0ab4b4c2-ef55-4011-9cbc-a3522922868f'::uuid, 'Бичлэгт «тэр цэцэрлэгт хүрээлэн бидний байгаа газраас хол уу?» гэж асуухад «маш ойрхон, бид энд байгаа тул явган хорин минутад хүрч болно» гэж хариулсан. Энэ дүрслэлтэй тохирох зургийг сонгож тулгаж үз.'),
  ('5d93f80d-b5b3-42cb-ba1e-29a24259b9fa'::uuid, 'Бичлэгт «морь унахыг хэнээс сурсан бэ?» гэж асуухад «өвөөгөөс, тэр морь унахад их дуртай бөгөөд маш сайн унадаг» гэж хариулсан. Энэ дүрслэлтэй тохирох зургийг сонгож тулгаж үз.'),
  ('e12c8b06-a1d2-4127-b015-e593f54a33e2'::uuid, 'Бичлэгт «энэ дэлгүүрийн жүүс маш амттай!» гэхэд «тийм ээ, тэдний талх ч бас сайн, амталж үз» гэж хариулсан. Энэ дүрслэлтэй тохирох зургийг сонгож тулгаж үз.')
) as v(id, explanation)
 where t.id = v.id;

update mock_test_questions as t
   set explanation_mn = v.explanation
  from (values
  ('558ae355-1a2e-4dee-b962-9aca522d13fa'::uuid, 'Бичлэгт «пасспортоо чемоданд хийсэн үү?» гэж асуухад «үгүй, миний цүнхэнд байна, ингэж авахад хялбар» гэж хариулсан. Энэ дүрслэлтэй тохирох зургийг сонгож тулгаж үз.'),
  ('8d435574-312f-4733-8df1-7cf26d6f9d2a'::uuid, 'Бичлэгт «Сяо Сяог бамбарууш үзэхээр хэзээ дагуулж явах вэ?» гэж асуухад «оройдоо явъя, өглөө дэлгүүрт орж чийдэн авмаар байна» гэж хариулсан. Энэ дүрслэлтэй тохирох зургийг сонгож тулгаж үз.'),
  ('f3ac0913-2517-420c-9d37-bcf0d8aa389f'::uuid, 'Бичлэгт «маш хүйтэн байна! Хараач, чиний хамар час улаан боллоо!» гэхэд «тийм ээ, өнөөдөр ийм их салхи шуурна гэж бодоогүй» гэж хариулсан. Энэ дүрслэлтэй тохирох зургийг сонгож тулгаж үз.'),
  ('093b2177-fbf5-446d-a7df-16d3b678b261'::uuid, 'Бичлэгт «хөл чинь ямар байна, гүйж чадах уу?» гэж асуухад «зүүн хөл маань одоо ч их өвдөж байна, би жаахан амарья, чи түрүүлж гүй» гэж хариулсан. Энэ дүрслэлтэй тохирох зургийг сонгож тулгаж үз.'),
  ('6e613f27-a202-4de3-9bf0-752c1d788832'::uuid, 'Бичлэгт «энэ зургийг хэзээ авахуулсан бэ, үнэхээр өхөөрдөм байна!» гэхэд «найман настайдаа, бага сургуулийн хоёрдугаар ангид байхдаа авахуулсан, тэр үед би богино үстэй байсан» гэж хариулсан. Энэ дүрслэлтэй тохирох зургийг сонгож тулгаж үз.'),
  ('efc7ce7c-8968-4699-9e63-847c40a115da'::uuid, 'Бичлэгт худалдагч «энэ бол таны авсан усан үзэм, гадил, нийт 38 юань тавин мөнгө» гэж тодорхой хэлсэн. Харин өгүүлбэрт «тэр 105 юань зарцуулсан» гэж байгаа нь бичлэгийн дүнгээс огт өөр тул энэ өгүүлбэр буруу (×).'),
  ('c3881be6-3aa7-4447-900c-a85559fbd768'::uuid, 'Бичлэгт «энэ нохой бол миний дүүгийн, тэр Нанжинд хуралд явсан тул хэдэн өдөр над дээр асруулахаар үлдээсэн» гэж тодорхой хэлсэн. Энэ нь өгүүлбэртэй яг таарч байгаа тул зөв (√).'),
  ('814fcdeb-a55f-4082-9ca8-42b3798c66e8'::uuid, 'Бичлэгт «түр битгий сандар, бид хамтдаа шийдвэрлэх аргыг эрэлхийлье, хамгийн хэцүү асуудлыг эхлээд шийдвэл бусад нь хялбар болно» гэсэн нь одоо шийдвэрлэсэн гэсэн үг биш, харин хамтдаа шийдэх төлөвлөгөөг л илэрхийлж байна. Иймд «асуудлыг шийдвэрлэсэн» гэсэн өгүүлбэр буруу (×).'),
  ('e8347a12-1e0a-43ab-bbd8-1af2d7a43fa0'::uuid, 'Бичлэгт «Сяо Ван маш ухаалаг, юмыг маш хурдан сурдаг, ялангуяа сонирхолтой зүйлээ нэг л удаа үзээд сурчихдаг» гэж хэлсэн. Энэ нь өгүүлбэрт байгаа «удаан сурдаг» гэдэгтэй яг эсрэг тул буруу (×).'),
  ('7c9dfe6a-7517-44ec-8d20-31da6b4a172e'::uuid, 'Бичлэгт «гунигтай үед хөгжим сонсох, тоглоом тоглох, дасгал хийх зэрэг өөрийгөө баярлуулах зүйл хийх нь сайн сонголт» гэж хэлсэн. Хөгжим сонсох нь дуу сонсохтой утга дүйцэх тул өгүүлбэр зөв (√).'),
  ('4f1d5934-2376-44f4-851c-17e5f2ff5d3b'::uuid, 'Бичлэгт «охин маань дөнгөж сая утасдаад, өнөөдөр ажлаас гарсны дараа найзтайгаа кино үзэхээр явна, орой хооллохоор ирэхгүй тул биднийг хүлээхгүй байхыг хүссэн» гэж хэлсэн. Энэ нь өгүүлбэртэй яг таарч байгаа тул зөв (√).'),
  ('557c288f-194b-44ef-b1ce-1e1bc68120bc'::uuid, 'Бичлэгт «математикийн хичээлтэй харьцуулбал би түүхийн хичээлд илүү дуртай, учир нь олон түүхийн түүх маш сонирхолтой» гэж хэлсэн. Иймд тэр математикийн хичээлд бус, харин түүхийн хичээлд илүү дуртай тул өгүүлбэр буруу (×).'),
  ('2c350cac-c347-43e6-bb0c-26df9153ba3f'::uuid, 'Бичлэгт «Ли гуайн ажлын өрөө урьд нь дөрөвдүгээр давхарт байсан бөгөөд саяхан арван хоёрдугаар давхарт нүүсэн» гэж тодорхой хэлсэн. Энэ нь ажлын өрөөгөө сольсон гэсэн үг тул өгүүлбэр зөв (√).'),
  ('1926159d-a977-4d83-a8cd-c73b860e886a'::uuid, 'Бичлэгт «Жан авга бол манай гэр бүлийн хөрш бөгөөд мөн аавын минь хамт ажилладаг хүн» гэж хэлсэн. Тэр аавын ангийн найз биш, харин хамт ажилладаг хүн тул өгүүлбэрт байгаа «ангийн найз» гэдэг нь буруу (×).'),
  ('a9d4d0e0-110e-4f46-b47f-77b9b6cd59b1'::uuid, 'Бичлэгт «улирал бүр өөрийн гэсэн өнгөтэй, хавар ногоон, зун улаан, намар шар, өвөл цагаан. Дөрвөн улирлын өнгө өөр өөр ч бүгд маш үзэсгэлэнтэй» гэж хэлсэн. Хавар ч мөн үзэсгэлэнтэй гэдэгт багтсан тул өгүүлбэр зөв (√).'),
  ('aad9d323-b16d-4a70-9c8e-c15fdbb1b5f9'::uuid, 'Хоёр аргын аль нэгийг сонгохыг санал болгоход нэг нь «усан онгоцоор явъя, би хараахан суугаагүй байна» гэж хэлж, усан онгоцоор явахыг сонгосон. Тиймээс зөв хариулт A «坐船». Онгоц, метроны тухай тэр огт сонгоогүй тул B, C буруу.'),
  ('b8fec103-81db-439c-90e9-2bdab0d4371b'::uuid, 'Асуулт эмэгтэйн тухай юу мэдэж болохыг тодруулж байна. Тэрээр «тийм ээ, гадаадад сурахаар явна, эцэг эх маань зөвшөөрсөн, залуу насандаа их явж үзэх ёстой гэж хэлсэн» гэж хариулсан. Тиймээс тэр гадаадад явахаар болсон нь тодорхой тул зөв хариулт B «要出国». Уйлах, хүмүүст туслах тухай огт дурдаагүй тул A, C буруу.'),
  ('8b9770cb-6275-42b5-b4f8-2b018582f2f0'::uuid, 'Нэг хүн «миний хэлснийг ойлгосон уу?» гэж асуухад нөгөө нь «уучлаарай, би ойлгосонгүй, жаахан удаан ярина уу?» гэж хариулсан. Энэ нь тэр яриаг сонсоод ойлгоогүй байгааг тодорхой харуулж байгаа тул зөв хариулт A «没听明白». Дасгал хэцүү байх, путунхуа ярьж чадахгүй байх тухай огт дурдаагүй тул B, C буруу.'),
  ('3612e567-1647-451f-9d40-baef82713207'::uuid, 'Эмэгтэйгээс энд байнга ажиллах уу гэж асуухад тэрээр «үгүй, нөхөр минь ирэх онд хойд нутагт ажиллахаар буцна, би түүнтэй хамт буцна» гэж хариулсан. Тиймээс түүний төлөвлөгөө хойд нутагруу буцах явдал тул зөв хариулт A «回北方». Байшин зарах, ажиллаж сурах тухай огт дурдаагүй тул B, C буруу.'),
  ('7eaff631-9e2b-446e-82dc-9cee0d7014b9'::uuid, 'Асуулт эрэгтэй яагаад ТВ бага үздэгийг тодруулж байна. Тэрээр «үзсэнгүй, би сүүлийн үед дараа долоо хоногийн тэмцээндээ бэлдэж завгүй, ТВ бараг үздэггүй» гэж хэлсэн. Тиймээс зөв хариулт C «要准备比赛». Хичээл давтах, нэвтрүүлэг сайхан биш тухай огт дурдаагүй тул A, B буруу.'),
  ('4552813a-89c4-4727-8b37-65c71cc32693'::uuid, 'Эрэгтэй хүн энэ утас үнэхээр сайхан байна гэхэд «би ч бас дүү охиндоо нэгийг авмаар байна» гэж хэлсэн. Тиймээс тэр дүү охиндоо утас өгмөөр байгаа нь тодорхой тул зөв хариулт C «妹妹». Ээж, эгч тухай огт хэлээгүй тул A, B буруу.'),
  ('c24e4a0b-74a1-4c80-bc77-d028ea0ef423'::uuid, 'Нэг хүн энэ гутал ямар вэ гэж асуухад нөгөө нь «надад хар өнгийн хэдэн хос гутал бий, өөр зүйл харцгаая» гэж хэлсэн. Гутал сонгож байгаа нь тэд дэлгүүрт байгааг харуулж байгаа тул зөв хариулт A «商店». Онгоцны буудал, галт тэрэгний буудалд гутал сонгодоггүй тул B, C буруу.'),
  ('d3f259c2-3b24-4dd7-8af0-1fb9f48bc8f6'::uuid, 'Асуулт Ван Дунгийн тухай юу мэдэж болохыг тодруулж байна. «Түүнд утасдсан, тэр ангид юм авахаар орсон, удахгүй ирнэ гэж хэлсэн» гэсэн үгнээс тэр одоогоор ирээгүй байгаа нь тодорхой тул зөв хариулт B «还没来». Захидал бичиж байгаа, хариулж чадахгүй байгаа тухай огт дурдаагүй тул A, C буруу.'),
  ('a3b1a77a-2a0e-4dba-bd57-f0d7d919f92b'::uuid, 'Нэг хүн «Лао Ли» гэж нэрээр дуудаж ажил цагтаа дуусах эсэхийг асуухад нөгөө нь «менежер ээ, санаа зоволтгүй» гэж хариулсан. «Менежер» гэдэг үгнээс тэдний хамт ажилладаг харилцаа тодорхой тул зөв хариулт A «同事». Нөхөр эхнэр, багш сурагч тухай огт дурдаагүй тул B, C буруу.'),
  ('16dab4a5-3340-404c-8292-c8f29424d950'::uuid, 'Сонин уншиж байгаа хүнээс өнөөдрийн мэдээ юу байгааг асуухад «сонинд өчигдрийн их цаснаас болж олон онгоц хоцорсон» гэж бичсэн байна гэж хэлсэн. Тиймээс өчигдөр их цас орсон нь тодорхой тул зөв хариулт B «下雪了». Нартай, бороотой байсан тухай огт дурдаагүй тул A, C буруу.'),
  ('e0607410-454e-4725-b254-4492b6f71c7f'::uuid, 'Асуулт кино хэдэн цагт эхлэхийг тодруулж байна. «Кино арван цаг арван таван минутад эхэлнэ, дөнгөж таван минут үлдлээ» гэж тодорхой хэлсэн тул зөв хариулт B «10:15». A «10:05», C «10:30» бол огт дурдаагүй.'),
  ('4f12ad8a-a9bc-4381-a2f7-e1ccc0573aa2'::uuid, 'Эрэгтэй хүн имэйл харсан эсэхийг асуухад «үгүй ээ, өнөөдөр өдөржин гадаа ажилтай явж, интернэт орж чадаагүй» гэж тайлбарласан. Иймд тэр интернэт орох цаг завгүй байсан нь тодорхой тул зөв хариулт C «没时间上网». Уулзалт хийж байсан, компьютер эвдэрсэн тухай огт дурдаагүй тул A, B буруу.'),
  ('323f24b2-5957-4203-8c2c-8f4eb3ca3c58'::uuid, 'Асуулт эмэгтэй энэ өгүүллэгийг хэрхэн бичсэнийг үнэлж байгааг тодруулж байна. Тэрээр «сайн байна, би их сэтгэл ханамжтай байна, гэхдээ жаахан анхаарах цөөн асуудал бий» гэж хэлсэн. Ерөнхийдөө эерэг үнэлгээ өгсөн тул зөв хариулт A «不错». Дундаж, муу гэж шууд хэлээгүй тул B, C буруу.'),
  ('e4097a52-31e8-49dd-9a28-ad5b7c833d6d'::uuid, 'Ярианд хонины мах цөөвтөр байна уу гэдгийг ярилцаад дараа нь архины талаар «архи авах хэрэггүй, хөргөгчинд шар айраг арай хангалттай байна» гэж хэлсэн. Энэ нь архи худалдаж авах шаардлагагүй гэсэн үг тул зөв хариулт B «不用买酒». Мах чанар муу, ач холбогдолгүй тухай биш тул A, C буруу.'),
  ('383a8190-f0bb-40ca-b140-9b1381623dbd'::uuid, 'Эрэгтэй хүн эмчээс «би эмнэлгээс гарч болох уу?» гэж асуухад эмч «тийм, гэртээ сайн амарч, яаралгүй хөл бөмбөг тоглоорой» гэж зөвшөөрсөн. Тиймээс тэр эмнэлгээс гарах эрхтэй болсон нь тодорхой тул зөв хариулт C «可以出院了». Таргалсан, сагсан бөмбөгт дуртай тухай огт дурдаагүй тул A, B буруу.'),
  ('5ef557dc-a315-4363-950f-b155f1a3bbb5'::uuid, 'Асуулт эрэгтэй Бээжинд хэзээ ирэхийг тодруулж байна. Тэрээр «гуравдугаар сарын тавны өдөр, өөрөөр хэлбэл ирэх бямба гарагт» гэж тодорхой хэлсэн тул зөв хариулт A «3月5日». B «3月6日», C «6月7日» бол огт дурдаагүй.'),
  ('15c598b5-b14a-43e5-becc-eb365ae58057'::uuid, 'Асуулт эрэгтэй юу олсныг тодруулж байна. «Энэ малгай чинийх биш үү?» гэж асуухад «тийм, миний, баярлалаа» гэж хариулсан бөгөөд ангиас олсон гэдгийг тодорхой хэлсэн. Тиймээс зөв хариулт A «帽子». Таваг, юбка тухай огт дурдаагүй тул B, C буруу.'),
  ('8d890237-e2e7-4478-bdad-300ca18d86d3'::uuid, 'Асуулт эмэгтэйн тухай юу мэдэж болохыг тодруулж байна. «Такси ирлээ, би түрүүлж явлаа» гэж хэлсэн нь тэр таксинд суугаад гэртээ явж байгааг харуулж байна. Тиймээс зөв хариулт B «打车回家». Хөл өвдөж байгаа, машин авсан тухай огт дурдаагүй тул A, C буруу.'),
  ('005078a4-7171-4b0e-b6fb-8ae626736aaa'::uuid, 'Асуулт эрэгтэйд юу тохиолдсоныг тодруулж байна. Тэрээр «жаахан халуурч, толгой ч өвдөж байна, магадгүй ханиад хүрсэн байх» гэж хэлсэн. Энэ нь тэр биеэ тааруухан байгааг харуулж байгаа тул зөв хариулт C «身体不舒服». Цангасан, хоцорсон тухай огт дурдаагүй тул A, B буруу.'),
  ('4664c01d-4b84-46e9-b18d-7575f0d2d936'::uuid, 'Асуулт эрэгтэй тэр рестораныг хэрхэн үнэлж байгааг тодруулж байна. Тэрээр «орчин сайхан, хоол амттай бөгөөд үнэ ч хямд» гэж хэлсэн. Сонголтуудаас «хоол хямд» гэдэг нь хамгийн тохирч байгаа тул зөв хариулт C «菜比较便宜». Цэс хуучирсан, кофеор алдартай тухай огт дурдаагүй тул A, B буруу.'),
  ('22525b5d-0b9b-43fd-bdc6-0b0cc7776c75'::uuid, 'Бичлэгт хэлж буйгаар хэн нэгэн анх удаагаа морь унаж, хамтрагч нь бүү ай, энэ морь дуулгавартай, хөлөө сайн тавьж, нүдээрээ урагшаа хар гэж зааварлаж байна. Энэ бол морь унах дүр тул зурагтай тулгаж C сонголтыг шалгаарай.'),
  ('cbda2612-27a1-4f7a-acaa-39dd53ba2821'::uuid, 'Энэ хэсэгт хоёр малгайн аль нь илүү таалагдаж байгааг ярилцаж, эцэст нь цэнхэр өнгийнх нь илүү үзэсгэлэнтэй гэж шийдэж байна. Тиймээс малгай сонгож буй дүр зурагтай таарна — зурагтай тулгаж F сонголтыг шалгаарай.'),
  ('11e661ff-588a-4914-86db-49b161c69c73'::uuid, 'Энд нэг хүн номын санд явж, түүхийн талаарх хэдэн ном зээлэхээ хэлж, нөгөөх нь чи ч бас явна уу гэж асууж байна. Номын сан руу явж буй ярианы дагуу зурагтай тулгаж E сонголтыг шалгаарай.'),
  ('28776023-756f-4da2-b972-4d507a5eca0a'::uuid, 'Бичлэгт хэн нэгэн ханиад хүрсэн эсэхийг асуухад, өчигдөр хувцас цөөн өмссөнөөс болж өглөө хамар эвгүй болсныг хэлж байна. Ханиад хүрсэн шинж тэмдгийн тухай яриа тул зурагтай тулгаж A сонголтыг шалгаарай.'),
  ('9cecc855-a71b-49a4-b2f8-7cf9870c9c4b'::uuid, 'Өнөөдөр салхи хүчтэй, шүхэр хийсчих гээд байна, маргааш цаг агаар сайжрахыг хүсэж байгаагаа ярьж байна. Салхи, шүхэртэй холбоотой дүр тул зурагтай тулгаж B сонголтыг шалгаарай.'),
  ('059af7fa-45ba-4c07-9f47-7edd9f73c2e0'::uuid, 'Хэн нэгэн бялуу идэхээ больсныг асуухад, өмнө нь их дуртай байсан ч сүүлийн үед дахиад таргалсан тул идэхгүй байна гэж хариулж байна. Бялуу, жингийн тухай яриа учир зурагтай тулгаж E сонголтыг шалгаарай.'),
  ('91bc21ec-b0f0-4982-95ff-991a3174d9e6'::uuid, 'Кофе уух эсэхийг асуухад, ундаасаж байгаа тул ус уухыг илүүд үзэж байгаагаа хэлж байна. Кофе биш ус сонгож буй энэ дүр зурагтай тулгаж B сонголтыг шалгаарай.'),
  ('faabe340-f7bf-4beb-919e-2de1527ed2df'::uuid, 'Гадил жимс нэг фунт нь хэдийг асуухад зургаан юань тавин мөнгө гэж хариулаад, хоёр фунт авахаар шийдэж байна. Гадил жимс худалдаж авах дүр тул зурагтай тулгаж A сонголтыг шалгаарай.'),
  ('8fb5dadb-a365-4ffb-b5fa-98c4f0aba3a3'::uuid, 'Өдөр бүр унадаг дугуйгаараа ажилдаа явдаг эсэхийг асуухад, гэрээсээ ажлын газар хол биш тул дугуйгаар явахад тохиромжтой гэж хариулж байна. Дугуй унаж буй дүр тул зурагтай тулгаж D сонголтыг шалгаарай.'),
  ('deae53ea-283a-4ce7-99a4-ceb160d50950'::uuid, 'Яагаад ийм яаравчилж байгааг асуухад, хүүгээ дөрвөн цаг хагаст хичээлээс нь авахаар байгаа бөгөөд одоо аль хэдийн дөрвөн цаг арван таван минут болсныг хэлж байна. Хүүхдээ авахаар яаравчилж буй дүр тул зурагтай тулгаж C сонголтыг шалгаарай.'),
  ('d4173136-cd9f-4d3a-bed7-b6f9acd27952'::uuid, 'Багш сурагчдаас самбар дээрх өгүүлбэрийн утгыг хэн хэлж чадах вэ гэж асууж байгаа тул тэрээр хариулт хүсэж байна гэсэн үг үнэн. Багшийн 谁能告诉我...是什么意思 гэсэн хэллэг нь яг л асуулт асууж, хариулт хүсэж буйг илтгэнэ.'),
  ('779a6c67-d128-4f93-93ef-5c5fd39563bb'::uuid, 'Лифт ажиллуулагч эмэгтэйд энэ лифт зөвхөн наймдугаар давхарт хүрдэг, харин та арван хоёрдугаар давхарт явах учир зүүн талын лифтээр яв гэж хэлж байна. Тэгэхээр тэр эмэгтэй найм биш арван хоёрдугаар давхарт явна гэсэн үг тул өгүүлбэр буруу.'),
  ('8601bf12-cac0-426e-9419-3640e84ded1e'::uuid, 'Тэр хүн усанд сэлж байхдаа гар цагаа тайлахаа мартаж, дотор нь ус орсон, эвдэрсэн эсэхийг мэдэхгүй байгаагаа ярьж байна. Энэ нь гар цаг усанд норсон гэсэнтэй яг тохирч байна.'),
  ('42c6da6d-be53-4518-8ff1-eca624a2bf2c'::uuid, 'Тэр хүн энэ номыг удаан хайж явсан бөгөөд өнөөдөр ажлаасаа гарахдаа номын дэлгүүрээр өнгөрч байхдаа санаандгүй олж, маш баяртай байгаагаа хэлж байна. Тиймээс тэр номоо олсон гэдэг үнэн.'),
  ('c9103ab2-37be-46de-85cc-899c0910e4db'::uuid, 'Тэр хүн урьд нь Шар мөрний эрэг дээр амьдардаг байсан ч аавынхаа ажлын улмаас энэ газар руу нүүсэн гэж хэлж байна. Иймд тэрээр одоо Шар мөрний ойролцоо биш өөр газар амьдарч байгаа тул өгүүлбэр буруу.'),
  ('cf1088b8-a28e-4307-b888-84cf6eaa73f7'::uuid, 'Энэ бичлэг маш богино бөгөөд шууд «тэрээр гүйлт хийхдээ хамт хөгжим сонсох дуртай» гэсэн өгүүлбэрийг өөрөө уншиж өгсөн байна. Асуултын өгүүлбэр нь бичлэгийн үгтэй яг ижил тул харьцуулах шаардлагагүйгээр √ зөв гэдгийг мэдэж болно.'),
  ('db1a78e4-7020-4f78-90ac-bd6afcc726fb'::uuid, 'Жил бүр өвөл ойртоход хойд нутгийн олон шувуу урагшаа нисч, дараа жилийн хавар буцаж ирдэг гэж хэлж байна. Тэгэхээр шувууд өвөл хойд зүг биш урагшаа нисдэг тул өгүүлбэр буруу.'),
  ('b5d859b2-4fc0-4e92-a314-8788f77c0039'::uuid, 'Тэр хүн хорин өдөр танайд цамц худалдаж авсан бөгөөд одоог хүртэл хүргэгдээгүй байгааг дуудлагаар мэдэгдэж байна. Тиймээс худалдаж авсан зүйл нь хараахан ирээгүй гэдэг үнэн.'),
  ('5cbdaf05-afe4-4834-9b09-f8ddd04a1384'::uuid, 'Тэр хүнээс зурган дээрх охиныг санаж байна уу гэж асуухад, өнгөрсөн жил Шанхайд байхдаа танилцсан бөгөөд өнөөдөр гудамжинд таарсан гэж хариулж байна. Тэгэхээр тэр охиныг мэдэхгүй биш, харин сайн мэддэг тул өгүүлбэр буруу.'),
  ('d69137d8-0f22-4034-94e6-648e81935c70'::uuid, 'Тэр хүн тухайн рестораны зөөгч нартай ч танилцаж, найзуудаа олон удаа дагуулж очсон бөгөөд бүгд тэндхийн хониний махыг хамгийн амттай гэж боддог гэж хэлж байна. Гоймон биш хониний мах тухай ярьж буй тул өгүүлбэр буруу.'),
  ('310ca9d0-5bc3-403a-a726-afc512711420'::uuid, 'Таваг өндөрт байрлуулсныг гайхаад, сандал авчирч өгөөч гэж хүсэж байгаа нь эмэгтэй хүний хэлсэн үг. Тиймээс эмэгтэй хүн эрэгтэйгээр сандал зөөлгөхийг хүсэж байна гэдэг B хариулт зөв.'),
  ('9c8ea8c2-f460-4f5a-8046-3a7ea82132b5'::uuid, 'Менежер энэ долоо хоногт заавал дуусгах ёстой гэж шаардсан бөгөөд, баасан гарагийн өмнө дуусгана гэж хоёулаа ярьж байна. Ижил менежерийн доор ажилладаг тул тэд хамтран ажиллагсад (同事) гэдэг B хариулт зөв.'),
  ('bd7ba60a-03de-47b2-af33-88ae697945d6'::uuid, 'Шинэ авсан алим идэх үү гэж асуухад, эрэгтэй хүн шүдээ угаачихсан учир идэхгүй гэж татгалзаж байна. Тиймээс жимс идэхгүй байгаа шалтгаан нь шүдээ угаасан явдал гэдэг A хариулт зөв.'),
  ('235997ca-9014-4bd3-9792-7dfa5e954ac8'::uuid, 'Хүү нь эцгээ их дуурайсан гэхэд, эрэгтэй хүн ам нь эцгээ илүү их дуурайсан гэж хариулж байна. Тиймээс хүү ямар эрхтэнээрээ эцэгтэйгээ адилхан болохыг асуухад ам (嘴) гэсэн A хариулт зөв.'),
  ('9c4f26ad-ee38-4260-8038-b0988b427048'::uuid, 'Зургийн аппарат чинийхийг буцааж өгье, баярлалаа гэж хэлж, нөгөөх нь эгчтэйгээ сайхан цагийг өнгөрөөсөн үү гэж асууж байна. Тиймээс эмэгтэй хүн эрэгтэйгээс камер буцаах гэж очсон тул B хариулт зөв.')
) as v(id, explanation)
 where t.id = v.id;

update mock_test_questions as t
   set explanation_mn = v.explanation
  from (values
  ('46515561-7daa-43ff-87a3-19d1d7e066eb'::uuid, 'Бид сүүлийн үед олон шинэ хоол гаргасан, шинэ цэс хийх цаг болсон биз гэж хэлж, нөгөөх нь чи хий гэж хариулж байна. Тиймээс цэс солих гол шалтгаан нь шинэ хоол гарсан явдал гэдэг A хариулт зөв.'),
  ('90b0af43-014b-454f-9d62-cb6b5cd78188'::uuid, 'Яагаад унтаагүй байна вэ, хэнтэй чатлаж байна вэ гэж асуухад, ангийн найзтайгаа маргаашийн сагсан бөмбөгийн тэмцээний талаар ярьж байгаагаа хэлж байна. Тиймээс эрэгтэй хүний тухай мэдэх зүйл нь маргааш тэмцээнтэй гэдэг C хариулт зөв.'),
  ('51f664f4-fe06-40e0-83d1-541899a37c05'::uuid, 'Энэ цэцгийн саванд их дурлачихлаа, хаанаас авсан бэ гэж асуухад, доод давхрын дэлгүүрээс авсан гэж хариулж байна. Эхлээд «их дурлачихлаа» гэж хэлсэн тул эрэгтэй хүн уг цэцгийн саванд их таалагдсан гэдэг A хариулт зөв.'),
  ('f9abe815-223f-4ee9-bbe6-ac05c827382e'::uuid, 'Өмдөн дээр чинь ийм олон өвс яагаад байна вэ гэж асуухад, эрэгтэй хүн дүүтэйгээ хамт зүлэгэн дээр хөл бөмбөг тоглосон гэж хариулж байна. Тиймээс хамт тоглосон хүн нь дүү (弟弟) гэдэг B хариулт зөв.'),
  ('c57055ef-38f2-4c05-a616-3aed7f9f864f'::uuid, 'Бээжингийн их сургууль руу метроор явахад тохиромжтой юу гэж асуухад, тохиромжтой гэж хариулаад, сургуулийн зүүн хаалганаас 203-р автобусанд сууж болно гэж зөвлөж байна. Тиймээс 203-р автобусанд сургуулийн зүүн хаалганаас (学校东门) суух ёстой тул C хариулт зөв.'),
  ('eece85b3-76b6-4546-8928-5b7724cb1d28'::uuid, 'Хүн нэг чигээрээ явж хоёр дахь уулзвар дээр баруун тийш нэг километр явахад хүрнэ гэж заавар өгч байгаад, эмэгтэй хүн удаан хэлээч, тодорхойгүй байна гэж дахин асуугаад зураг зурж өгье гэж санал болгож байна. Тиймээс эмэгтэй хүн зам асууж (问路) байгаа нь тодорхой тул A хариулт зөв.'),
  ('34045991-985e-433e-b927-b2d725f4a371'::uuid, 'Өнөөдөр ч спорт заал руу явах уу гэж асуухад, шүршүүрт орчихоод явна гэж хариулаад, гадаа үүлэрхэг тул удахгүй бороо орж магадгүй, машинаа болгоомжтой унаарай гэж сануулж байна. Тиймээс өнөөдрийн цаг агаар үүлэрхэг (阴天) гэдэг B хариулт зөв.'),
  ('2dedb8d1-fd39-40f4-8ff2-605adb33e325'::uuid, 'Хүүхдэдээ ямар нэр өгвөл дээр вэ гэж асуугаад, охин бол Байсюэ гэж нэрлэе, харин хүү бол гэдэг дээр л сэтгэл нь тогтоогүй байгаагаа ярьж байна. Тэд хүүхдийнхээ нэрийг (孩子的名字) хэлэлцэж байгаа тул C хариулт зөв.'),
  ('347333f9-4017-408b-a1fa-a77e5e96a0b7'::uuid, 'Сяо Ван ийм олон зурааш (画笔) худалдаж авсныг асуухад, хүүдээ авсан бөгөөд тэрээр сүүлийн үед зураг зурж сурч байна, амьтад, нохой, муур, загас зурах дуртай гэж хариулж байна. Тиймээс хүү нь зураг зурж сурч байгаа (在学画) тул B хариулт зөв.'),
  ('56352bb1-f1fe-4e9b-b13d-edaa4372b6f2'::uuid, 'Энэ долоо хоногт Сяо Чжан ажилдаа ирээгүй байгааг гайхаад, компани түүнийг гадаадад сургахаар илгээснийг мэдэж байна уу гэж хэлж, хагас жилийн дараа арван хоёрдугаар сард буцаж ирнэ гэж нэмж хэлж байна. Тиймээс тэрээр гадаадад явсан (出国了) тул A хариулт зөв.'),
  ('ba2dabdf-0d65-4573-aa98-37891148d008'::uuid, 'Эрэгтэй хүн түрийвчээ гээгдүүлж, магадгүй ресторанд мартсан гэж хэлээд, түрийвчийнхээ хар өнгөтэй, дотор нь хоёр карт, хэдэн зуун юань байсныг тайлбарлаж байна. Ажилтан угаалгын өрөөг цэвэрлэж байхдаа олсон түрийвчийг олж өгснөөр асуудал нь түрийвч гээгдсэн (钱包不见了) гэдэг нь батлагдана — C хариулт зөв.'),
  ('fa2fc403-488c-48bb-b2ea-89174c8c027b'::uuid, 'Захирал Ван нартаа маргааш нисэх онгоцны буудал руу хэдэн машин хэрэгтэйг асуухад, нийт дөчин таван хүн байгаа бөгөөд нэг машинд хорин таван хүн суух боломжтойг тооцоод, хоёр машин хангалттай гэж дүгнэж байна. Тиймээс тооцоолол хийсэн эмэгтэй хүн хоёр машин хэрэгтэй (需要两辆车) гэсэн дүгнэлтэд хүрсэн тул C хариулт зөв.'),
  ('e5178cca-0f26-4ab0-968d-56b5406da3db'::uuid, 'Одоо явах уу гэж асуухад, эрэгтэй хүн хэдэн дасгал даалгавраа дуусгаагүй байгаа тул та түрүүлж яв гэж хариулж байна. Тиймээс тэрээр даалгавраа дуусгаагүйгээс болж (没做完题) хойшлуулж байгаа нь C хариулттай тохирно.'),
  ('ff90155c-b606-401f-b701-6e46afb60a42'::uuid, 'Ням гарагийн өглөө хамт усанд сэлэхээр урьж, сургуулийн ойролцоо шинээр нэг усан сан нээгдсэн бөгөөд орчин тойрон нь муугүй гэж сонссон гэдгээ хэлж байна. Тэгэхээр уг усан сан саяхан нээгдсэн (新开不久) тул A хариулт зөв.'),
  ('a175e1fe-2e02-4b88-9be3-822678f29ce5'::uuid, 'Сонин уншихаа боль, эмч чамд амарч байхыг зөвлөсөн гэж хэлэхэд, эрэгтэй хүн санаа зоволтгүй, би аль хэдийн халуурахаа больсон гэж хариулж, эм ч уусан гэдгээ баталж байна. Тиймээс эрэгтэй хүний одоогийн байдал нь халуурахаа больсон (不发烧了) тул B хариулт зөв.'),
  ('003c3b4d-83e6-4135-9e7e-ae10c3a63e23'::uuid, 'Тэр хүн Юньнань руу аялахаар төлөвлөж, тэнд дөрвөн улирал хавар мэт дулаахан, байгаль үзэсгэлэнтэй, тус нутгийн үндэстний хүмүүс маш зочломтгой тул энэ зуны амралт сонирхолтой болно гэдэгт итгэлтэй байгаагаа ярьж байна. Энэ нь өгүүлбэртэй яг тохирч байгаа тул √ зөв.'),
  ('d1498033-b06d-449e-ac9d-595b1087d331'::uuid, 'Охин нь өнөөдөр ажлаасаа гарсны дараа ангийн найзтайгаа кино үзэхээр уулзалттай, орой гэртээ хооллохоор ирэхгүй гэдгээ хэлж байна. Ажил дээрээ илүү цагаар ажиллана гэж хэлээгүй, харин уулзалт хийж байгаа тул өгүүлбэр буруу.'),
  ('5049e25c-34b9-4696-b3ee-98ea8b911f28'::uuid, 'Тэр хүн энд анх ирэхэд дасаж чадаагүй, ганцаардмал санагдаж байсан ч аажмаар дадаж, олон найз нөхөдтэй болсноор энд амьдрахад улам их дуртай болсноо ярьж байна. Тиймээс тэрээр энд амьдралд дассан гэдэг үнэн.'),
  ('c56ed6c9-9935-4d75-be03-337bc51f2125'::uuid, 'Тухайн вэбсайтын агуулга баялаг бөгөөд шинжлэх ухаан, урлагийн мэдлэгээс гадна олон хошин үлгэр агуулдаг тул сонирхвол хаягийг нь илгээе гэж хэлж байна. Энэ бол үнэ ярилцаж буй яриа биш, вэбсайтын агуулгын тухай яриа тул өгүүлбэр буруу.'),
  ('5f039507-b0b8-4902-ac32-6e3e485f16f8'::uuid, 'Хятадууд 6 тоог амжилт, тэгш замтай холбож үздэг тул 6 тоотой өдрөөр хурим хийх дуртай, утасны дугаартаа ч 6 тоо байхыг хүсдэг гэж тайлбарлаж байна. Энэ нь Хятадууд 6 тоонд дуртай гэдэгтэй яг таарч байна.'),
  ('3cabadb3-e6ec-4790-aad6-0d88450d5c51'::uuid, 'Тэр хүн ажил дээрээ завгүй тул хөдөлгөөн хийх цаг ховор ч амралтын өдрүүдэд найзуудтайгаа уулзаж сагсан бөмбөг эсвэл хөл бөмбөг тоглох, заримдаа уулын тэнхлэг рүү явдаг гэж хэлж байна. Өдөр бүр биш зөвхөн амралтын өдрүүдэд тоглодог тул өгүүлбэр буруу.'),
  ('1fe2c99d-8867-4f64-ae3d-ec819f0b47b1'::uuid, 'Монгол хэлний шалгалтад бэлдэж байгаа хүнээс маргааш бүртгэл дуусах гэж байхад юунд материалаа өгөөгүй байна вэ гэж асууж байна. Бүртгэл маргааш дуусна гэсэн нь өнөөдөр хараахан хугацаа дуусаагүй, өөрөөр хэлбэл өнөөдөр бүртгүүлэх цаг байсаар байна гэсэн үг тул √ зөв.'),
  ('81ffe16f-fa21-4e0a-aca2-cc3e7089d9a3'::uuid, 'Сяо Линь хуулийн асуудалтай бол өмгөөлөгч танилцуулж болно, түүнтэй ярилцаарай, мэргэжлийн зөвлөгөө өгнө гэж хэлж байна. Энэ нь Сяо Линь өөрөө өмгөөлөгч биш, харин өөр хэн нэгэн түүнд өмгөөлөгч танилцуулж байгааг харуулж байгаа тул өгүүлбэр буруу.'),
  ('9684f51e-c4b2-47c2-afa2-971c7ff8e830'::uuid, 'Бид бусдын сайн ажил, сайхан гэр бүлд атаархаад өөрсдийн эдэлж буй аз жаргалыг мартдаг ч бодит байдал дээр бид ч бусдын нүдэнд аз жаргалтай байдгийг олж хардаггүй гэж хэлж байна. Энэ нь бусдад байнга атаархаж болохгүй гэсэн санаатай яг таарна.'),
  ('823d6242-306d-412b-a2e8-91c206a6cfb5'::uuid, 'Хүйтэн агаарын массын нөлөөгөөр манай мужид маргааш хүчтэй салхи, температур буурах, зарим газарт бага-дунд зэргийн бороо орох тул зам харилцаанд нөлөөлж болзошгүй, гарах үедээ болгоомжтой байхыг сануулж байна. Энд их цас биш бороо орно гэж хэлсэн тул өгүүлбэр буруу.'),
  ('d68ee742-0b54-4ba0-be43-6ba116a26803'::uuid, 'Энэ шоколад амттай юм, хаанаас авсан бэ гэж асуухад, өөрөө авсан биш, авга ах нь гадаадаас авчирсан гэж хариулж байна. Тиймээс шоколадыг авга ах (叔叔) авчирсан гэдэг B хариулт зөв.'),
  ('02441fb9-ae82-45d5-a643-40f8fc8f23ca'::uuid, 'Ах аа, өчигдөр орой сайн унтсан уу, халуурсан уу гэж асуухад, өрөөндөө агааржуулагч асаасан тул сэрүүхэн байсан гэж хариулж байна. Тиймээс сэрүүн байсан шалтгаан нь агааржуулагч асаасан (开空调了) явдал тул C хариулт зөв.'),
  ('efc5fd02-7c45-43af-b7be-655646c0801a'::uuid, 'Хэвлэлийн бага хурал арван цагт эхэлнэ, та онгоцноос хэдэн цагт бууж байгааг мэдвэл авахаар очъё гэхэд, эмэгтэй хүн хэрэггүй, би долоон цаг арван таван минутад буугаад шууд такси барьж хурлын газар очно гэж хариулж байна. Тиймээс тэрээр таксигаар (坐出租车) явна гэдэг D хариулт зөв.'),
  ('bb347347-4c69-4458-a49b-89e83b89a80d'::uuid, 'Нүүрнийхээ хөлсийг алчуураар арчаад, та хоёр теннис сайн тоглож байна шүү гэхэд, эрэгтэй хүн Лао Литэй анх удаа тоглож байгаа бөгөөд түүний тоглоом ийм сайн байх гэж бодоогүй гэж хариулж байна. Тиймээс эрэгтэй хүн саяхан теннис тоглож байсан (打网球) тул A хариулт зөв.'),
  ('8d67e671-a534-463f-9d88-bb37932d6637'::uuid, 'Таны бичсэн энэ мэдээллийн репортаж их сайн болжээ, цаашид ч үргэлжлүүлж хичээгээрэй гэж магтаж, эрэгтэй хүн баярлалаа, сайн ажиллана гэж хариулж байна. Тиймээс тэр репортажийг сайн бичсэн (写得不错) гэж үзэж байгаа нь B хариулттай тохирно.'),
  ('af4105e0-787a-4cd4-afa3-8d9f04f1a98a'::uuid, 'Зөөврийн компьютерээ солихыг хүсэж, аль нь сайн болохыг мэдэх үү гэж асуухад, өөрөө ч сайн мэдэхгүй, эхлээд интернэтээр хайж, харьцуулаад дараа нь шийд гэж зөвлөж байна. Тиймээс эрэгтэй хүний хэлсэн санаа нь интернэтээр хайж үзэх (上网看看) гэдэг тул B хариулт зөв.'),
  ('2388a782-8f19-449c-932c-2242d0d49474'::uuid, 'Танаас нэрээ, хүйсээ, насаа заавал бичих ёстой энэ маягтыг эхлээд бөглөнө үү гэж хэлж, эмэгтэй хүн зөвшөөрөөд бал авчаагүй байна, танайд бал бий юу гэж асууж байна. Тиймээс эмэгтэй хүн маягт бөглөж байгаа (填表) нь тодорхой тул A хариулт зөв.'),
  ('6c9bbbcc-48c8-4ab5-b99d-ab91c640c49c'::uuid, 'Гадаадад суралцахаар явна гэж сонссон гэхэд, тийм ээ, визээ дөнгөж авсан, энэ сарын төгсгөлд явна гэж хариулж байна. Тиймээс эрэгтэй хүний тухай зөв мэдээлэл бол виз аль хэдийн авсан (拿到签证了) явдал тул D хариулт зөв.'),
  ('07649453-c5fc-4b3b-a30f-f0535e8a5c69'::uuid, 'Докторын зэрэгт элссэнд чинь баяр хүргэе гэхэд, эмэгтэй хүн баярлалаа, та нарын тусламжгүйгээр ийм амархан амжилтад хүрэхгүй байсан гэж хариулж байна. Тиймээс эмэгтэй хүн докторын зэрэгт элссэн (考上了博士) гэдэг нь D хариултай тохирно.'),
  ('2bf9f4db-357c-4ac2-af4d-f80919c76679'::uuid, 'Уучлаарай, саяхан хурлын өрөөнд хурал хийж байсан тул утсанд хариулж чадаагүй гэж хэлж, нөгөөх нь ойлголоо, чи ч завгүй байсан байх, саад болоогүй биз гэж хэлж байна. Тиймээс эмэгтэй хүн саяхан хурал хийж байсан (开会) гэдэг A хариулттай тохирно.'),
  ('44b64452-cd46-4206-88db-7c5c491c74e6'::uuid, 'Эрэгтэй хүн шидмэлийн (бадминтон) тэмцээнийг үзсэн эсэхийг асуухад эмэгтэй нь "看了,真是太精彩了,尤其是第二场" (үзсэн, үнэхээр сонирхолтой байлаа, ялангуяа хоёр дахь тоглолт) гэж хариулсан нь маш их таалагдсаныг илэрхийлж байгаа тул "十分精彩" (маш сонирхолтой) зөв хариулт. "很无聊" (уйтгартай), "让人失望" (урам хугарсан) гэсэн сонголтууд эмэгтэйн сэтгэгдэлтэй яг эсрэгээрээ тул буруу.'),
  ('b163db29-70e5-48ed-9d22-63e4f666d167'::uuid, 'Эх нь хүүдээ зочин ирэхээс өмнө "去帮我把垃圾扔了" (яв, хогоо хая) гэж даалгасан тул зөв хариулт "扔垃圾" (хог хаях) мөн. "收拾行李" (ачаа цэгцлэх), "请客" (зочломт хийх) зэрэг ажлын тухай уг ярианд огт дурдагдаагүй тул буруу.'),
  ('2445927f-51e1-4744-b72c-0ea217e44834'::uuid, 'Маргаашийн айлчлалд орчуулагч хэрэгтэй гэдэгтэй холбогдуулан "小马吧,他就是这个专业毕业的,而且经验丰富" гэж хэлж байгаа нь Сяо Ма орчуулгын мэргэжлээр төгссөн, туршлагатай тул орчуулга хийж чадна гэсэн үг. Иймд "可以做翻译" зөв, харин "很勇敢", "遇事冷静" зэрэг зан чанарын тухай юу ч хэлээгүй.'),
  ('00381a26-4aab-44d3-b27a-f1f57a438495'::uuid, 'Эмэгтэй жолоочид "我得在九点之前到大使馆" (9 цагаас өмнө элчин сайдын яаманд хүрэх ёстой) гэж хэлж байгаа тул очих газар нь "大使馆" мөн. "公园", "首都体育馆", "国家图书馆" зэрэг газрын нэр огт дурдагдаагүй тул буруу.'),
  ('f30b6789-5d9c-4b1c-ac90-1eb2298ed305'::uuid, 'Чихэрт дуртай байсан эмэгтэй яагаад идэхээ больсныг асуухад "我最近牙疼,连饼干这种稍微有点甜的东西都不敢吃,更别说糖了" (сүүлийн үед шүд өвдөж байгаа тул жигнэмэг ч идэхээс эмээж байна, чихэр бол хэлэх ч үгүй) гэж тайлбарласан тул шалтгаан нь "牙疼" (шүд өвдөх) мөн. "胖了", "肚子不舒服" зэрэг шалтгаан огт дурдагдаагүй.'),
  ('9d28ad82-98b4-4de8-b888-54b8d53eb50b'::uuid, 'Гэрт орж ирээд гэрлийг асаагаагүйг асуухад "刚发现灯不亮,是不是停电了" гэж, дараа нь хөрш гэр гэрэлтэй байгааг тодруулснаар "那就是灯坏了" (тэгвэл гэрэл эвдэрсэн байна) гэсэн дүгнэлтэд хүрсэн тул "灯不亮了" зөв хариулт. Цахилгаан тасарсан гэсэн таамаглал няцаагдсан тул "冰箱坏了" зэрэг бусад сонголт буруу.'),
  ('24b770ba-5c1e-4fce-b882-f4e334dc6f76'::uuid, 'Эмэгтэй шинээр нээгдсэн рестораны тухай "那儿菜不错,服务态度也挺好" (тэнд хоол сайхан, үйлчилгээ ч сайн) гэж дурсамжаа хуваалцаж байгаа тул хамгийн онцлон дурдсан зүйл нь "菜好吃" (хоол амттай) мөн. "很吵" (чимээ шуугиантай) гэсэн сөрөг үнэлгээ уг яриаНД байхгүй.'),
  ('135dbe76-f164-4aab-b0dc-49bf7a61b5c7'::uuid, '"你父亲以前是京剧演员" гэсэн асуултад "对" гэж баталгаажуулж, аав нь залуу насандаа алдартай байсныг ярьж байгаа тул аав нь Бээжингийн дуурийн жүжигчин байсан гэдэг нь тодорхой — "会唱京剧" зөв. "是数学老师", "爱跳舞" гэсэн зүйл огт дурдагдаагүй.'),
  ('f7a03bde-7512-4545-a17f-80d4d11fa472'::uuid, 'Яагаад ийм цэгцтэй хувцасласан талаар "有家银行通知我去面试,所以就打扮了一下" (банкнаас ярилцлагад дуудсан тул жаахан хувцасласан) гэж тайлбарлаж байгаа тул шалтгаан нь "要去面试" мөн. "要演节目", "要参加讨论会" зэрэг зорилго ярианд алга.'),
  ('42455101-88aa-4fcd-8082-47a6846ba8cb'::uuid, 'Номын зохиогчийн тухай "他的小说写得很感人" (роман нь маш сэтгэл хөдөлгөм) гэж нэг нь үнэлж, нөгөө нь "我也喜欢他的小说" гэж дэмжсэн тул хоёулаа энэ романыг "让人感动" (сэтгэлд хүрдэг) гэж бодож байна. "不自然", "不吸引人" гэсэн сөрөг үнэлгээ огт байхгүй.'),
  ('6e717139-dcad-44c2-a4f3-5f86d2aaf9dd'::uuid, '"是您要理发吗? 不是,给我小孙子理发" гээд "想给他理成什么样的呢?" гэж асуусан яриа нь үс засах газарт болж байгаа нь тодорхой тул "理发店" зөв. "教室", "办公室" зэрэг газар үс засахтай холбоогүй.'),
  ('550fde15-3ae3-489d-b157-fcaa9ae3e192'::uuid, 'Эрэгтэй "你顺便买几个西红柿吧,晚上做个汤" (замдаа улаан лооль аваад ир, орой шөл хийе) гэж хүссэн тул "西红柿" зөв хариулт. Эмэгтэй өчигдөр авчихсан гэдгээ хэлсэн ч асуулт нь эрэгтэйн ЮУ авахыг хүссэнийг л асуусан тул хариулт өөрчлөгдөхгүй.'),
  ('587ab086-967c-47c8-95df-a282e30ab0bf'::uuid, 'Эмэгтэй өрөөгөө эмх замбараагүй болгож "看见我的钱包了吗?我到处找都没找到" (түрийвчийг минь харсан уу, хаа сайгүй хайлаа ч олдсонгүй) гэж түгшиж, кафед мартсан байж магадгүй гэж ярьж байгаа тул шалтгаан нь "钱包丢了" мөн.'),
  ('9be58e4b-9300-48ce-b90b-257b02ae95b7'::uuid, 'Бизнес хийж буй эмэгтэйд "慢慢来,万事开头难,关键是要多积累经验" (яарах хэрэггүй, эхлэл хэцүү байдаг, гол нь туршлага хуримтлуулах) гэж зөвлөхөд эмэгтэй "我也是这样想的" гэж санал нэгдсэн тул түүний бодол "多积累经验" мөн. "输赢不重要" гэсэн санаа огт гараагүй.'),
  ('9eefd69f-67cf-44dc-b531-2f72e92fb95b'::uuid, 'Ням гарагт далайн музейд явахаар тохирсны дараа "从学校西门走方便一些,我们在那儿见吧" (сургуулийн баруун хаалганаас явбал тохиромжтой, тэнд уулзацгаая) гэж тохирсон тул уулзах газар нь "学校西门" мөн. "宾馆右边", "植物园后面" зэрэг газар ярианд алга.'),
  ('43a148bd-b414-45de-8eb7-32411e443434'::uuid, 'Бичлэгт "儿子告诉我,他长大后,想做204路公交车的司机" (хүү минь том болохоороо 204-р автобусны жолооч болно гэж хэлсэн) гэж эх нь ярьж байгаа тул хүүгийн ирээдүйн мөрөөдөл "司机" (жолооч) мөн.'),
  ('174d49f6-28f9-4200-8b3b-1e89bf185bec'::uuid, 'Хүү яагаад яг 204-р автобусны жолооч болохыг хүссэнийг "因为204路车的最后一站,是动物园,这样,我就可以天天到动物园,看老虎和猴子了" (учир нь энэ автобусны эцсийн буудал амьтны хүрээлэн, тэгвэл өдөр бүр очиж бар, сармагчин үзнэ) гэж тайлбарласан тул 204-р автобус "能到动物园" (амьтны хүрээлэнд хүрдэг) гэдэг нь зөв. Хурд, эцсийн буудлын байршил зэрэг бусад мэдээлэл дурдагдаагүй.'),
  ('43455b94-c95c-4a51-adb0-b7a2fb230401'::uuid, 'Цайны тухай өгүүлэхдээ "最早的时候,茶只是被当作一种药,而不是饮料" (эхэн үедээ цай зөвхөн эм болгож хэрэглэгддэг байсан, ундаа биш) гэж тодорхой хэлсэн тул хамгийн эхэнд цайг "药" (эм) гэж үзэж байсан нь зөв.'),
  ('cf1c8f44-6b44-4525-b109-abb0532fb59f'::uuid, '"茶在中国有数千年的历史" (цай Хятадад хэдэн мянган жилийн түүхтэй) гэж эхэлж байгаа тул цайны тухай мэдэх зүйл бол "历史很长" (түүх нь урт) мөн. Улаан цай хамгийн түгээмэл гэх мэдээлэл, хүчиллэг амттай гэх зэрэг огт дурдагдаагүй.'),
  ('9cf4041e-18b8-450a-b1d9-3b55a51be85d'::uuid, 'Худалдагч "只要是在我们店购买的洗衣机,一年以内出现任何质量问题,我们都会免费给您修" (манай дэлгүүрээс худалдаж авсан угаалгын машинд нэг жилийн дотор чанарын асуудал гарвал үнэгүй засна) гэж хэлж байгаа тул ноён Ван "洗衣机" (угаалгын машин) худалдаж авч байна.'),
  ('9d9688e2-1457-4de7-af52-d2d192bf8eb2'::uuid, '"这是保修卡,使用中遇到什么问题,您可以通过上面的电话联系我们" (энэ бол баталгаат хугацааны карт, асуудал гарвал дээрх утсаар холбогдоорой) гэж хэлсэн тул холбоо барих утасны дугаар "保修卡上" (баталгааны картан дээр) бичигдсэн байна.'),
  ('2f39c9fa-2a39-4661-b0b5-a178125e27b5'::uuid, 'Эцэг эхийн хандлагын тухай "有些父母,觉得孩子做事情慢,总想替他们做" (зарим эцэг эх хүүхэд нь удаан хийдэг гэж бодоод байнга оронд нь хийхийг хүсдэг) гэж хэлсэн тул тэд ихэвчлэн "替孩子做" (хүүхдийн оронд хийж өгдөг) нь зөв.'),
  ('a93464c1-1eea-4d6e-9b04-13b9a6e20521'::uuid, '"父母应该让孩子学会管理时间,自己的事情自己做" (эцэг эх хүүхдэдээ цагаа зохицуулж сурган, өөрийн ажлыг өөрөөр нь хийлгэх ёстой) гэж дүгнэсэн тул хүүхдэд төлөвшүүлэх ёстой зуршил нь "会安排时间" (цагаа зохицуулж чаддаг байх) мөн.'),
  ('e8bee890-4adc-4343-bdc0-02c55a7d1489'::uuid, 'Бичлэгт "虽然小高平时爱开玩笑,但他做起事来还是很认真的,把这个任务交给他,他一定能够做好" (Сяо Гао ажлаа нухацтай хийдэг тул даалгавар өгвөл сайн хийнэ) гэж эерэгээр найдаж байгаа бол өгүүлбэр "他反对把任务交给小高" (даалгаврыг Сяо Гаод өгөхийг эсэргүүцэж байна) гэж эсрэгээр хэлж байгаа тул тохирохгүй (×).'),
  ('d6cc7035-f805-4c03-8005-4257aedf210b'::uuid, 'Эцэг хүүдээ газрын зургийг тайлбарлахдаа "绿色的是森林,蓝色的是海洋" (ногоон нь ой, хөх нь далай) гэж шууд хэлсэн тул "地图上蓝色表示海洋" гэсэн өгүүлбэр бичлэгтэй нийцэж байгаа тул зөв (√).')
) as v(id, explanation)
 where t.id = v.id;

update mock_test_questions as t
   set explanation_mn = v.explanation
  from (values
  ('9c00b490-4041-4528-babf-225a2024d9cd'::uuid, '"我觉得这条裙子很适合女儿,现在穿肯定特别凉快,正好又打折,咱们就买这条吧" (энэ юбка охиндоо тохирно, хямдарсан үед л авъя) гэж хэлж, худалдаж авахаар шийдсэн нь тухайн юбканд сэтгэл ханамжтай байгааг харуулж байгаа тул "他对那条裙子很满意" зөв (√).'),
  ('ee281152-ebfa-4773-a1e1-b5b915e648fa'::uuid, 'Бичлэгт "尽管很辛苦,但他还是坚持每天做运动,几个月下来减肥的效果很不错" (хэцүү ч байсан өдөр бүр дасгал хийж, хэдэн сарын дараа туранхай болсон) гэж хэлж байгаа бол өгүүлбэр "他最近胖了" (сүүлийн үед таргалсан) гэж эсрэгээр хэлж байгаа тул буруу (×).'),
  ('738e934c-77ab-4f14-b56e-7c1b2df64e72'::uuid, '"只要是在我店购买的家具,无论价钱多少,无论您家离这儿多远,我们都将为您提供免费送货上门服务" (үнэ болон зайнаас үл хамааран, манай дэлгүүрээс авсан тавилгад үнэгүй хүргэлт хийнэ) гэж борлуулагч тодорхой амлаж байгаа тул "那家店免费为顾客送家具" гэсэн өгүүлбэр бичлэгтэй бүрэн нийцэж байгаа тул зөв (√).'),
  ('a748da70-4fc9-4364-b207-356015377310'::uuid, 'Бичлэгт "一直没找到合适的房子,所以暂时还得在这儿住一段时间" (тохиромжтой байр олоогүй тул түр энд амьдрах хэрэгтэй) гэж хэлж байгаа бол өгүүлбэр "他租到了合适的房子" (тохиромжтой байр түрээслэсэн) гэж эсрэгээр мэдэгдэж байгаа тул буруу (×).'),
  ('381aa338-595f-48f5-b835-48d6fc7a2dbd'::uuid, '"保护环境可以从小事做起,例如少用塑料袋,将垃圾丢进垃圾桶" (орчны хамгааллыг жижиг зүйлээс эхлүүлж болно, тухайлбал полиэтилен цөөн хэрэглэх) гэж хэлж байгаа тул "环保要从身边小事做起" гэсэн өгүүлбэр бичлэгтэй бүрэн нийцэж байгаа тул зөв (√).'),
  ('37f466d4-30e0-40e3-b27d-06aa07204428'::uuid, 'Бичлэгт "我们办公室的传真机坏了" (манай оффисын факс машин эвдэрсэн) гэж хэлж байгаа бол өгүүлбэр "复印机坏了" (хувилагч машин эвдэрсэн) гэж өөр төхөөрөмжийн тухай хэлж байгаа тул тохирохгүй (×) — факс болон хувилагч өөр зүйл гэдгийг анзаарах хэрэгтэй.'),
  ('2a731908-e179-410b-b91d-2c67d078834a'::uuid, 'Бичлэгт "你和小夏当时都没做出解释,这才引起了误会,我觉得你们俩见一面,把事情说清楚就好了" (та хоёр тайлбарлаагүйгээс болж ойлголцгүй байдал үүссэн, уулзаж ярилцвал дээр) гэж ЗӨВЛӨЖ байгаа болохоос ойлголцгүй байдал АЛИ ХЭДИЙН тайлагдсан гэж хэлээгүй тул "小夏把误会解释清楚了" буруу (×).'),
  ('d96b506b-4b38-4c26-85c5-ec1d8ed44532'::uuid, '"研究发现吃甜的东西能使人心情愉快,所以如果你觉得心烦,可以吃点蛋糕或者巧克力" (чихэрлэг зүйл идэх нь сэтгэл санааг сайжруулдаг гэдгийг судалгаагаар тогтоожээ) гэж шууд хэлсэн тул "吃甜的东西能让心情变好" зөв (√).'),
  ('26e8187f-4b0c-4751-8b81-f8d27633a6db'::uuid, '"我们什么时候去参观长城? 明天上午八点出发,到时大家准时在宾馆门口见" гэж эмэгтэй бүлгээ удирдан аялалын хуваарь, цуглах цаг газрыг мэдэгдэж байгаа тул тэрээр жуулчдыг удирдан явуулдаг "导游" (жуулчны хөтөч) байх магадлал хамгийн өндөр. "警察" эсвэл "理发师" гэдэгтэй холбоотой юу ч дурдагдаагүй.'),
  ('cb785428-0dfb-4a1f-8929-184f4e0b9143'::uuid, '"您付现金还是刷卡? 我的零钱不够,还是刷卡吧" (бэлнээр эсвэл картаар төлөх үү? Задгай мөнгө хүрэхгүй байна, картаар төлье) гэж хэлж байгаа тул "男的想刷卡" (эрэгтэй карт ашиглахыг хүсэж байна) зөв. "男的没带钱" гэдэг бол буруу — тэр зөвхөн задгай мөнгөгүй байгаа болохоос мөнгөгүй биш.'),
  ('a6efee0c-c7f7-40d5-aeec-0ad803eaa86e'::uuid, '"我已经通知他会议地点改到首都饭店了" (хурлын байрыг Шоуду зочид буудал руу шилжсэн гэдгийг мэдэгдсэн) гэж хэлж байгаа тул хурлын тухай зөв мэдээлэл "地点变了" (байршил өөрчлөгдсөн) мөн.'),
  ('cc990d5e-fc86-4cf6-a727-a7b7ff9d2330'::uuid, 'Эмэгтэй "这儿的景色真美,帮我照张相吧!" (энэ газрын үзэмж үнэхээр сайхан байна, надад зураг авч өгөөч) гэж хүссэнд эрэгтэй "你稍微往左边站一点" гэж байрлал заасан тул эрэгтэйгээр хийлгэхийг хүссэн зүйл нь "照相" (зураг авах) мөн.'),
  ('64947aae-25c9-405d-88c0-a45b15d3eea2'::uuid, '"不是,我同事突然肚子疼,我陪他来检查一下" (үгүй, хамт олон минь гэдэс өвдсөн тул хамт эмнэлэгт ирлээ) гэж тайлбарласан тул эмэгтэй өөрөө өвдөөгүй, харин "陪同事看病" (хамт олноороо эмчид үзүүлэхээр хамт ирсэн) нь эмнэлэгт очсон шалтгаан мөн.'),
  ('0c3b5997-3f27-415c-9d8a-7126d515aa2e'::uuid, '"52路和407路都能到我这儿,你看看有没有这两趟车? 52路来了,我先挂了" (52 болон 407-р автобус хоёулаа надад ирдэг, ирсэн эсэхийг харчих; 52-р автобус ирлээ) гэж хэлж байгаа тул эрэгтэй одоо "公共汽车站" (автобусны буудал) дээр байгаа нь тодорхой.'),
  ('91988296-111d-4c3b-bcc3-45a30665b0da'::uuid, '"这块手表真漂亮,是送给妈妈的生日礼物吗? 是的,不过你现在千万别告诉她" (энэ цаг үзэсгэлэнтэй юм, ээждээ бэлэглэх үү? Тийм ээ, гэхдээ түүнд одоохондоо бүү хэлээрэй) гэж баталгаажуулсан тул цаг бэлэглэх хүн нь "妈妈" (ээж) мөн.'),
  ('0da05e34-a929-4609-89df-f3b43842d0ab'::uuid, '"是有点复杂,你多练习几遍就好了" (арай төвөгтэй байна, хэдэн удаа давтаад дасах болно) гэж зөвлөж байгаа тул эрэгтэй эмэгтэйд "多练习" (илүү давтан дасгал хийх) гэж зөвлөж байна.'),
  ('a3d71e00-812f-4ac7-8488-5bd73bb21f27'::uuid, '"是我从网上买的盘子和勺子,你小心点" (интернетээс худалдаж авсан таваг, халбага, болгоомжтой байгаарай) гэж хэлж байгаа тул хайрцаг дотор "里面有盘子" (таваг байгаа) нь зөв.'),
  ('d1572a3e-96e9-4cd2-a344-b28ff8b55dc2'::uuid, '"请问这附近是不是有家烤鸭店? 对,你走到前面路口左转就能看见了" (ойролцоо шарсан нугасны газар байдаг уу? Тийм, урд уулзвараас зүүн тийш эргэвэл харагдана) гэж хэлж байгаа тул эмэгтэй "烤鸭店" (шарсан нугасны газар) хайж байна.'),
  ('6cc8fa63-7e1e-423e-9d98-4b2281c38acb'::uuid, '"喂,你在哪儿呢?我忘带钥匙了" (чи хаана байна? Би түлхүүрээ авахаа мартчихлаа) гэж эрэгтэй анх дуудлага өгч буй хэсэгт шууд хэлж байгаа тул түүнд тохиолдсон асуудал "没带钥匙" (түлхүүр аваагүй) мөн. "哭了" эсвэл "敲错门了" гэсэн зүйл огт дурдагдаагүй.'),
  ('877a051e-a4ec-40db-9dc1-e58db1dbc20b'::uuid, '"今天很暖和,外面一点也不冷,你不用穿这么多衣服" (өнөөдөр дулаахан, гадаа огт хүйтэн биш, ийм их хувцас өмсөх шаардлагагүй) гэж хэлж байгаа тул өнөөдрийн цаг агаар "很暖和" (дулаахан) мөн.'),
  ('55064bb1-748c-4a23-a779-02c6e693dc2b'::uuid, '"这么厚的书,你竟然三天就看完了?" (ийм зузаан ном гурван хоногт л уншиж дуусгачихав уу?) гэж гайхан асуусан тул тухайн үг хэлж буй эрэгтэй маш их "很吃惊" (гайхсан) байгааг харуулж байна.'),
  ('060e62b7-e72d-43f9-aaca-995b38c4ff6c'::uuid, '"信封右下角,还得写上寄信人的姓名和地址" (дугтуйны баруун доод буланд илгээгчийн нэр, хаягийг бичих хэрэгтэй) гэж сануулахад "不好意思,我忘记了" гэж хариулсан тул эрэгтэй бичихээ мартсан зүйл нь "寄信人地址" (илгээгчийн хаяг) мөн.'),
  ('a174a398-6891-46b0-8ddd-17e7ba8cc4d8'::uuid, '"经理,我这次又出错了,总给您带来麻烦,真抱歉" (менежер ээ, би дахиад алдаа гаргалаа, байнга танд төвөг учруулж байна, уучлаарай) гэж хэлж байгаа тул эрэгтэй "总出错" (байнга алдаа гаргадаг) учраас уучлалт гуйж байна.'),
  ('bfe2e037-1ffa-461d-8481-51ef22803784'::uuid, 'Эмэгтэй, эрэгтэй хоёр ''үргэлжлүүлж авирах хүчгүй боллоо'' гэж хэлээд, хамтдаа сууж жаахан идэх санал тавьж байна. Энэ нь ууланд авирч яваад завсарлаж байгааг харуулна, тиймээс зөв хариулт бол B (爬山, ууланд авирах). A (дэлгүүр тойрох), C (дараалал жагсах), D (жимс угаах) талаар яриагүй тул тохирохгүй.'),
  ('2a79f66d-4d48-42cd-a469-4efdde7cc876'::uuid, 'Эрэгтэй ''чемодан яагаад нээгдэхгүй байна, нууц код буруу байх нь ээ?'' гэж асуухад нөгөө нь сайн бод гэж хэлж байна. Энэ нь чемодангийн код тохирохгүй байгаагаас болж нээж чадахгүй байгааг илтгэх тул зөв хариулт D (行李箱打不开, чемодан нээгдэхгүй байна). Зам төөрөх, паспорт алдах зэрэг тухай ярьсангүй тул бусад сонголт тохирохгүй.'),
  ('65ad90ad-b8d5-455f-8e6a-dd75d80d7cc9'::uuid, 'Аав явган тоглоом хийхээр гарахдаа охиноосоо асуухад, охин нь ''жүүс аваад ир, хөргөгчид ундаа алга боллоо, зөвхөн алимны жүүс'' гэж хэлж байна. Тиймээс эмэгтэй эрэгтэйгээс жүүс худалдаж авчрахыг хүссэн нь тодорхой тул зөв хариулт A (买果汁). Ширээ арчих, гал тогоо цэвэрлэх, гүйлт хийх тухай ярьсангүй.'),
  ('ddc5f082-ea41-43a5-8bb3-71b4b5fafe4f'::uuid, 'Ярилцагч эмэгтэйд ''ийм залуу байхдаа докторын зэрэг хамгаалчихсан юм байна'' гэж гайхаж, эмэгтэй нь магистр төгсөөд шууд докторт орсноо хэлж байна. Энэ нь эмэгтэйн тухай мэдэх зүйл бол докторын зэрэг хамгаалсан явдал болохыг батална, тиймээс зөв хариулт C. Өндөр биетэй, профессор, гадаадаас ирсэн тухай яриагүй тул бусад сонголт буруу.'),
  ('ec87001b-c569-48e8-a221-bd397d1302dd'::uuid, 'Хаврын баярт хаашаа явахаа асуухад эрэгтэй ''бид өвөө эмээ дээрээ явж, шинэ жил тэмдэглэнэ'' гэж хэлж байна. Энэ нь эрэгтэйн тухай зөв мэдээлэл бол шинэ жилээр төрсөн нутагтаа явна гэдгийг батална, тиймээс хариулт D. Тоглолт үзэх, тасалбар аваагүй, өрөө цэвэрлэх тухай ярьсангүй.'),
  ('6ae42a1d-6677-4bc5-9c65-f15c82fb149d'::uuid, 'Ресторанд мэндэлсэн охиныг хэн бэ гэж асуухад, тэр нь шинээр ирсэн сувилагч бөгөөд шинэ жилийн үдэшлэгт хамт тоглолт үзүүлсэн гэж тайлбарлаж байна. Тиймээс тэд хэний тухай ярьж байгаа нь шинэ сувилагчийн тухай учир зөв хариулт C. Хөрш, эмч, зоогийн газрын үйлчлэгч гэсэн хувилбарууд таарахгүй.'),
  ('035ebf22-0c98-49e4-a72d-8dd4041f611c'::uuid, 'Эмэгтэй жолоочид ''нисэх онгоцны буудал руу яв, би онгоцондоо хоцроод байна, түргэн яв'' гэж хэлж байна. Энэ нь эмэгтэйн очих газар нь нисэх онгоцны буудал болохыг шууд илтгэх тул зөв хариулт A. Элчин сайдын яам, номын сан, ойн парк тухай яриа огт байхгүй.'),
  ('e3dc328b-bd02-457f-a14d-8898546449c0'::uuid, 'Амралтын өдөр сургуулийн спорт заалан дээр теннис тоглохоор явахыг санал болгож, хүн их байх эсэхийг эргэлзэх боловч өвлийн амралт эхэлсэн тул хүн бага байх гэж хэлж байна. Тиймээс амралтын өдрөөр хийхээр төлөвлөж буй зүйл нь теннис тоглох тул зөв хариулт B. Диван сонгох, хүчийн бэлтгэл хийх, виз хийх тухай яриагүй.'),
  ('f2f7ca03-15b1-4094-94e0-1032687e2c05'::uuid, 'Бантангийн амтыг асуухад эрэгтэй ''амттай байна, гагцхүү давс их хийсэн тул жаахан давслаг'' гэж хэлж байна. Энэ нь эрэгтэйн бодлоор бантан жаахан давслаг байгааг илтгэх тул зөв хариулт D (有点儿咸). Хүчиллэг, халуун ногоотой, мах бага тухай яриагүй.'),
  ('b060bac3-a187-46b4-8f51-570714b67bc6'::uuid, 'Зурган дээрх ач хүүгийнх нь тухай асуухад эмээ нь ''нэг нас дөрвөн сартай болсон, аав ээж гэж дуудаж чаддаг, зарим энгийн үг хэлж чаддаг болсон'' гэж хэлж байна. Тиймээс ач хүүгийн тухай мэдэх зүйл бол дөнгөж ярьж сурч буй явдал тул зөв хариулт C (刚会说话). Гэрлэсэн, зуны амралттай, тоглоом дуртай гэсэн зүйл тухай яриагүй.'),
  ('ba3b542c-7503-4b90-937a-bf6454016980'::uuid, 'Ярьж буй хүн энэ удаагийн хэлэлцүүлэг маш сайн болсон, асуудлууд сонирхолтой байсан бөгөөд ялангуяа багшийн ярьсан богино түүх нь хэлэлцүүлгийг илүү сонирхолтой болгосон гэж дүгнэж байна. Энэ нь тухайн үйл ажиллагааны талаарх дүгнэлт эерэг байгааг харуулах тул зөв хариулт A (很不错, маш сайн). Романтик, амжилтгүй, албан бус гэсэн үнэлгээ өгөөгүй.'),
  ('8e90690e-dae5-4038-8a3b-d2d6b7eb5a02'::uuid, 'Хэлэлцүүлгийг илүү сонирхолтой болгосон зүйл нь багшийн ярьсан богино түүх байсныг өмнөх хэсэгт дурдсан. Тиймээс багш үйл ажиллагааны үеэр хийсэн зүйл бол түүх ярьсан явдал тул зөв хариулт B (讲故事). Хошин үг хэлэх, төгөлдөр хуур тоглох, сэтгүүл унших тухай яриагүй.'),
  ('81d91ff8-b6a0-4259-8c5b-45d7c503be46'::uuid, 'Үдэшлэг дуусах гэж байхад хэн ч түүнийг бүжиглэхийг урьсангүй тул тэр гунигтай санагдаж байгаа тухай өгүүлж байна. Тиймээс гунигтай болсны шалтгаан нь хэн ч бүжиглэхийг урьсангүй байсан явдал тул зөв хариулт D. Үзэгч цөөн, дуулж чадахгүй, тоглолт сонирхолгүй гэсэн шалтгаанууд тухай яриагүй.'),
  ('1242c193-d34a-4464-82ff-cc30ef536748'::uuid, 'Царайлаг залуу ойртож ирээд бүжиглэхийг урьсан мэт харагдсан ч, эцэст нь ''болж байна, тэгвэл би чиний суудал дээр суучихъя'' гэж хэлсэн нь түүний жинхэнэ зорилго суудал олох байсныг харуулж байна. Тиймээс зөв хариулт C (找座位, суудал хайх). Тамхи татах, гэр лүү явах, ариун цэврийн өрөө рүү явах тухай яриагүй.'),
  ('fa740179-f50a-4b2a-9342-ee5203b56616'::uuid, 'Бамбарууш дэлхий даяар ердөө мянга орчим ширхэг үлдсэн болохыг өгүүлж байна. Тиймээс бамбарууш тухай мэдэх боломжтой зүйл бол тоо толгой цөөн болохыг зөв хариулт B (数量少) харуулна. Урт хамар, зоригтой, усан үзэм дуртай тухай мэдээлэл байхгүй.'),
  ('94fa9345-664a-47d1-896f-b1c1ee16415e'::uuid, 'Хятад улс 1957 оноос эхлэн найрсаг харилцаагаа илэрхийлэх зорилгоор бусад орнуудад бамбарууш бэлэглэж эхэлсэн тухай өгүүлж байна. Тиймээс бамбаруушийг гадаадад илгээсэн шалтгаан нь найрсаг байдлыг илэрхийлэх зорилготой байсан тул зөв хариулт C. Туршлага хуримтлуулах, орчинд дасах, орлого нэмэгдүүлэх тухай өгүүлээгүй.'),
  ('39c062ff-a45a-4881-9900-d8ea136cf177'::uuid, 'Жижиг Жан хуульчийн ажлаа орхиж зохиолч болохоор шийдэхэд найзууд нь харамсаж, эцэг эх, төрөл садан нь ч дэмжээгүй тухай өгүүлж байна. Энэ нь хүмүүсийн ерөнхий хандлага түүнийг ойлгож чадаагүй байсныг харуулах тул зөв хариулт D (普遍不理解). Уй гашуу, атаархал, хөдөлгөөнд автах тухай өгүүлээгүй.'),
  ('cbb03932-48d0-4f8e-afdf-1dd6cfa6e5b9'::uuid, 'Одоо түүнийг алдартай зохиолч болсон гэж өгүүлж, өөрийн шийдвэрийг зөв байсныг бүгдэд нотолсон тухай хэлж байна. Тиймээс Жижиг Жаны тухай зөв мэдээлэл бол зохиолч болсон явдал тул хариулт C (当了作家). Харамссан, уурлаг зантай, эцэг эхдээ талархаж буй тухай өгүүлээгүй.'),
  ('290e8c29-6ca3-49a6-bf8c-ebeab74c6b27'::uuid, 'Судалгаагаар шударга, дулаан сэтгэлтэй, эелдэг хүн илүү их найз нөхөдтэй байдаг бол ихэрхэг, бусдыг шүүмжлэх дуртай, өрөвдөх сэтгэлгүй хүн хамгийн дургүйцэл төрүүлдэг тухай өгүүлж байна. Тиймээс хүмүүст дургүйцэл төрүүлдэг зан чанар бол ихэрхэг байдал тул зөв хариулт D (骄傲的). Залхуу, тэнэг, ичимхий тухай өгүүлээгүй.'),
  ('a85a16d2-ebff-4c1a-8ca6-bdebfb01348f'::uuid, 'Энэхүү өгүүллэгийн гол санаа нь шударга, дулаан сэтгэлтэй, эелдэг байх нь хүмүүсийн дунд илүү их хүндлэл, найз нөхөдтэй болгодог гэдгийг онцолж байна. Тиймээс сургамж бол хүн шударга байх ёстой гэдэг тул зөв хариулт D (做人要诚实). Идэвхтэй ажиллах, уучлах, харилцан ойлголцох тухай гол санаа биш.'),
  ('a0bc05fe-a08b-45b4-be57-16fd2244b8e2'::uuid, 'Ажилтнаас ''Ван дарга та ирэх долоо хоногийн худалдааны хэлэлцүүлэгт очих уу?'' гэж асуухад, эрэгтэй ''компанийн ажил их байна, нарийн бичгийн дарга явтугай'' гэж хариулж байна. Энэ нь тэрээр завгүй байгаагаас болж очихгүй байгааг илтгэх тул зөв хариулт A (太忙). Аж ахуйн аялалд явна, сонирхохгүй байна, бэлтгэл хангалтгүй гэсэн шалтгаан дурдаагүй.'),
  ('8d5f7f10-8aee-455c-ba3a-edd01ff3f146'::uuid, 'Амралтын өдөр загас барихаар явахыг санал болгоход, эмэгтэй ''за, би яг л хөдөө гарахаар төлөвлөж байсан'' гэж хариулж байна. Энэ нь тэр саналыг зөвшөөрч байгааг илтгэх тул зөв хариулт B (同意去钓鱼). Амралтын өдөр ажиллана, далайн хоолонд харшилтай, хөдөө гарахыг хүсэхгүй байна гэсэн зүйл ярьсангүй.'),
  ('a968b56b-9157-4585-b304-4d2b112d96a9'::uuid, 'Редактор ''дахин нэг шалгаж үз, дээр нь цэг таслалын алдаа байна'' гэж хэлж байна. Тиймээс редакторын санал бол дахин шалгах явдал тул зөв хариулт C (再检查一下). Үг тоо их, бүтэц эмх замбараагүй, дүрмийн алдаатай гэдгийг тодорхой дурдаагүй.'),
  ('8de62383-4232-4125-935a-37570c60d8e4'::uuid, 'Эмэгтэйн бүжиг сайн байгааг магтаж, мэргэжлийн бэлтгэл авсан бизгэ гэж асуухад, тэр багадаа хэдэн жил бүжиг сурч, суурьтай гэж хариулж байна. Тиймээс эмэгтэйн тухай мэдэх зүйл бол өмнө нь бүжиг сурч байсан явдал тул зөв хариулт B (学过跳舞). Жүжигчин, анх удаа тоглож байна, эрэгтэйд бүжиг заана гэсэн зүйл ярьсангүй.'),
  ('c8f8372b-302e-4acf-b7f4-f74ac5ba4520'::uuid, 'Эрэгтэйн гар бэртсэн гэж сонссон, ноцтой юу гэж асуухад тэр ''зүгээр ээ, зөвхөн арьсны өнгөц шарх, эм түрхвэл сайжирна'' гэж хариулж байна. Тиймээс эрэгтэй бэртсэн явдал тодорхой тул зөв хариулт A (受伤了). Ухаан алдсан, хөл цусархаг, мэс засал хийлгэсэн тухай ярьсангүй.'),
  ('f9879d4e-0374-4708-9887-45542ae0dda1'::uuid, 'Ангийн хамт олны уулзалт зохион байгуулахаар олон хүний утасны дугаар өөрчлөгдсөнийг олж мэдээд, шинэ хаягийн дэвтэр хийх шаардлагатай гэж ярилцаж байна. Тиймээс эмэгтэй хийхийг хүсэж буй зүйл бол шинэ хаягийн дэвтэр хийх явдал тул зөв хариулт B (做通讯录). Ангийнхантайгаа холбогдох, дугаараа солих, уулзалтын газраа өөрчлөх тухай биш.'),
  ('7097d6c4-8c6e-4c3b-a454-e371555c574f'::uuid, 'Төлөвлөгөөний тухай санал асуухад, ''үнэ цэнэ бага, хэрэгжүүлэхэд хэцүү, манай асуудлыг ч шийдэхгүй'' гэж хариулж байна. Тиймээс тэр төлөвлөгөөг тустай гэж үзэхгүй байгааг илтгэх тул зөв хариулт B (帮助不大). Хялбар хэрэгжинэ, маш үнэ цэнэтэй, онолын хэт их гэсэн үнэлгээ өгөөгүй.'),
  ('99627946-85aa-4c9b-a7d6-05d0b666254d'::uuid, 'Дипломын ажлын сэдвийн талаар асуухад, багш нь судалгааны хүрээ хэт өргөн байгаа тул хумих хэрэгтэй гэж хэлсэн байна. Тиймээс сэдвийн асуудал бол судалгааны хүрээ өргөн байгаа явдал тул зөв хариулт C (研究范围大). Өнцөг гажсан, шинэлэг зүйлгүй, судлах ач холбогдолгүй гэсэн зүйл ярьсангүй.'),
  ('3691adb0-fdf3-4f8d-8067-85e07c4f84a7'::uuid, 'Ороолтын загварыг магтаж, хаанаас авснаа асуухад, эхнэрийнхээ нэхсэн зүйл гэдгийг хэлээд, гэвч өнгө нь хэтэрхий тод гэж боддогоо хэлж байна. Тиймээс эрэгтэй ороолтыг өнгө нь хэт тод гэж боддог тул зөв хариулт B (颜色艳). Нимгэн, чанар муу, дизайн энгийн гэсэн үнэлгээ өгөөгүй.'),
  ('cbb45bce-be74-456b-a322-eaf137ddb8e4'::uuid, 'Тэр охин манай орцны хөрш үү гэж асуухад, тийм ээ, гадаад газар тохиолдоно гэдэг сайхан аз таарлаа, очиж мэндэлье гэж хэлж байна. Тиймээс тэдний тухай мэдэх зүйл бол хөршөө таамгүй газар тааралдсан явдал тул зөв хариулт C (碰到了邻居). Зам төөрсөн, хүн андуурсан, тэр охиныг харж байгаагүй гэсэн зүйл буруу.'),
  ('32928fb9-5680-43e8-8b27-e6b7e7ef7c86'::uuid, 'Том шуудангийн дугтуй одоо хаана байгааг асуухад, ''би чиний унтлагын өрөөнд тавьсан, дараа нь юмаа замбараагүй бүү тавь'' гэж хариулж байна. Тиймээс дугтуй одоо унтлагын өрөөнд байгаа тул зөв хариулт A (卧室). Зочны өрөө, тагт, ажлын өрөө гэсэн газар дурдаагүй.'),
  ('1173f9ba-68b3-485d-b1c3-ff1907d2af4c'::uuid, 'Ойролцоо шинээр нээгдсэн Сычуань ресторан руу очиж амтлаад үзье гэж санал болгоход, эмэгтэй ''сүүлийн өдрүүдэд ходоод муу байна, эмч халуун ногоотой хоол багасга гэсэн'' гэж татгалзаж байна. Тиймээс эмэгтэй Сычуань хоол идэхийг хүсэхгүй байгаа шалтгаан бол ходоод муу байгаа явдал тул зөв хариулт C (胃不舒服). Дөнгөж идчихсэн, ресторан хол, халуун ногоо дургүй гэсэн шалтгаан биш.'),
  ('72d84cec-0cbb-420f-811c-08ee30fb225d'::uuid, 'Эрэгтэй утсаа санаандгүй тасалсандаа уучлал хүсэж, маргааш өглөө есөн цагт хүний нөөцийн хэлтэст ирж бүртгүүлэхийг мэдэгдэхийн тулд утасдсан гэж хэлж байна. Тиймээс эрэгтэй эмэгтэйд утасдсан шалтгаан бол ажилд орохыг мэдэгдэх явдал тул зөв хариулт B (通知她去上班). Уучлал хүсэх, анкет авахуулах, шалгалтын дүн мэдэгдэх зорилгоор биш.'),
  ('9c03df98-4a92-4a8b-ae2e-e5da19202cac'::uuid, 'Одоо магистрант шалгалтад бэлдэх ч амжина, шаардлагатай ном байна гэж хэлэхэд эмэгтэй маш их баярлаж, номоо надад зээлээд өг, би цаг гарган давтъя гэж хариулж байна. Тиймээс эмэгтэйн тухай мэдэх зүйл бол магистрант шалгалт өгөх бодолтой байгаа явдал тул зөв хариулт A (想考研). Ном худалдаж авах, давталтаа дуусгасан, зорилгогүй гэсэн зүйл буруу.'),
  ('ea43e4dc-6ade-4891-b601-548f8a3eba61'::uuid, 'Киноны хадмал орчуулга ба дуу хоёр таарахгүй байгааг хачирхалтай гэж хэлээд, тоглуулагчийг дахин нээж үзэх, болохгүй бол дахин татаж авах шаардлагатай гэж ярьж байна. Тиймээс кино асуудал бол хадмал орчуулга ба дуу тохирохгүй байгаа явдал тул зөв хариулт D. Хадмал алга, хятад орчуулгагүй, дэлгэц тодорхой бус гэсэн асуудал биш.'),
  ('eab70ac2-7df6-4452-b55c-7d29230b2d12'::uuid, 'Агааржуулагч суулгагч эмэгтэйд, бид гарлаа, хагас цагийн дараа очно гэхэд эмэгтэй ''юу? Би маргаашийн цагийг захиалсан шүү дээ'' гэж гайхаж байна. Тиймээс эмэгтэйн үг эрэгтэй цагийг андуурсныг илтгэх тул зөв хариулт C (男的弄错时间了). Үнэ тохирохгүй, суулгуулахгүй болсон, үйлчилгээ муу гэсэн шалтгаан биш.'),
  ('771e13db-e37b-4160-8320-0e2d5a7b04f0'::uuid, 'Уг зохиолч дөнгөж утга зохиолын шагнал хүртсэн гэсэн номыг харж байгааг тэмдэглэхэд, эрэгтэй сонины редакцаас түүнтэй ярилцлага авахаар илгээсэн тул урьдчилан бэлтгэл хийж байгаагаа хэлж байна. Тиймээс тэр номыг унших шалтгаан бол ярилцлагад бэлдэж байгаа явдал тул зөв хариулт D (为采访做准备). Найзын санал болгосон, номын борлуулалт сайн зэрэг шалтгаан биш.')
) as v(id, explanation)
 where t.id = v.id;

update mock_test_questions as t
   set explanation_mn = v.explanation
  from (values
  ('03368562-55b5-4c8c-845b-f34fee85ab1b'::uuid, 'Бүртгэлийн холбогдох журмыг тодорхой асуусан уу гэж асуухад, тодорхой асууж, шаардлагатай материалаа бэлдчихсэн гэж хариулж байна. Тиймээс тэд бүртгэлийн журмын тухай ярьж байгаа нь тодорхой тул зөв хариулт B (注册手续). Сурталчилгаа, бизнесийн лиценз, ажилд авах төлөвлөгөө тухай ярьсангүй.'),
  ('0f257db9-ec67-49fc-a485-c1335be8b7fe'::uuid, 'Маргааш ууланд авирах арга хэмжээнд оролцох уу гэж асуухад, цаг агаарын урьдчилсан мэдээгээр цас орно гэсэн тул арга хэмжээ хойшлогдсон, тодорхой цагийг дараа мэдэгдэнэ гэж хариулж байна. Тиймээс хойшлогдсон шалтгаан бол цас орох гэж байгаа явдал тул зөв хариулт A (要下雪). Мөнгө хүрэлцээгүй, зам мөс болсон, оролцогч цөөн гэсэн шалтгаан биш.'),
  ('42815f56-6ab8-4ac4-8750-5b8d543285c0'::uuid, 'Багш эмэгтэйд ''сүүлийн үеийн шатрын тоглолт сайн болж байна, ийм байдлаа хадгалбал финалд орно'' гэж магтаж байна, эмэгтэй баярлалаа гэж хариулж байна. Тиймээс энэ нь эмэгтэйн сүүлийн үеийн байдал маш сайн байгааг харуулах тул зөв хариулт D (女的状态很好). Тэр аль хэдийн финалд орсон гэж хараахан баталгаажаагүй тул C буруу, зориг бүү хая, дасгал нэмэгдүүлэх зэргийг ч дурдаагүй.'),
  ('2d0f32c0-ccdd-477d-b109-b86287eedb47'::uuid, 'Энэ улирлын теннисний ангид бүртгүүлж болох уу гэж асуухад, болно, ирэх долоо хоногт хичээл эхэлнэ гэж хариулж, бүртгэлийн маягт хүсэж байна. Тиймээс эмэгтэй хийхийг хүсэж буй зүйл бол теннис сурах явдал тул зөв хариулт C (学网球). Турах, хичээл болиулах, дасгалжуулагчаа солих тухай ярьсангүй.'),
  ('121dc547-eff9-489a-9c20-7d42a455d867'::uuid, 'Хананд өлгөөстэй цаг ташуу болсон эсэхийг асуухад, тийм ээ жаахан хазайсан гэж хариулж, сандал зөөж засах гэхэд, гутлаа тайлаад авдар дээр гарвал болно гэж хэлж байна. Тиймээс харилцан яриа нь цагны ташуу болсон тухай тул зөв хариулт A (钟歪了). Цаг зогссон, сандал бохирдсон, авдар эвдэрсэн тухай ярьсангүй.'),
  ('5b17699a-ec29-4315-ba0f-f34c24881567'::uuid, 'Даргад өчигдрийн хурлын тэмдэглэл өгөхөд, маргааш гэнэт Шанхайд явах ажил гарсан тул онгоцны тасалбар захиалж өгөхийг хүсэж, өглөө есөн цагийн орчим гэж цагийг тодорхойлж байна. Тиймээс эрэгтэй эмэгтэйгээр хийлгэхийг хүссэн зүйл бол онгоцны тасалбар захиалах явдал тул зөв хариулт A (订机票). Орчуулга хийх, тэмдэглэл хийх, буудал дээр хүн авах тухай биш.'),
  ('6368f60e-86b8-4667-adfa-a49cef157d5c'::uuid, 'Эмэгтэй энэ сарын дундуур жилийн амралтаа авч, Юньнань руу нэг долоо хоног аялна гэж хэлэхэд, нөгөө нь өөрийн жилийн амралт аль хэдийн дууссан тул хамт явж чадахгүйдээ харамсаж байна. Тиймээс харамссан шалтгаан бол хамт явах боломжгүй болсон явдал тул зөв хариулт D (不能一起去). Юньнаньд очиж байгаагүй, найз хамтрагчгүй гэсэн шалтгаан биш.'),
  ('27da96d3-8bac-4baa-88c5-218fcbc8d7b8'::uuid, 'Өнгөрсөн удаа ярьсан төслийг батлагдсан уу гэж асуухад, ''хараахан, бид дөнгөж төлөвлөгөөгөө өргөн барьсан'' гэж хариулж байна. Тиймээс тухайн төслийн тухай мэдэх зүйл бол хараахан батлагдаагүй байгаа явдал тул зөв хариулт A (还没批). Ашиг өндөр, зээл шаардлагатай, татгалзагдсан тухай ярьсангүй.'),
  ('47035d00-b3d3-4b37-a3c6-bf40bec61f25'::uuid, 'Дахин интернетээр юм худалдаж авч байна уу гэж асуухад, үгүй, барааг буцаах хүсэлт гаргаж байна гэж хариулаад, худалдаачны илгээсэн жинсэн өмд хэмжээ хэт том тул өмсөж чадахгүй байгаагаа хэлж байна. Тиймээс буцаалт хийх шалтгаан бол өмд хэт том болсон явдал тул зөв хариулт B (裤子太大). Гутал жижиг, өмд богино, юбка чөлөөтэй гэсэн зүйл ярьсангүй.'),
  ('31257bff-3748-4864-a012-5dcae02c393c'::uuid, 'Солонго гарлаа гэж хэлэхэд, өнгө нь тийм ч тод биш гэдгийг тэмдэглэж, агаарт байгаа бороо дуслын хэмжээ жижиг байх тусам солонгын өнгө улам бүдгэрдэг гэж тайлбарлаж, эрдэм шинжилгээний нэвтрүүлгээс мэдсэн гэж хэлж байна. Тиймээс ярилцлагын гол сэдэв бол солонгын өнгө тул зөв хариулт D (彩虹颜色). Бороо хэмжээ, зурагт нэвтрүүлэг, солонгын хэлбэр гол сэдэв биш.'),
  ('e0c8c7d9-1469-4b74-aba2-3bc75f1f5857'::uuid, 'Шуудан хүргэгч дугтуй хүлээж авахыг хүсэхэд эмэгтэй одоо байгууллагадаа биш байгаагаа хэлж, нэг цагийн дараа ирж болох уу гэж асуухад, эрэгтэй тохиромжгүй бол өөр хүнээр орлуулж авахуулж болно гэж санал болгож байна. Тиймээс эрэгтэйн санал бол өөр хүнээр орлуулж авахуулах явдал тул зөв хариулт A (找人代收). Ресепшнд ирж авах, одоо ирж авах тухай биш.'),
  ('f0361bd7-8ac2-4f25-b544-419e69abf996'::uuid, 'Зуучлагч тэдний ажлын байрны ойролцоо тохиромжтой байшин байгааг хэлж, очиж үзэхийг санал болгосон, тохирвол шууд түрээсийн гэрээ байгуулж болно гэж хэлж байна. Тиймээс тэд одоогоор байшин түрээслэхийг хүсэж байгаа нь тодорхой боловч гэрээ хараахан байгуулаагүй тул зөв хариулт B (他们想租房). Байшингийн талбай жижиг, гэрээ байгуулсан, худалдаа хийхэд тав тухтай гэсэн зүйл буруу.'),
  ('69358de3-b838-4d5f-88a1-f49ce99c51d9'::uuid, 'Номын шүүгээгээ цэгцлэж байхдаа нэгэн хамтарсан зургийг олсноо үзүүлж, энэ бол ажилд орсон эхний жилийн зураг биш үү гэж хэлж, гуч гаруй жил болсон гэдгийг тэмдэглэж байна. Тиймээс тэд харж байгаа зүйл бол хамтарсан зураг тул зөв хариулт A (照片). Сэтгүүл, өдрийн тэмдэглэл, шуудангийн карт тухай яриагүй.'),
  ('86294af0-eba9-44da-97be-0b41eddc9c64'::uuid, 'Харамч баян хэзээ ч зочин дуудаж байгаагүй атал, нэг өдөр хөрш нь түүний байшинг түрээслэн зочин дуудсанаас болж байшин их шуугиантай болсон тухай өгүүлж байна. Тиймээс байшин шуугиантай болсон шалтгаан бол хөрш нь байшин түрээслэн зочломжлоо тарааж байсан явдал тул зөв хариулт D. Төрөл садангийнхан ирсэн, баянгийн төрсөн өдөр, баян өөрөө зочломжлол хийсэн гэсэн зүйл буруу.'),
  ('3dad02c4-959d-4dec-a0e8-b7981555eed9'::uuid, 'Баян хүн туйлын харамч, хэзээ ч хүн зочломжилдоггүй гэж тодорхой хэлж байна. Тиймээс баянгийн зан чанар бол харамч байдал тул зөв хариулт A (小气). Өгөөмөр, зальтай, дулаан сэтгэлтэй гэсэн шинжийг харуулаагүй.'),
  ('13558938-680d-4c15-8599-7dec3898880e'::uuid, 'Хөгшин эмгэн горхины эрэг дээр төмөр саваа чулуун дээр үрж байхыг Ли Бай асуухад, ''би тор оёх зүү үрж байна'' гэж хариулж, өдөр бүр үргэлжлүүлбэл төмөр саваа улам нарийсаж, эцэст нь зүү болно гэж тайлбарлаж байна. Тиймээс эмгэн төмөр саваагаа юу болгохоор үрж байгаа нь тодорхой тул зөв хариулт A (针, зүү). Хутга, савх, тоглоом болгохоор үрж байгаагүй.'),
  ('53378d2e-d7e4-4a40-b47b-c4360a8a7a17'::uuid, 'Ли Бай багадаа ном идэвхтэй уншдаггүй байсан бөгөөд нэг өдөр номоо тэн хагасаас нь уначихаад, ийм зузаан ном хэзээ дуусах вэ гэж тэвчээргүйдэн, номоо хаяад тоглохоор гүйсэн тухай өгүүлж байна. Тиймээс Ли Байн тухай мэдэх зүйл бол анх удаа тэвчээргүй байсан явдал тул зөв хариулт D. Туслах дуртай, халамжтай, багаасаа хичээнгүй гэсэн зүйл буруу.'),
  ('6f75260f-b513-4ff6-a55c-61e3046aceeb'::uuid, 'Түүх төгсгөлдөө зөвхөн тэсвэр хатуужилтай, хичээж хөдөлмөрлөвөл л амжилтад хүрдэг гэдгийг онцолж байна. Тиймээс өгүүллэгийн гол санаа бол тэвчээртэй тэмүүлбэл амжилтад хүрнэ гэдэг тул зөв хариулт D. Ахмад настныг хүндэтгэх, харж мэдэх нь үнэн, эргэлзэх сэтгэл хэрэгтэй гэсэн санаа биш.'),
  ('437cbf61-c9e2-4710-b089-cd2ef7208e6e'::uuid, 'Баян хүн зурагчаас тогос зурахыг захиалж, нэг жилийн дараа очиход зурагч цаас гарган түргэн хугацаанд үзэсгэлэнтэй тогос зурж өгсөн боловч, түүний асуусан үнэ тавин түмэн болохыг сонсоод их гайхаж байна. Тиймээс баян хүн гайхсан шалтгаан бол зурагчийн үнэ хэт өндөр байсан явдал тул зөв хариулт B (画家要价高). Зураг алга болсон, зурагч худал хэлсэн, түргэн зурсан тухай гайхшрал биш.'),
  ('bb356667-3934-44ff-a164-627443d82532'::uuid, 'Зурагч баяныг өөр өрөөнд аваачихад тэнд тогос зурсан олон хог цаас овоолсон байсныг харуулж байна. Тиймээс баян хүн өөр өрөөнд юу харснаа тодорхой хэлж болно тул зөв хариулт D (一堆画着孔雀的废纸). Олон амьтан, ганц тогос, хүний захиалсан зураг тухай харсангүй.'),
  ('53cd01a5-07d8-4329-80f1-63fa757ad280'::uuid, 'Зурагч тогосыг хялбархан зурсан мэт харагдсан ч жинхэнэ дээрээ бүтэн нэг жилийн цаг хугацаа, хүчин чармайлт зарцуулан бэлтгэл хийсэн гэдгээ тайлбарлаж байна. Тиймээс зурагчийн тухай зөв мэдээлэл бол нэг жил бэлтгэсэн явдал тул зөв хариулт B (准备了一年). Зургаа урж хаясан, тогос зараагүй, баянтай худалдаа хийхийг хүсэхгүй байсан гэсэн зүйл буруу.'),
  ('0064251a-3d4c-41cd-bf46-8427643afcff'::uuid, 'Загас идэх дуртай сайд руу олон хүн загас бэлэглэдэг байсан ч, тэрээр хэзээ ч авдаггүй байсан тул сурагч нь юунд гайхаж, яагаад хүлээж авдаггүй юм бэ гэж асуужээ. Тиймээс сурагчийг ойлгомжгүй болгосон зан авир бол бэлэг болгон авчирсан загас хүлээж авдаггүй явдал тул зөв хариулт D. Загас идэх дуртай, зочин хүлээж авдаггүй, албан тушаал хүсэхгүй байгаа гэсэн зүйл буруу тайлбар.'),
  ('6b4539f7-8951-4ca6-884f-f3a6ae2475c9'::uuid, 'Сайд өөрөө тайлбарлахдаа, хэрэв тэр хүний загасыг авбал, тэдний хүссэнээр ажил хийх ёстой болно, энэ нь хууль зөрчихөд хүргэж болзошгүй гэж хэлж байна. Энэ нь хүмүүс загас бэлэглэсэн жинхэнэ шалтгаан бол түүгээр ямар нэг ажил хийлгэхийг хүссэн явдал болохыг илтгэх тул зөв хариулт B (求他办事). Талархал илэрхийлэх, загас тэжээдгийг мэдсэн, амттай загас хийдэг гэсэн шалтгаан биш.'),
  ('1692528d-b1a7-4946-b168-a25c4e32732b'::uuid, 'Сайд загас бэлэг авбал бусдын хүслээр ажил хийхэд хүрч, ингэснээр хууль зөрчиж болзошгүй тул авдаггүй гэж тайлбарласан нь бага зэргийн ашиг хонжоод хууль зөрчихөөс сэргийлэх ухаарлыг харуулж байна. Тиймээс өгүүллэгийн гол санаа бол жижиг ашиг олохыг завдаж болохгүй гэдэг тул зөв хариулт D (不要占小便宜). Харж мэдэх нь үнэн, даруу байх, бусдад итгэх ёстой гэсэн санаа биш.'),
  ('36fdaef3-d824-4e0c-8aa7-a53c31284347'::uuid, 'Бичлэгт хүн шинэ зуршил тогтооход дор хаяж 21 хоног хэрэгтэй гэдэг тухай ярьж, эхний 7 хоногт өөрийгөө санаатайгаар гүйхийг сануулах хэрэгтэй гэж хэлсэн байна. Тиймээс B (特意提醒自己) зөв. Харин A төлөвлөгөө гаргах, C хамт хөдөлгөөн хийх хүн олох, D ачааллыг нэмэгдүүлэх зэрэг сонголтууд бичлэгт огт дурдагдаагүй тул буруу.'),
  ('6ae11d3d-7ddb-4adb-a4e6-10773c43b913'::uuid, 'Бичлэгт шинэ зуршил буюу шинэ санаа тогтоохын тулд дор хаяж 21 хоног шаардлагатай гэдгийг ''21 хоногийн эффект'' гэж нэрлэдэг гэж тодорхой хэлсэн байна. Иймд D (养成新习惯至少要21天) зөв. А 21 дэх хоног хамгийн чухал гэдэг, В муу зуршлыг арилгахад хэцүү гэдэг, С танил зүйлээ хурдан мартдаг гэдэг зэргийг бичлэгт огт дурдаагүй.'),
  ('f56a403a-c793-40c6-be65-10a9ccd0b798'::uuid, 'Найз нь бага байхад цэцэрлэгт зугтахдаа шаахайгаа хашаан дотогш шидээд дараа нь заавал орж авах ёстой болгодог байсан тухай өгүүлжээ. Энэ нь A (把鞋扔进果园) сонголттой яг таарч байна. B хувцсаа тайлж авирах, C хамгийн намхан хана олох, D модонд түшиглэх зэргийг бичлэгт огт дурдаагүй тул буруу.'),
  ('94f01660-ebfd-4cb2-b9e0-f12bc226f3f2'::uuid, 'Бичлэгийн төгсгөлд ''ажил хэцүү мэт санагдвал ухрах замаа өөрөө таслах хэрэгтэй, учир нь эцсийн ганцаарчилсан байдал л бидний асар их чадавхийг сэрээдэг'' гэсэн гол санааг илэрхийлсэн байна. Энэ нь C (切断后路才能激发潜力) сонголттой тохирно. А бие даасан байх, В өөрийгөө бодитой үнэлэх, D өсөх явцад алдаа гаргах нь зайлшгүй гэдэг санаанууд энэ бичлэгийн гол санаа биш.'),
  ('208045ca-1dc2-4bb2-aa57-f4e681c1a9e7'::uuid, 'Зөөгч ''манайд далайн хоол сайхан бөгөөд яг одоо хямдрал байгаа'' гэж хэлсэн тул A (海鲜优惠) зөв. B үйлчилгээ сайн, C хэмжээ том, D нугас сайн зэргийг тухайн харилцан яриа огт дурдаагүй.'),
  ('0f5a6afd-e2f4-4c85-b1e3-7d0737ce1302'::uuid, 'Эрэгтэй хоолны вагон энэ чиглэлд байгаа эсэхийг асуухад, хоолны вагон 11 дүгээр вагонд, гурван вагон урагшаа явбал хүрнэ гэж хариулсан. Тиймээс A (餐车) зөв. B машины гараж, C бие засах газар, D тасалбар зарах газар зэрэг сонголтууд харилцан яриатай огт холбоогүй.'),
  ('5baac43a-01c0-4ea3-98bf-0864f15474cf'::uuid, 'Эмэгтэй доод давхрын автомат худалдааны машинаас жигнэмэг авахын тулд ваксель мөнгө байгаа эсэхийг асуусан тул D (买吃的) зөв. Тэрээр өөрөө мөнгө солиулах гэж бус, ноднд байгаа ваксель мөнгийг лавлаж байгаа тул C сонголт төөрөгдүүлдэг ч буруу. A мөнгө буцаах, B карт цуцлах зэрэг огт дурдагдаагүй.'),
  ('d1eecd95-f712-41a0-bc5f-db3417ef45d9'::uuid, 'Сяо Ли хэвлэлийн газарт хэрхэн ажилладгийг асуухад ''тэр их хичээнгүйлэн ажилладаг, ажлаа сайн хийдэг, гагцхүү харилцаанд тийм ч сайн биш'' гэж хариулжээ. Иймд C (工作勤奋) зөв. A хошин шог, B хүнлэг дулаан, D болгоомжгүй зэрэг шинж чанарууд бичлэгт байхгүй.'),
  ('ae9bab8d-e286-4868-8fde-0b8fcfbfd7ea'::uuid, 'Байрны талаар асуухад эрэгтэй ''зочны өрөө их том, гэрэлтэй ч, түрээс бага зэрэг буусан бол дээр байх байсан'' гэж хэлсэн. Тиймээс B (面积大) зөв. C бага зэрэг харанхуй нь эсрэгээрээ гэрэлтэй гэж хэлсэнтэй зөрчилдөж байгаа тул буруу, A эмх замбараагүй, D чимэглэл дутагдалтай зэргийг дурдаагүй.'),
  ('965410f0-5009-4b3f-9290-192d46058e6b'::uuid, 'Эмэгтэйгээс ханиад хүрсэн эсэхийг асуухад тэр үгүйсгэж, ''би цэцгийн тоосонцорт харшилтай, хавар болгонд ингэдэг'' гэж тайлбарлажээ. Тиймээс A (过敏了) зөв. B ханиад, C нойргүйдэл, D согтуу зэргийг бичлэгт огт дурдаагүй бөгөөд ханиадыг тэр эмэгтэй өөрөө үгүйсгэсэн.'),
  ('6dd98a05-24aa-4cb1-8056-8919581acd2e'::uuid, 'Эрэгтэй ах руугаа залгаж бэрийнхээ төрсөн эсэхийг асууж, ''хүү төрсөн, ээж хүүхэд хоёулаа эрүүл мэнд сайн'' гэсэн хариу авсан тул тэр эрэгтэй яг л аав болсон байна. Иймд C (当爸爸了) зөв. A их гунигтай гэдэг нь эсрэгээрээ баяртай сэтгэлтэй байгаатай зөрчилдөнө, B хоолой өвдсөн, D мэс засал хийлгэсэн зэргийг дурдаагүй.'),
  ('c1dc76af-224d-4ebb-8fa4-3cf284b48306'::uuid, 'Эрэгтэй ''би Ма даргатай уулзах цаг товлосон, түүнийг хайж байна'' гэж хэлсэн тул A (马主任) зөв. B Ма дасгалжуулагч, C Лю нарийн бичгийн дарга, D Лю захирал зэрэг нэрс бичлэгт огт гараагүй.'),
  ('8796fade-e5f2-41da-b8c0-1751d77593ea'::uuid, 'Эрэгтэйгээс нохой авахаар шийдсэн шалтгааныг асуухад ''аавдаа авсан юм, тэр саяхан тэтгэвэрт гарсан болохоор гэртээ ганцаараа уйдах вий гэж айсан'' гэж хариулжээ. Тиймээс C (怕爸爸寂寞) зөв. B тэр өөрөө тэжээвэр амьтан дуртай гэдгийг эхэнд нь үгүйсгэсэн, A найздаа өгөх, D тэтгэвэрт гарч завгүй байх зэрэг нь тэр аавыг биш өөрийг нь тодорхойлдог тул тохирохгүй.'),
  ('e0a23668-9fc0-4e8f-ae55-6e68b5861168'::uuid, '''Энэ дансан дахь бүх мөнгийг гарган аваад, дансаа хааж өгөөч'' гэсэн харилцан яриа банкны үйлчилгээтэй холбоотой байгаа тул C (银行) зөв. A баар, B талбай, D клуб зэрэг газар дансны үйлчилгээ хийдэггүй тул тохирохгүй.'),
  ('9b3b5d37-581b-4a55-b3a8-d51cb770d576'::uuid, 'Хөрш засвар хийж байгаа шалтгааныг асуухад ''шинэ залуу нүүж ирсэн, тэр барилгын инженер, харагдахад сайхан хүн юм билээ'' гэж хариулсан тул B (工程师) зөв. A нягтлан бодогч, C нэвтрүүлэгч, D радиогийн сурвалжлагч зэрэг мэргэжлүүд бичлэгт дурдагдаагүй.'),
  ('34bc3988-fbd6-4955-94f9-5267efdf9cea'::uuid, 'Ням гарагт музейд яагаад явж чадаагүйг асуухад ''явна гэж бодож байсан ч компанид гэнэт ажил гарч явж чадсангүй'' гэж хариулсан тул B (公司有事) зөв. D үзэсгэлэнд сонирхолгүй гэдэгтэй яг эсрэгээрээ ''явна гэж бодож байсан'' гэсэн нь зөрчилдөнө. A тасалбар авч чадаагүй, C өвчтэй хүн үзэх зэрэг огт дурдаагүй.'),
  ('ae5436c7-cda7-48b2-8a9e-a7833b4a22a0'::uuid, 'Бөгж хуруунаас гарахгүй болсон гэсэн асуудалд эрэгтэй ''гар дээрээ саван хийсэн ус түрхэж үзээрэй'' гэж зөвлөсөн тул D (在手上涂肥皂水) зөв. A дулаан усаар угаах, B илүү хүчтэй татах, C арьс арчилгааны бүтээгдэхүүн түрхэх зэргийг дурдаагүй.'),
  ('a265d7ca-b2e2-4ca2-a5d3-5edf5c201b22'::uuid, 'Сяо Ли бакалаврын шатандаа хуулийн мэргэжлээр сурч, магистрт орсны дараа бизнесийн удирдлагад шилжсэн гэж хэлсэн тул D (读过法律专业) зөв. Тэрээр одоо хуульч гэж хаана ч дурдаагүй (B), докторантур судалж байна гэсэн үг байхгүй (A), одоо бизнес хийж байна гэдэг ч (C) баталгаагүй.'),
  ('de8c2224-a400-435a-869d-b8d10e9588a5'::uuid, 'Хэлэлцээрийн тухай асуухад ''нөхцөл болзолоо тохирсон, пүрэв гарагт гэрээ баталгаажуулна'' гэж хариулсан. Тиймээс D (双方已谈好条件) зөв. A гэрээ байгуулсан гэдэг нь пүрэв гэсэн ирээдүйн үйлдэлтэй зөрчилдөнө, B гөлгөр байсан нь ''гэнэтийн зүйл гарсан''-тай зөрчилдөнө, C үр дүн мэдэгдэхгүй гэдэг нөхцөл тогтсонтой зөрчилдөнө.'),
  ('09d3c004-91d9-4303-a778-40a4fc6d1816'::uuid, 'Эмэгтэй инээж хараад байгаа нэвтрүүлгийг ''од хуулбарлаж дуурайдаг нэвтрүүлэг, дуураймал хийгчдийн хөдөлгөөн хэт хэтрүүлсэн, маш инээдтэй'' гэж тайлбарлажээ. Тиймээс A (很有趣) зөв. B уйтгартай, D шинэлэг зүйлгүй гэдэг эсрэгээрээ, C бодитой гэдгийг ч дурдаагүй.'),
  ('6b0c7c01-28d3-49f3-8c33-dbc88ffd2f3a'::uuid, 'Эмэгтэй ''нүд минь дахиад муудсан юм шиг байна, телевизийн бичвэрийг тод харахгүй байна'' гэж хэлсэн тул C (看不清字幕) зөв. B шинэ нүдний шил хийлгэсэн гэдэг нь маргааш үзлэг хийлгэх төлөвлөгөө учир одоохондоо болоогүй, A суваг сольмоор байна, D нүдний тос олдохгүй байна зэргийг дурдаагүй.'),
  ('e5b8fc26-3ed6-464d-a560-ff6c328241dd'::uuid, 'Эрэгтэй ''Бээжингийн хутун гудамжны тухай илтгэлээ хугацаандаа гардуулж чадахгүй байх, олсон материал минь хангалтгүй байна'' гэж санаа зовниж байгаа тул C (不能按时交论文) зөв. Уг санаа зовнил нь тодорхой хугацаанд гардуулах тухай байсан тул D материал худалдаж авч чадахгүй гэдэг нь бодит асуудлыг яг тусгаж чадахгүй, A төөрөх, B ном унших цаг байхгүй зэргийг дурдаагүй.'),
  ('94a21bf0-7502-442a-8dfa-d41575a74652'::uuid, 'Сяо Ван зурсан гэрэл зураг олон улсын уралдаанд шагнал авсныг сонсоод найз нь ''тэр шагнал авахад би огтхон ч гайхаагүй, тэр үргэлж хамгийн гайхамшигтай мөчийг барьж чаддаг'' гэж хэлсэн. Тиймээс D (小王摄影技术很好) зөв. A их гайхсан гэдэг нь ''огтхон ч гайхаагүй'' гэсэнтэй шууд зөрчилдөнө, В шагналыг найз нь бус Сяо Ван авсан, C байгалийн үзэсгэлэн зурах дуртай гэдгийг дурдаагүй.'),
  ('aeeecb0f-687e-43cc-becd-bbdb6d5df869'::uuid, 'Лоо Жаны компанийг ийм сайн удирддагт нь ''үнэхээр биширмээр байна'' гэж эмэгтэй хэлсэн тул C (令人佩服) зөв. A өөртөө итгэлтэй, B үр ашиг өндөр гэдгийг дурдаагүй, D бизнес хийхэд тохиромжгүй гэдэг нь компаниа өргөжүүлж, хойд зах зээлд орох гэж байгаа агуулгатай шууд зөрчилдөнө.'),
  ('c0e543cc-f371-4f03-a7e6-9a27a7603740'::uuid, 'Охин нагацдаа нууц хэлэхийн өмнө ''чи бусдад хэлэхгүй гэж амлах ёстой'' гэж шаардаж, нагац нь ''чамаас болон надаас өөр гуравдагч хүн мэдэхгүй гэдгийг амлая'' гэж хариулсан. Тиймээс D (别把秘密说出去) зөв. A магтаах, B тоглох, C тоглоом худалдаж авах зэргийг эмэгтэй хүсээгүй.'),
  ('b45a2f24-3606-4529-ab43-a543042756a8'::uuid, '''Энд онгоцны суудлын тасалбар солиулж байна уу?'' гэж асуухад ажилтан ''иргэний үнэмлэхээ өгөөрэй, бүрдэл хийж өгье'' гэж хариулсан тул B (换登机牌) зөв. A нууц үг оруулах, C хөшиг сонгох, D иргэний үнэмлэх дахин авах зэргийг дурдаагүй, үнэмлэхийг зөвхөн бүрдэл хийхэд шаардсан.'),
  ('80eee5f8-938d-4600-8454-b6fabbad3b68'::uuid, 'Жолооны үнэмлэхтэй болсон эсэхийг асуухад нөгөө хүн ''дараа сарын дундуур шалгалт өгнө, гэхдээ жолоо барихаараа сэтгэл түгшдэг'' гэж хариулжээ. Тиймээс D (开车时很紧张) зөв. C шалгалт өгсөн гэдэг нь шалгалт хараахан болоогүй байгаатай зөрчилдөнө, A шинэ машин авсан, B авто сургуульд ажилладаг зэргийг дурдаагүй.'),
  ('2dd0f4df-9921-4740-9e39-9342a4eafd8f'::uuid, 'Халбага дангаараа зарах эсэхийг асуухад худалдагч ''уучлаарай эрхэм ноён, энэ хэрэглэлийг зөвхөн бүхэл иж бүрдлээр нь худалддаг'' гэж хариулжээ. Тиймээс D (是整套售出的) зөв. A үнэтэй, B хямдрал хийж байгаа, C ганцхан иж бүрдэл үлдсэн зэргийг дурдаагүй.'),
  ('5177d28b-8b72-445f-a28f-4d2d276c51c1'::uuid, '''Өчигдрийн ярилцлага ямар байсан бэ?'' гэж асуухад ''мэдэгдэл хүлээх ёстой гэсэн, эцсийн шийдвэр ирэх долоо хоногт л гарна'' гэж хариулсан тул тэд ярилцлагын үр дүнгийн тухай ярьж байна, өөрөөр хэлбэл B (面试结果) зөв. A ажлын төлөвлөгөө, C цалин хангамж, D цагийн ажлын шаардлага зэргийг дурдаагүй.'),
  ('156d41df-dff2-4e6b-94f7-eb44723a498c'::uuid, '''Одоо өрөө байна уу?'' гэж асуухад ''стандарт өрөө дууссан, харин бизнес өрөө байна, одоо жуулчны улирал болохоор хүн ихтэй байна, зочин саяхан гарсан өрөө'' гэж хариулсан нь буудлын харилцан яриа болохыг харуулж байна. Тиймээс A (酒店) зөв. B фитнес заал, C элчин сайдын яам, D зоог барих танхим зэрэг өрөөний бэлэн байдал, зочин гарсан гэх мэт нөхцөлд тохирохгүй.'),
  ('5a2e9bfd-69f7-4338-98f8-6d29f18a532a'::uuid, '''Карт ажиллах уу?'' гэж асуусан хүн бэлэн мөнгөөр л авдаг гэдгийг мэдээд ''сайн, надад падаан бич'' гэж хэлж байгаа буюу яг тэр хүн мөнгөө төлж байгаа юм. Тиймээс C (男的在付款) зөв. B карт уншигч эвдэрсэн гэж хэлээгүй, зөвхөн бэлнээр авдаг гэсэн; D эсрэгээрээ падаан бичиж өгсөн; A эмэгтэй мөнгөгүй гэдгийг ч дурдаагүй.'),
  ('de32bf54-78a1-4101-a760-578e532e6ad0'::uuid, '''Чи яагаад үсээ ингэж богино хайчлуулав?'' гэж асуухад тэр эмэгтэй ''шинэ засалт хийлгэхийг хүссэн юм, яасан сайхан харагдаж байна биз?'' гэж баяртайгаар хариулсан тул C (剪短发了) зөв. A сэтгэл муутай гэдэг нь баяртай хариулттай зөрчилдөнө, B үсээ буржгарлуулсан бус хайчилсан, D түрийвч алдсан зэргийг дурдаагүй.'),
  ('a79ec888-9852-4163-8e5b-3f085c14e8be'::uuid, 'Эмэгтэй эрэгтэйгээс зураг засах программ байгаа эсэхийг асууж, ''бүртгэлийн сайтад шаардсан хэмжээтэй адил болгож зургийг минь засаж өгөөч'' гэж хүссэн тул D (修改照片大小) зөв. A программ суулгах, B бүртгэлийн маягт бөглөх (энэ бол эрэгтэй өөрөө хийж байгаа зүйл), C бүртгэлийн хураамж төлөх зэрэг огт хамаагүй.'),
  ('6fa97f0e-af0f-4170-aba9-969214f70af6'::uuid, '''Цэнэглэгчийн улаан гэрэл асаж байвал цэнэглэгдээгүй, ногоон гэрэл асвал дүүрсэн гэсэн үг, одоо ч гэсэн улаан байна'' гэж ярьсан тул D (手机还没充满电) зөв. A утсаа унтраасан, B цэнэглэгч эвдэрсэн, C батарейны загвар тохирохгүй байна зэргийг бичлэгт дурдаагүй.'),
  ('1ded8943-9f96-49f3-a57c-5305fea9999e'::uuid, 'Хүүхэд лонхны амнаас чихрийг бүтэн атгаараа авсны улмаас гараа буцааж авч чадаагүй, чихрээ ч өгөхгүй, гараа ч гаргаж чадахгүй болсноос айж уйлсан тухай өгүүлсэн. Тиймээс B (手拿不出来) зөв. A гар нь гэмтсэн, C чихэр бохирдсон, D аав загнасан зэрэг бичлэгт дурдаагүй бөгөөд аав нь харин зөвлөгөө өгсөн байдаг.'),
  ('92ebe551-ea84-4c53-8e00-3695273a431c'::uuid, 'Бичлэгийн төгсгөлд ''бид сонгож орхихыг сурах хэрэгтэй, орхих байж л олох боломжтой'' гэсэн санааг илэрхийлж, ''орхивол олно'' гэдэг зүйр үгээр төгсгөсөн. Тиймээс A (要学会放弃) зөв. B яараад бүү санаа зов, C алдаанаас бүү ай, D сонголтоо бат зогсоо зэрэг санаанууд энэ бичлэгийн үндсэн санаатай зөрчилддөг, учир нь энд яг эсрэгээр орхиж сурахыг зөвлөж байна.')
) as v(id, explanation)
 where t.id = v.id;

update mock_test_questions as t
   set explanation_mn = v.explanation
  from (values
  ('e6d1504c-d53f-4308-b371-bb3640a40a32'::uuid, 'Эхний асуулт хэлбэрээр ''кофе уух уу?'' гэж асуухад ихэвчлэн ''үгүй'' гэсэн хариу авдаг байсныг өгүүлсэн тул C (易被拒绝) зөв. A хэл нь хатуу, B эелдэг, D бүх талыг харгалзсан зэргийг дурдаагүй, харин л татгалзуулах хариу гаргадаг гэдгийг л онцолсон.'),
  ('043e0ce6-6ae6-4d78-8c30-67e0ff112e78'::uuid, '''Кофе уух уу, сүү уух уу?'' гэж сонголттой асуулт болгож өөрчилсний дараа борлуулалт эрс өссөн тухай өгүүлжээ. Тиймээс C (销售额大增) зөв. A ашиг багассан, B зочин цөөрсөн, D бараа хүрэлцэхгүй болсон зэргийг дурдаагүй.'),
  ('e75ae1e2-56c4-4102-92a0-7be9a52b3cee'::uuid, 'Бичлэг нь хэлэлцээрийн хэл ярианы ур чадварыг маркетингт хэрхэн ашиглаж болохыг жишээгээр тайлбарлаж, асуулгын хэлбэр өөрчлөхөд борлуулалт хэрхэн өссөнийг харуулсан. Тиймээс D (语言技巧在营销中的作用) зөв. A удирдлагын арга, B ундаа сонгох арга, C үйлчилгээний хандлагын нөлөө зэрэг нь бичлэгийн гол сэдэв биш, гол цөм нь асуултын хэлбэр буюу хэл ярианы ур чадвар байсан.'),
  ('10674d97-621c-4205-ba14-276a4e868226'::uuid, '''Тэмээн хяруул аюулд орвол толгойгоо элсэнд булж, өөрөө харагдахгүй болсон гэж бодоод аюулгүй болсон гэж боддог'' гэж бичлэгт шууд тайлбарласан тул D (把头埋进沙子里) зөв. A шууд зугтдаг, B чулуун ард нуугддаг, C далавчаараа өөрийгөө хаадаг зэргийг дурдаагүй.'),
  ('ca72f535-2252-4bb5-867e-c4b7f4b4c23f'::uuid, 'Судлаачид ихэнх хүн дарамтад орохдоо асуудлыг мэдсэн ч шийдэхийг оролдохгүй, зайлсхийдэг ''тэмээн хяруулын сэтгэл зүй'' гэж нэрлэгддэг хандлагыг харуулдаг гэж хэлсэн. Тиймээс A (逃避) зөв. B эргэлзэх, C тайван байх, D болгоомжтой байх зэрэг нь энэ зайлсхийх хандлагатай тохирохгүй.'),
  ('0f5f3fce-e782-4fc3-8dcb-b013ccbba688'::uuid, 'Бичлэгийн гол санаа нь ''зөвхөн бэрхшээлтэй эрэлхэг тулгарч, шуурхай арга хэмжээ авч, хариуцлагыг өөрөө үүрч байж л хохирлыг хамгийн бага байлгах боломжтой'' гэсэн эцсийн дүгнэлт байгаа тул D (要勇敢面对困难) зөв. A даруу сэтгэлтэй суралцах, B амьтад ч ичдэг, C бэрхшээл түр зуурынх зэрэг нь бичлэгт огт дурдаагүй.'),
  ('b9cc44c4-809f-466f-bf85-a253dcd932bc'::uuid, 'Өөрийн дуу хоолойг бусад хэрхэн сонсдогийг мэдэхийн тулд ''дуу хоолойгоо бичлэг хийж, дараа нь тоглуулж үзэх'' хэрэгтэй гэж бичлэгт хэлсэн тул B (录下来回放) зөв. A ярианы хурдыг удаашруулах, C бусдаар дуурайлгах, D микрофоноор ярих зэрэг аргыг дурдаагүй.'),
  ('3e45ece8-1ec9-4b25-b72b-e20aef1276f7'::uuid, 'Хүн ярихдаа өөрийн чихээр сонссон дуу хоолой нь толгойны яс, булчингаар дамжин тархдаг тул илүү чанга сонсогддог гэж тайлбарлажээ. Тиймээс C (比较响亮) зөв. A хурдан, B бага зэрэг намуухан, D онц сайхан сонсогддог зэргийг дурдаагүй.'),
  ('53ec03e1-b735-4b14-b630-6997f8741ff5'::uuid, 'Өөрийн сонссон дуу нь ясаар дамждаг, харин бусад хүний сонсдог дуу агаараар дамждаг тул дуу дамжих орчин өөр учраас чанар нь өөр болдог гэж тайлбарлажээ. Тиймээс B (传播方式不同) зөв. A зайн ялгаа, C бичлэгийн төхөөрөмжийн чанар, D сонсголын түвшин зэргийг шалтгаан болгож дурдаагүй.'),
  ('439ae429-9a3e-45c5-90f8-244fe3c335ee'::uuid, 'Алдартай зохиолч хувцасны компаниас нэг зангиа болон захидал хүлээн авсан гэж эхэлж байгаа тул B (领带) зөв. A костюм биш яг зангиа байсан, C 50 юань бол компани хүсэлт тавьсан төлбөр, шинэ юм хүлээж аваагүй, D энэ захидал найзаас биш компаниас ирсэн зэрэг тул буруу.'),
  ('df65acd0-452e-4eca-8409-4dfb4ef744e1'::uuid, 'Компани зангиагаа сорьж үзээд өртгийн мөнгийг буцаан явуулахыг хүссэн бол, зохиолч хариуд нь 59 юанийн номоо явуулж, зөрүү 9 юанийг л буцаан явуулахыг хүссэн байна. Ингэснээр тэр бодит бэлэн мөнгө огт төлөөгүй. Тиймээс A (作家没付钱) зөв. B их азтай бодсон, C компани дампуурсан гэдгийг дурдаагүй, D борлуулалт муу гэдэг эсрэгээрээ ''таалагддаг'' гэж бичсэн байдаг.'),
  ('27b0f202-a2e1-41ea-ac32-505cea2642c1'::uuid, 'Ээж нь ''аажуухан яв, бүү унаарай'' гэж хэлдэг байсныг өгүүлж, энэ нь хүүхдээ унаж бэртэх вий гэсэн санаа зовнилоос үүдсэн гэдгийг тодорхой хэлсэн. Тиймээс A (怕他摔倒) зөв. B цаг хүрэлцэнэ гэдэг эсрэгээрээ өмнө нь ''яараарай, хоцрох гээд байна'' гэж хэлж байсантай зөрчилдөнө, C хоол боловсрол сайжруулах, D аав хүргэж өгөхийг хүлээх зэргийг дурдаагүй.'),
  ('7954f4ab-3042-409f-bdd4-06d77209f5af'::uuid, 'Бичлэгийн эцэст ''ээж хүмүүсийн нүдэнд хүүхэд үргэлж хүүхэд хэвээрээ, үргэлж халамж хайрлал хэрэгтэй байдаг'' гэж дүгнэсэн байгаа тул D (母亲觉得孩子永远需要关心) зөв. A хүүхэд байнга буруу үг хэлдэг, C ээж хүүхдээ ойлгодоггүй зэрэг нь бичлэгийн эсрэг санааг илэрхийлж байна, B хүүхэд эцэг эхээ өрөвдөх ёстой гэдгийг ч дурдаагүй.'),
  ('9d9771b2-601c-44d4-a7fc-d0848e2cef47'::uuid, 'Бичлэгт залуу насандаа цагийн үнэ цэнийг мэдэхгүй, ирээдүйд өдөр их байгаа гэж боддог, нийгэмд орсны дараа л олон юм хийгээгүйгээ ойлгодог тухай өгүүлээд, эцэст нь өнөөдрийг барьж ав, гэмшил насаараа дагахгүй байг гэж дүгнэдэг. Энэ нь цаг хугацааг үнэлэх ёстой гэсэн санаа тул A зөв, харин боломж авах B, эрсдэлд орох C, зорилгоо орхихгүй байх D зэрэг нь бичлэгт огт дурдаагүй.'),
  ('9f153929-97c1-4248-aa9d-5adc782e2a1c'::uuid, 'Эхнэр нөхрөөсөө хаана байгааг асуухад, нөхөр нь хуучин хамт очиж үзсэн зээрэнцгийн дэлгүүр, тэнд эхнэрийнхээ таашаасан зүүлт худалдаж авна гэж амласнаа сануулж, эхнэр нь баяртайгаар санаж байна гэж хариулмагц, үнэндээ өөрөө тэр дэлгүүрийн хажуугийн баарт байгаагаа хэлдэг. Ингэснээр эхнэр нь нөхрөө зүүлт худалдаж авахаар очсон гэж андуурч байсан нь илэрхий тул D зөв.'),
  ('76956676-f788-4572-9b5e-a468d0117871'::uuid, 'Бичлэгт хүний өмнө тулгарах бэрхшээл өндөр байх тусам түүний хүрэх амжилт ч их байдаг гэсэн зарчмыг тайлбарлаж, сохор хүний сонсгол илүү мэдрэмтгий, гар алдсан хүний тэнцвэрийн мэдрэмж илүү сайжирдаг жишээ татсан байна. Энэ нь бэрхшээл хүнийг амжилтад хүргэхэд тусалдаг гэсэн санааг илэрхийлж байгаа тул B зөв.'),
  ('a8f777a0-ee65-4dca-b3fa-291ed232521a'::uuid, 'Дуучин 蔡琴-ээс нэг дуугаа 80 мянга гаруй удаа дуулсан ч мэдрэмжтэй дуулж чадах уу гэж асуухад, тэрээр дуулах бол таашаал юм гэж хариулсан байна. Энэ нь тэрээр дуулах явцаас өөрөө таашаал авдгийг харуулж байгаа тул C зөв. Дуу зохиогч эсэх, шинэ дуу мөн эсэхийг бичлэгт огт дурдаагүй тул A, D буруу.'),
  ('591b59a9-36e6-41de-b974-6e1eb9cd9398'::uuid, 'Циньхуандаогийн боомтын тухай бичлэгт боомт өргөн, ус гүн, давалгаа тайван, шавар элс бага хуримтлагддаг бөгөөд жил бүрийн турш хөлддөггүй, өвлийн улиралд ч хөлөг онгоцууд хэвийн орж гардаг гэж хэлсэн байна. Энэ нь боомт өвлийн улиралд хөлддөггүй гэсэн B хариулттай тохирч байна. Боомт нарийн эсвэл элс их хуримтлагддаг гэсэн A, D нь эсрэг санаа тул буруу.'),
  ('dd62881a-b2f6-4607-81e2-2a78c8437566'::uuid, 'Тос цаасан шүхэр нь бүхэлдээ гараар хийгддэг, хулсан модоор шүхрийн яс хийж, тос түрхсэн цаасаар бүрхэвч хийдэг гэж тайлбарласан. Сайн хадгалагддаггүй тул одоо голдуу дурсгалын зүйл болгон зардаг, бодитоор хэрэглэдэг хүн цөөхөн. Тиймээс бүхэлдээ гараар хийдэг гэсэн D зөв; металл яс гэсэн B, өргөн хэрэглэгддэг гэсэн C нь эсрэг тул буруу.'),
  ('b89f02a9-536c-43bc-931d-34323e969cc8'::uuid, 'Зуны цагт хөлс их гардаг тул хөлстэй хамт кали элемент их алддаг бөгөөд тухайд нь нөхөж өгөхгүй бол хүн залхуу, ядарч, сэтгэл санаа муудаж унтмаар санагддаг гэж тайлбарласан. Энэ нь зуны ''унтаа'' үзэгдэл кали дутагдлаас үүсдэг гэсэн D хариултыг батална. Хөлс бага гаргадаг хүн ядардаг гэсэн A эсрэг санаа, кали хэрэглэж болохгүй гэсэн B ч бичлэгт харшилна.'),
  ('1569767b-af3a-4ae1-9130-3cbcfff59a1b'::uuid, 'Энэ нь Чин улсын зохиолч Пү Сунлингийн зохиосон эртний хятад хэлээр бичсэн богино өгүүллэгийн түүвэр бөгөөд ихэвчлэн үнэг, сүнсний тухай өгүүлж, дүрүүд тод, түүхийн эргэлт содон сонин гэж хэлсэн байна. Түүхийн эргэлт содон гэдэг нь A хариулттай тохирно. Урт роман биш богино өгүүллэг тул B, зохиолч тухайн номын гол дүр биш тул C буруу.'),
  ('6526a047-05a2-488f-a981-95b0da16e64d'::uuid, 'Сэтгэл судлалын судалгаагаар хүмүүс бусдын сөрөг сэтгэл хөдлөлийг дутуу үнэлж, өөрийгөө хамгийн азгүй гэж боддог ч, бусад хүн баяр хөөртэй маскны цаана уй гашуугаа нуудаг байж болзошгүй, чи ч бодож байгаа шигээ азгүй биш гэдгийг өгүүлдэг. Энэ нь өөрийн зовлонг хэтрүүлэн бодох хэрэггүй гэсэн D хариулттай нийцнэ.'),
  ('e8dc22f3-c0a7-47c6-a0c0-5dcd9bf1b9e7'::uuid, 'Лю Гунцюань бага наснаасаа бичгийн авьяастай байсан бөгөөд алдар нэр нь холдож, тиймээс жаахан бардам байсан гэж хэлдэг. Гэтэл гартаа хэсэг алдсан өвгөнтэй тааралдаж, тэр өвгөн хөлөөрөө бичсэн бичиг өөрийнхөөс ч сайхан байхыг олж мэдээд, сургамж авч хичээнгүйлэн бичиг дадлагажсаны эцэст алдарт мастер болсон гэдэг. Энэ нь эхэндээ тэрээр бардам байснаа харуулах тул A зөв.'),
  ('3b52c58d-9002-4a00-b038-14776dd78924'::uuid, 'Эрдэмтэд өөр ургамал шуугианд өөрөөр мэдрэмтгий байдгийг ашиглан шуугиан гаргадаг хогийн ургамал устгагч зохион бүтээж, шуугианаар хогийн ургамлын үрийг эрт соёолуулан тариалангийн ургамал ургахаас өмнө хогийг арилгадаг гэж тайлбарлав. Энэ нь шуугиан хэрэглэж хог ургамал ухаалгаар устгах гэсэн B хариулттай тохирно; шуугиан соёололтыг дарангуйлдаг гэсэн D эсрэгээрээ буруу.'),
  ('cda7b299-b041-4f34-b2f3-3207705a762b'::uuid, 'Аав нь ширээн дээрх утсыг ард нь түлхэхэд утас гажиж, урд талаас нь татахад дагаж хөдөлдгийг харуулаад, удирдлага гэдэг нь зорилгоороо хүмүүсийг татах явдал гэж тайлбарлав. Энэ нь зорилго нь бусдыг татах, урам зориг өгөх нөлөөтэй гэсэн D хариулттай тохирно.'),
  ('4b561e19-3238-4a9b-a10b-1752de1e7d1f'::uuid, 'Хөхтөн амьтад нь амьтны ертөнцөд хамгийн хөгжсөн тархитай тул зан үйл нь илүү нарийн, гадаад орчны өөрчлөлтөд өөрсдийгөө байнга дасан зохицуулж чаддаг гэж тайлбарлав. Энэ нь дасан зохицох чадвар илүү сайн гэсэн D хариулттай тохирно.'),
  ('d9e6c1fd-7c2e-42c9-bf26-d63dfd4cb024'::uuid, 'Нарс, хулс, чавганз гурав өвлийн хатуу ширүүн үед ч амьдрах чадвараа хадгалдаг тул хятадын соёлд язгууртны шинжийг илэрхийлдэг бэлгэдэл, зурган урлагийн нийтлэг сэдэв болсон бөгөөд тэдний зургийг эрт үеийн эд юм, хувцас, барилгад чимэглэлд ашигладаг байсан гэж хэлдэг. Энэ нь эдгээр гурвыг хятад хүмүүс өндөр үнэлдэг гэсэн D хариулттай тохирно.'),
  ('fedb76c2-e77f-49eb-a175-08dd593d86be'::uuid, 'Замын хөдөлгөөний гэрлийн улаан гэрэл нэвтрэх чадвар нь ногооноос илүү хүчтэй тул манантай үед улаан гэрэл илүү хол харагддаг, тиймээс улаанаар зогсох дохио өгч жолооч нар эрт харж бэлдэх боломжтой болгодог гэж тайлбарладаг. Энэ нь улаан гэрлийн нэвтрэх чадвар ногооноос илүү гэсэн C хариулттай шууд тохирно.'),
  ('c8c03a2d-ce4d-488c-825c-ad4736548b04'::uuid, 'Ярилцлагад эмэгтэй бизнес эрхлэгч ахиц дэвшил гэдгийг байнга шинэ зүйл бүтээх, өөртөө таашаадаг төдийгүй бусдад ч ашиг тустай зүйл бүтээх явдал гэж тодорхойлж байгаа тул энэ нь шинийг санаачлан бүтээх санааг илэрхийлж байгаа тул A зөв. B, C, D-ийн тухай шууд дурдаагүй.'),
  ('8f04ffbc-ef9d-46a6-a196-1a703975d875'::uuid, 'Тэрээр бизнес эрхлэгчийн хувьд бүтэлгүйтэхээс айгаад хийхийг хүссэн зүйлээ хийхгүй байж болохгүй гэдгийг сургамжаа болгож, шинэлэг зүйлд бүтэлгүйтэх нь хамгаалалттай амьдралаар амжилтад хүрэхээс дээр гэж хэлсэн байна. Энэ нь бүтэлгүйтэхээс айж болзошгүй ажлаа орхиж болохгүй гэсэн D хариулттай тохирно.'),
  ('7eb7389a-8c26-4434-b124-e148ec17b16c'::uuid, 'Тэрээр хүн залуу насандаа алдаа гаргаж, бүдэрч унасан ч эрсдэл хүлээж чадах учраас зоригтойгоор оролдож үзэх хэрэгтэй, хожим хөгширсний дараа хийж чадах байсныг гэмших ёсгүй гэж хэлж байна. Энэ нь залуу насандаа зоригтой оролдох ёстой гэсэн A хариулттай тохирно.'),
  ('6476f8d3-44be-4399-880d-70b08cef55c0'::uuid, 'Тэрээр амжилттай амьдрал гэдгийг тодорхойлохдоо зөвхөн өөрийн хүссэн байдлаараа амьдрах бол л амжилт гэж хэлсэн бөгөөд амжилтын тухай өнөөгийн ойлголт хэт нарийсч байгаа гэж шүүмжилсэн. Энэ нь өөрийн дуртай байдлаараа амьдрах гэсэн D хариулттай тохирно.'),
  ('00922df7-f5fa-420f-a35a-3e632525d491'::uuid, 'Тэрээр дүрсэлсэн шиг тодорхой загварын эмэгтэй гэж байхгүй, хүн бүр өөр өөр, өөрийнхөө хамгийн гайхамшигтай хувилбар болж чадна гэж хэлсэн. Тиймээс тийм загварын эмэгтэй байдаг уу гэсэн асуултад тэр ийм зүйл байхгүй гэж хариулж байгаа тул A зөв.'),
  ('b13b4a92-1643-4ef5-8bd5-c06d87e762fa'::uuid, 'Сэтгэл зүйч манлайлагч гэдэг бол нийгмийн нэгэн үүрэг бөгөөд бүх хүн заавал манлайлагч болох албагүй гэж тодорхой хэлсэн тул нийгмийн үүрэг мөн гэсэн A хариулт зөв. Харин бүх хүн манлайлагч болох ёстой гэсэн D нь яг эсрэг санаа тул буруу.'),
  ('a3de7d51-6cae-4548-827b-e9541a2e53c4'::uuid, 'Тэрээр манлайллын зан чанарыг хөгжүүлсэн хүүхэд илүү сайн бүлэгт нэгдэж, харилцаагаа зөв барьж, дуртайяа юм хийж чаддаг болно гэж тайлбарласан. Энэ нь бүлэгт илүү сайн нэгдэхэд тусалдаг гэсэн D хариулттай тохирно.'),
  ('8c0e52aa-abf3-4258-97b1-a666e5e8bf76'::uuid, 'Тэрээр манлайллын зан чанарын хамгийн чухал зүйл бол бусадтай хамтран ажиллах чадвар, сайн харилцааны ур чадвар гэж хэлсэн тул харилцаа, хамтын ажиллагааны чадвар гэсэн D хариулт зөв.'),
  ('9b8918e3-8d6b-41b3-9da4-cabdd6bf5aca'::uuid, 'Эцэг эх хариуцлагыг шууд хүлээлгэж өгч чадахгүй, харин хүүхдээ өөрөө мэдрэхэд нь тохирсон удирдамж өгч, шийдвэрийнхээ үр дагаврыг өөрөө хариуцахад нь дасгах хэрэгтэй гэж хэлсэн. Энэ нь хүүхдэд өөрөө мэдрэх боломж олгох тухай B хариулттай тохирно.'),
  ('4f91ffef-8dce-45da-af9f-cc13d4aae3f9'::uuid, 'Тэрээр зөвхөн чи их сайн байна гэж хэлэхийн оронд, магтаалыг хүүхдийн бодит сайн үйлдэлд тодорхой холбож хэлэх хэрэгтэй гэж хэлсэн тул тодорхой бодит үйлдэлд тулгуурлах гэсэн C хариулт зөв.'),
  ('ff2504ee-87fc-4c81-9251-bc1acbe641bd'::uuid, 'Тэрээр анх удаа орчуулга хийхдээ нэг л удаад амжилттай орчуулж дуусгасан, орчуулгын явц харьцангуй гөлгөр байсан гэж хэлсэн тул орчуулга нэлээд гөлгөр явсан гэсэн C хариулт зөв.'),
  ('038d96b2-7a09-413c-bce1-045a1261c705'::uuid, 'Тэрээр Ван Кэйигийн орчуулсан ''Бардамнал ба Өрөвдөл'' номын хэл найруулгыг хошин ухаалаг, мэргэн, зусардмаар гэж магтсан тул хэл нь хошин, ухаалаг гэсэн C хариулт зөв.'),
  ('87172687-7044-4825-b940-0ca0a9c8c4ff'::uuid, 'Тэрээр зохиогч бол шинээр бүтээгч, орчуулагч бол дахин бүтээгч бөгөөд хоёулаа бүтээлч ажил гэдгийг онцолж, орчуулга бол хоёр дахь удаагийн бүтээл гэж тодорхойлсон тул орчуулга бол нэг төрлийн дахин бүтээл гэсэн B хариулт зөв.'),
  ('09191f7e-0875-4ed5-b369-4b5f696cba07'::uuid, 'Тэрээр сайн орчуулагч ихэвчлэн зан чанарын жүжигчин шиг байдаг, өөрийн жинхэнэ дүрээрээ тоглодоггүй гэж зүйрлэсэн тул зан чанарын жүжигчин гэсэн D хариулт зөв.'),
  ('c4e7f227-29cc-44c6-89c0-793ba2568ca9'::uuid, 'Ярилцлагын эхэнд тэрээр Фүданьгийн их сургуулийн математикийн ангийг төгссөн, тэр үед сургууль түүнийг гадаадад математик судлахаар илгээсэн гэж дурдсан тул өмнө нь математик мэргэжлээр суралцаж байсан гэсэн C хариулт зөв.'),
  ('a8bcc518-845f-4588-95b8-900bd70432da'::uuid, 'Дэлхийн хамгийн том гинкго мод Хятадын Фүцюаньд байдаг бөгөөд түүний нас 5000 гаруй жил гэдгийг өгүүлж, язгуурын диаметр, өндөр, цээжний диаметрийг дурдаад 13 хүн тэвэрч барьж чадна гэж хэлсэн байна. Тиймээс энэ мод хэдэн мянган жил амьд байгаа гэсэн B хариулт зөв; тэврэхэд 3 хүн биш 13 хүн шаардлагатай тул D буруу.'),
  ('2bd6ebb4-9c13-43f5-a064-6d455c3465b4'::uuid, 'Бичлэгт гинкго модыг амьд чулуужсан амьтан, гэр зуухны өмнөх мод, ургамлын ертөнцийн панда гэсэн хочтой гэж дурдсан ч мянган жилийн модны хаан гэдгийг огт дурдаагүй тул энэ хоч бичлэгт байхгүй гэсэн C хариулт зөв.'),
  ('1b11c398-1d93-40fe-84bc-32daa91dad99'::uuid, 'Гинкго мод хоол, материал, эмийн зэрэг олон зориулалтаар ашиглагддаг, бүхэлдээ үнэт зүйл гэж тайлбарласан тул хэрэглээ өргөн гэсэн A хариулт зөв. Навчинд онцгой эмийн үнэ цэнэ байдгийг тодорхой хэлсэн тул эмэнд хэрэглэдэггүй гэсэн D буруу; ургалт удаан гэдэг нь хурдан ургадаг гэсэн C-тэй ч харшилна.'),
  ('0eaafc3d-e364-4420-aad1-d7d6a69e5f25'::uuid, 'Тэр хүн ишгээ Гүйжоу мужид авчирсан ч тэнд ямар ч хэрэг байхгүйг олж мэдээд ууланд уяад орхисон гэж өгүүлдэг тул ишиг ямар ч ашиггүй гэж бодсон гэсэн B хариулт зөв.'),
  ('38d73c01-35c4-441d-a708-a7cd3709580c'::uuid, 'Бар ишгийг анх харахдаа энэ ямар нэгэн гайхамшигтай, ид шидтэй зүйл байх нь гэж бодож, ойролцоо мод бутанд нуугдан хол ажигласан тул анхны сэтгэгдэл нь ид шидтэй гэсэн A хариулт зөв. Хожим л бар аажмаар ойртож ишгийн жинхэнэ чадварыг олж мэдсэн юм.'),
  ('8c9d4962-4b1c-4103-a1f1-812c87f73e14'::uuid, 'Ишиг бартай уурлаж туурайгаараа цохисны дараа бар баярлаж, ишгийн чадвар үнэндээ ердийн зүйл гэдгийг ойлгосон тул бар ишигт онцгой чадвар байхгүйг олж мэдсэн гэсэн C хариулт зөв.'),
  ('4f1574fa-7c3b-4ba7-b262-4f567ff7e818'::uuid, 'Ишиг чадвар багатай гэдгийг олж мэдсэний дараа түүхийн төгсгөлд бар ишиг рүү үсрэн дайрч, хурц шүдээрээ хоолойг нь хазаж, идэж дуусгасан гэж өгүүлдэг тул ишиг эцэст нь барт идэгдсэн гэсэн D хариулт зөв.'),
  ('c23eab5f-174a-450b-af78-acb85caf4e40'::uuid, 'Эртний бичгийг судалдаг эрдэмтэн лун гу хэмээх эмийн материал дээр бичиг шиг зурсан хээ байгааг олж хараад бүх лун гуг худалдан авч судалсан гэдэг тул тэр бичиг мэт хээ олсон гэсэн C хариулт зөв.'),
  ('a0b5ad16-c461-4586-b246-9ae8fa819454'::uuid, 'Бичлэгт хятад ясан бичиг нь одоогийн хятад үсгийн эртний хэлбэр бөгөөд одоо хадгалагдаж үлдсэн хамгийн эртний төлөвшсөн бичиг гэж хэлсэн тул төлөвшсөн бичиг гэсэн B хариулт зөв. Олдсон дөрвөн мянга гаруй тэмдэгтээс ердөө хоёр мянга таван зуу орчим нь тайлагдсан тул бүгд тайлагдсан гэсэн C буруу.'),
  ('f9ae9d22-b548-4777-957b-81437c683e30'::uuid, 'Энэ бичвэр лун гу эмийн материал дээрх хээнээс эхэлж, хятад ясан бичиг хэрхэн олдож, нэрлэгдсэн тухай өгүүлж байгаа тул ясан бичиг хэрхэн олдсон тухай гэсэн A хариулт зөв.'),
  ('0da100d7-51c1-49d6-8d08-666df5cc1372'::uuid, 'Бичлэгт зохистой хэрэглэгчид зохистой бүтээгдэхүүн санал болгох нь харахад хялбар мэт боловч хийхэд хэцүү гэж хэлсэн тул энд хэрэглэсэн үг нь энгийн, амархан хийж болох мэт харагддаг зүйл гэсэн утгаар хэрэглэгдсэн тул C хариулт зөв.'),
  ('776628c1-515d-4f03-8885-b4051d69414a'::uuid, 'Бичлэгт зар сурталчилгааны даалгавар бол хэрэглэгчийн аль хэдийн байгаа хэрэгцээг тодорхой бүтээгдэхүүн рүү чиглүүлэх явдал бөгөөд хэрэгцээг өөрөө шинээр бүтээх биш гэж тодорхой хэлсэн тул хэрэглээний хүсэл эрмэлзлийг өдөөж чиглүүлэх гэсэн B хариулт зөв.'),
  ('c348b2d1-728b-4f27-a050-3f5e5976a998'::uuid, 'Амжилттай зар сурталчилгааны нууц бол зорилтот уншигчдын байршил тухайн бүтээгдэхүүний хэрэглэгчийн байршилтай нийцэж байх, өөрөөр хэлбэл зохистой хэрэглэгчид зохистой бүтээгдэхүүнээ санал болгох явдал гэж дурдсан тул байршил тодорхой, нарийвчлалтай байх гэсэн A хариулт зөв.'),
  ('6b884081-a11d-417c-9a83-395a79f9a895'::uuid, 'Сэтгэл судлаачдын үзэж байгаагаар пенальти цохигчид ихэвчлэн хаалгачийн хөдөлгөөнд хэт их анхаарал хандуулж, түүнийг ажиглах гэж оролдох тусам сандардаг бөгөөд улмаар цохилтоо алддаг гэж хэлсэн тул хаалгачид хэт их анхаарал хандуулдаг гэсэн B хариулт зөв.'),
  ('c5577a15-d473-440b-bf17-a43c8e9e780d'::uuid, 'Цохилтын нарийвчлалыг нэмэгдүүлэхийн тулд пенальти цохигч эхлээд сэтгэл зүйн байдлаа тохируулж, дарамтыг аль болох бууруулах ёстой гэж хэлсэн тул дарамтаа сааруулах гэсэн A хариулт зөв.'),
  ('e20f67c0-ee08-4d51-8aba-0fd6fea53e85'::uuid, 'Цохигч нөгөө талын хаалгачийг илүү бухимдуулахын тулд харцаа өгөх, хаалганы тодорхой цэг рүү анхаарлаа чиглүүлж харах зэрэг арга хэрэглэж болно гэж хэлсэн тул хаалга руу ширтэж харах гэсэн C хариулт зөв.'),
  ('5ffded60-4208-4c54-bbf9-4aece5424ce6'::uuid, 'Энэ бичвэр бүхэлдээ пенальти цохилтод амжилтад хүрэх сэтгэл зүйн болон бусад аргуудын тухай өгүүлж байгаа тул пенальтигийн амжилтын арга ур чадвар гэсэн B хариулт зөв.')
) as v(id, explanation)
 where t.id = v.id;

update mock_test_questions as t
   set explanation_mn = v.explanation
  from (values
  ('de1b1f63-2c71-4b5d-b0f3-4970629f686b'::uuid, 'Ангараг гарагийн агаар мандал маш шингэн, нягтрал нь дэлхийнхээс 1 хувиас ч бага бөгөөд ихэвчлэн нүүрстөрөгчийн давхар ислээс тогтдог гэж хэлсэн тул маш шингэн, нимгэн гэсэн A хариулт зөв. Нүүрстөрөгчийн давхар исэл нь үндсэн бүрэлдэхүүн хэсэг тул түүний агууламж бага гэсэн C буруу.'),
  ('e65c3b8c-a605-490c-bdd4-4b22a690c3dc'::uuid, 'Эрдэмтэд Ангараг гарагаас ирсэн солир дээр микроб амьдралын ул мөр олсон бөгөөд энэ солир 40-45 тэрбум жилийн өмнө үүссэн гэж тооцоолсон, гэхдээ энэ ул мөр дэлхийн бодисоор бохирдсоны улмаас үүссэн байж болзошгүй гэж хэлсэн байна. Тиймээс микробын ул мөртэй гэсэн B хариулт зөв; 50 тэрбум жилийн өмнө үүссэн гэсэн D нь тоо буруу.'),
  ('c1e05be2-2441-48f0-a762-10cfc137687f'::uuid, 'Бичвэрийн төгсгөлд Ангараг гарагийн амьдралын нууц одоо ч тайлагдаагүй байна гэж дүгнэсэн тул амьдрал байгаа эсэх нь баталгаагүй хэвээр байна гэсэн D хариулт зөв.'),
  ('b0339b39-0f6a-4302-bd89-67c3bd4af2c1'::uuid, 'Бичлэгт эрт үеийн тагтнуудын тухай өгүүлж, тодорхой зайтай тутамд ''五里亭'' буюу ''十里亭'' гэдэг тагт байгуулж, хүмүүс амарахын зэрэгцээ явсан замын хэрийг тооцоолоход ашигладаг байсныг тайлбарласан тул D зөв. A, B, C сонголтууд бичлэгт дурдсан ''ихэвчлэн хана хэрэмгүй, дээд тал нь зургаан эсвэл найман өнцөгтэй'' гэсэн мэдээлэлтэй зөрчилддөг тул буруу.'),
  ('d6527c0e-f0af-427f-bd42-f86a5ab6bb49'::uuid, 'Бичлэгт нэг ваар будаагаар юу хийхээс шалтгаалан үнэ цэн нь өөр өөр байдгийг харьцуулж, 15 минутад чанасан цагаан будаа 1 юань, 2 цагт хийсэн зунз 3-4 юань, харин сарууд турш исгэсэн дарс 20-30 юань болдог гэж хэлсэн. Иймд илүү их хугацаа, хүч зарцуулах тусам үр дүн, үнэ цэн нь ихсэнэ гэсэн санааг илэрхийлж буй тул C зөв.'),
  ('3e4dc329-f370-402e-a571-5ff984610d6e'::uuid, 'Энэ хэсэгт ''хүн хол хэтийн төлөвлөгөөгүй бол ойрын зовлон учирна'' гэсэн эртний хятад зүйр цэцэн үгийг дурдаж, зөвхөн өдгөө өмнөх зүйлд төвлөрч, эцсийн зорилгоо мартаж болохгүй гэдгийг сануулж байна. Энэ нь хол хэтийн харцтай байх ёстойг заасан тул A зөв.'),
  ('b8639a36-8f6e-4f5b-8e4e-eb14aadc53a1'::uuid, 'Бичлэгт Хайнань мужийн Ву Жи (五指山) уулын тухай дурдаж, дулаан бүсэд орших тул ой мод шигүү ургаж, ургамлын төрөл зүйл маш баялаг тул ''ногоон эрдэнийн сан'' гэж нэрлэдэг болохыг хэлсэн. Энэ нь ургамлын төрөл олонтой болохыг батласан тул C зөв. Уулын оргилын тоо, цасны тухай яриагүй тул D, A буруу.'),
  ('db946510-cab1-45d1-a9b8-dd0e2c1259ba'::uuid, 'Тариаланч буудай тарихаас бороо орохгүй байх вий гэж, хөвөн тарихаас хорхойтох вий гэж айсны улмаас эцэст нь юу ч тариагүй гэж хариулсан. Аюулгүй байдлыг хангахын тулд эрсдэл авахаас зайлсхийсэн энэ зан чанар нь эрсдэлээс айдгийг харуулж буй тул B зөв.'),
  ('61644107-261c-495f-ad26-ed024802baab'::uuid, 'Алдарт зураач Ци Байши шавийнхаа зурсан сайхан зургийг хараад түүнийгээ хуулбарлан зурж, ''Би багш чинь ч гэсэн чамаас муу байж болно'' гэж хэлсэн нь маш даруу зан чанарыг харуулсан тул B зөв. Шавь өөрийгөө буруутгуулсангүй тул A буруу.'),
  ('68321048-fdb6-45fc-b0d9-74778a53c476'::uuid, 'Хүүхдийн асуудал ихэвчлэн эцэг эхийнхээ асуудлаас үүддэг, хүүхэд бол эцэг эхийнхээ дүрийг тусгасан дэлгэц шиг гэж хэлж байна. Иймд хүүхдээс ямар нэг асуудал ажиглагдвал тэр нь эцэг эхийн өөрийнх нь асуудал болохыг олж мэдэх боломжтой гэсэн санаа тул D зөв.'),
  ('d46dfae6-f7b4-403e-8ebf-7d55164c5c3e'::uuid, 'Ихэнх хүн санхүүгээ төлөвлөх (理财) гэдгийг баяжихын тулд хийдэг гэж андуурдаг ч бодит зорилго нь санхүүгээ тогтвортой байлгах явдал гэж бичлэгт шууд хэлсэн байна. Энэ нь D сонголттой яг таарч байна. ''Баяжих'' гэдэг үгийг зөвхөн буруу ойлголт гэж дурдсан тул C буруу.'),
  ('6bc27cd7-474c-401d-827d-c92660590891'::uuid, 'Чадвар, хяналтаас чинь давсан зүйл тохиолдоход анхаарлаа өөрийн дуртай зүйл рүү шилжүүлэх нь дарамтыг сааруулдаг гэж, жишээ болгож эмэгтэйчүүд хувцас өмсөж үзэх жишээг дурдсан. Энэ нь дарамтаа хэрхэн бууруулахыг зааж байгаа тул A зөв.'),
  ('97faf01d-01b8-4ee1-bd97-0e6f218bb1bf'::uuid, 'Дэлхий даяар 600 гаруй амьтны төрөл цаг агаарын өөрчлөлтийг мэдрэмтгий мэдэрдэг бөгөөд шөнө шавьжны чимээ сонсогдвол дараа өдөр цаг агаар сайхан, аалзбадрага дээш доош нисвэл 1-2 цагийн дараа бороо орохыг мэдэгддэг жишээг дурдсан. Энэ нь зарим амьтад цаг агаарыг урьдчилан мэдэрдэгийг харуулсан тул C зөв.'),
  ('6f068692-81de-40f0-8e12-fdf608167902'::uuid, 'Хүний бичсэн үсгийн хэлбэрээр зан чанарыг нь тодорхойлж болно гэж бичлэгт өгүүлж, жижиг үсэг бичдэг хүн ажиглах чадвартай, том үсэг бичдэг хүн бусдын анхаарлыг татахыг хүсдэг, дугуй үсэг бичдэг хүн эелдэг, ойлголцоо сайтай гэсэн жишээ авчирсан. Энэ нь гар бичмэл зан чанарыг тусгадаг гэсэн санааг батласан тул B зөв.'),
  ('8080d8ea-311b-4da0-b798-506774ae5e20'::uuid, 'Мэргэжилтнүүд давс их идэх нь цусны даралт ихсэхээс гадна нүүрний эсийг чийгшүүлж, арьс хуучирахад хүргэдэг тул өдөрт 6 грамаас илүүгүй давс идэх, их ус уухыг зөвлөж байна. Энэ нь давс их идэх нь арьсанд хортой гэдгийг батласан тул D зөв. Давс идэх нь бие махбодид тустай гэсэн санаа бичлэгт огт байхгүй тул A, C буруу.'),
  ('c9aa869a-a4ba-4005-bbb3-02167f44d387'::uuid, 'Богино өгүүллэг (''微型小说'' буюу ''小小说'') хэлбэрээрээ богино боловч агуулгын хувьд ердийн зохиолын адил дүр төрх, сэтгэл зүйн дүрслэлийг нарийн хийдэг гэж бичлэгт хэлсэн бөгөөд ''богино боловч бяцхан агуулгатай'' гэсэн хэллэгийг ашигласан нь A сонголттой яг таарч байна. D буруу нь бичлэгт сэтгэл зүйн дүрслэлийг ч мөн чухалчилдаг гэж шууд хэлсэнтэй зөрчилддөг.'),
  ('29a07ec8-1b76-4a09-8a47-56d5cb6321d4'::uuid, 'Цэцэг худалдагч өглөө дэлбэрсэн бадам цэцэг сонгохыг зөвлөж, өглөө нээгдээгүй бол үд, орой ч нээгдэхгүй гэж хэлээд, хүн бас адилхан, залуу насандаа зорилготой болоогүй бол дунд, өндөр насандаа улам хэцүү болно гэсэн зүйрлэл хийсэн. Энэ нь эрт зорилготой болох хэрэгтэйг сануулж буй тул B зөв.'),
  ('b43b5473-54c0-42c6-bc34-f80f13d8ac92'::uuid, 'Олон хүн сэрэхдээ нуруу, бөгс өвддөг нь буруу нойрны байрлалтай холбоотой ч эрүүл хүн байрлалдаа хэт баригдах шаардлагагүй, учир нь хүн шөнөжингөө нэг байрлалд хэвтэж чаддаггүй, ихэнх хүн байрлалаа өөрчилж, ингэснээр ядаргаагаа тайлдаг гэж хэлсэн. Энэ нь байрлал өөрчлөх нь биед сайн гэдгийг батласан тул A зөв.'),
  ('c6f9521a-b563-4778-9aa8-7d99ebe81244'::uuid, 'Ярилцлагад тэрхүү загварын шоу нь хятад үндэстний хувцасны сэтгэл татам байдлыг харуулж буйг шууд дурдсан тул D зөв. Бусад сонголтууд болох цаг үеийн дүр төрх, дорно-өрнийн соёлын мөргөлдөөн зэрэг нь ярилцлагад дурдагдаагүй.'),
  ('6e612c1d-2218-42cb-8167-3a53384389b2'::uuid, 'Загварчин үндэстний шинж чанарыг гагцхүү хувцасны хэлбэр дүрсээр биш, харин дотор нь нуугдсан үндэстний сэтгэлгээг илэрхийлэх ёстой гэж тодорхой хэлсэн тул A ''民族精神'' зөв. Уламжлалт урлаг, орчин үеийн гоо зүй, сонгодог загвар зэрэг нь энэ хариултад тохирохгүй.'),
  ('6e71ffc2-3a5c-40e9-8e7f-3de98b10554f'::uuid, 'Загварчин загвараа бүрэн боловсруулахдаа эхлээд зах зээлийн мэдээллийг цуглуулж ангилдаг, дараа нь бүтээлч санаа гаргаж, эцэст нь хэрэглэгчийн эрэлт хэрэгцээнд нийцүүлдэг гэсэн гурван алхмыг тайлбарласан. Эхний алхам нь зах зээлийн мэдээлэл цуглуулах учир B зөв.'),
  ('1fb802d0-6bc0-4bde-a1f8-bf378eb990bc'::uuid, 'Загварчин Сишуанбаннагийн ойд бэлгэдэл зурж байхдаа тогос, хулсан байшин, сарны гэрэлд гялалзах хулс зэргийг ажигласнаа дурдаж, ''амьдрал гоо үзэсгэлэнгээр дутагдалгүй, зөвхөн олж хараагүй байгаа юм'' гэж хэлсэн нь бүтээлч сэтгэлгээ амьдралаас ирдэгийг харуулж буй тул A зөв.'),
  ('67ec89ef-6944-4960-a6f0-3b8b53b90b1b'::uuid, 'Ярилцлага бүхэлдээ энэ хүний зохион бүтээсэн загварын шоу, түүний загвар боловсруулах арга барилын тухай өгүүлж байгаа тул тэрбээр хувцасны загварчин мөн гэдэг нь тодорхой, B зөв.'),
  ('f547e404-a3f4-49e2-bfbc-8b9368b0594b'::uuid, 'Найруулагч Ли Ан зөвхөн нэг хүү, нэг бар оролцсон, бараг ярианы хэсэггүй кино хийхээ тайлбарлаж байгаа тул D зөв (баатрууд нь хүү, бар). Транскрипт дэх ''бараг ярианы хэсэггүй'' гэсэн үг A (''对白很多'' буюу яриа их) сонголттой зөрчилдөж байна.'),
  ('7a32d257-ab1e-4a5b-952e-a8f7a44aba7f'::uuid, 'Ли Ан хийж байгаагүй зүйл л сонирхолтой, шинэ, өдөөлттэй байх тусам сайн, сорилтгүй бол зорилго тэмүүлэл алга болно гэж хэлсэн нь тэрбээр шинэ сэдвийг сорилт, давалт хайж туршиж үзэхийг хүсдэг гэдгийг харуулж байгаа тул D зөв.'),
  ('753ed0a9-7481-4f08-87c6-b6863f7c9582'::uuid, 'Ли Ан айх нь хүчтэй байх, айх нь болгоомжоо дээшлүүлдэг, тэр л амьд явах, мэдлэг олж авах хамгийн сайн байдал гэж тайлбарласан тул айдас хүнийг сэрэмжтэй байлгадаг гэсэн санаа B зөв.'),
  ('4da26907-bfac-44c4-ab56-edb7a3c198d6'::uuid, 'Эмэгтэй сэтгүүлч яагаад цэвэр ариун царай сонгосон бэ, харин зоригтой эсвэл ухаалаг царай биш, эдгээр хоёр чанар л хүнийг бэрхшээлээс гарахад илүү тус болдог юм биш үү гэж асуусан нь тэрбээр ухаалаг, тэсвэр хатуужилтай (聪明和坚强) чанарыг илүү үнэлдгийг харуулж буй тул C зөв.'),
  ('67604897-846d-4780-b4f1-749fb6b05ff1'::uuid, 'Ли Ан ярилцлагын төгсгөлд ''энэ талаараа би хэзээ ч томрохгүй байхыг хүсч байна'' гэж хэлж, цэвэр ариун байдлаа үргэлж хадгалахыг хүсдэгээ илэрхийлсэн тул C зөв.'),
  ('6a1d73eb-7731-48c2-bb58-d52ad0f08c3c'::uuid, 'Тамирчин ''би өөрийгөө бахархаж байна'' гэж шууд хэлж, 12 жилийн турш үндэсний шигшээ багт байр сууриа хадгалж, дасгалжуулагчийн эхний сонголт хэвээр байгаагаа нотолсноо ярьсан тул тэрбээр өнөөгийн байдлаараа өөрийгөө үнэлж, бахархаж буй нь тодорхой, тиймээс C зөв.'),
  ('d89d319b-2e64-41a2-86ed-95aea564fcd2'::uuid, 'Тамирчин хэрэв би тоглосоор л байвал энэ нь олон залуучуудад урам зориг (鼓励) болно гэж хэлсэн нь өөрийгөө залуучуудад урамшуулал өгдөг гэж үзэж буйг харуулна, энэ нь A ''激励'' (урамшуулах/өдөөх) гэсэн санаатай нийцэж байгаа тул зөв.'),
  ('0e680515-d136-413a-883d-979420b9b35d'::uuid, 'Тамирчин олимпын наадам ариун ч гэсэн амьдралын эцсийн зогсоол буюу тэмцлийн эцсийн шат биш гэдгийг тодорхой хэлсэн бөгөөд энэ нь тэрбээр олимпоос гадна тоглоомоо үргэлжлүүлэн хийхээ илэрхийлж буйг харуулдаг тул B ''并非奋斗的终点'' зөв.'),
  ('f0014813-14ba-4c8d-9f54-fcefb3537ad2'::uuid, 'Тамирчин жаргал бол гэр орон, эд хөрөнгө биш, харин гэр бүлийн хайр, тэдний урамшуулал дэмжлэг гэж тодорхой хэлсэн тул A зөв. Амжилтын мэдрэмж (成就感) нь жаргал биш гэдгийг тэрбээр өөрөө ялгаж тайлбарласан тул B, C, D буруу.'),
  ('8b18f4b6-8d84-4299-8f2e-d0498ce2b666'::uuid, 'Тамирчин Лондон бол намайг Хятадын эрэгтэй ганцаарчилсан төлөөлж оролцох гурав дахь олимп гэж хэлсэн нь тэрбээр нэгээс олон удаа олимпод оролцсоныг харуулж буй тул C зөв.'),
  ('e81f2516-95f4-4bbb-911a-e021e9e48a9d'::uuid, 'Хоёр сайд Сун улсын Тайзунтай хамт архи ууж согтуурсны эцэст хааны нүүр дээр л алдар гавьяагаа харьцуулж, эрх мэдэлдээ бахархан хэрэлдэж эхэлсэн тул D зөв. Энэ бол хааныг шүүмжлэх, эрдэм үзүүлэх зэрэг сонголтуудтай тохирохгүй.'),
  ('5a42e053-4083-4461-8095-c37706372a26'::uuid, 'Тайзун хаан харуулын хүсэлтийг зөвшөөрөлгүй зөвхөн зоог хурлыг тарааж, дараа өдөр нь хоёр сайд уучлал гуйхаар ирэхэд ''би ч бас согтуу байсан, юу ч санахгүй байна'' гэж хөнгөн ханддаг хариулт өгсөн нь тэднийг шийтгэлгүй орхисныг харуулж буй тул D ''不做计较'' зөв.'),
  ('235bd10d-5f1d-45fb-b7d9-ceb946ecbfc8'::uuid, 'Хоёр сайдын явдлыг харьцангуй хөнгөн шийдвэрлэсний дараа түүхийн төгсгөлд ''тэвчээртэй, уужим сэтгэлтэй байх нь удирдагчийн заавал байх ёстой сайхан чанар юм'' гэж шууд дүгнэсэн бөгөөд бусад сонголт болох сонсох чадвар, шударга байдал, ажилтны давуу талыг олж харах зэргийг дурдаагүй тул A зөв.'),
  ('2819a204-de36-4511-8c83-cbe5d487f796'::uuid, 'Мэдээнд өвлийн амралт дуусах дөхөх үед онгоцоор явах сурагчдын тоо хоёр дахин нэмэгдсэн (''学生人数倍增'') гэж хэлсэн бөгөөд эдгээрийн олонх нь ганцаараа явах хүүхдүүд байна гэсэн тул сурагчдын тоо нэмэгдсэн А зөв.'),
  ('6d30381b-0a54-40be-b7c2-ba97119bc1a9'::uuid, 'Мэдээнд хамгаалагчгүй хүүхдийн насны хязгаар 5-аас 12 нас хүртэл, 12-18 насныхан сайн дураараа хүсэлт гаргаж болно гэж тодорхой хэлсэн тул заавал хамгаалагчгүй үйлчилгээ хүсэх насны хязгаар нь B ''5-12 нас'' зөв.'),
  ('b47b8766-22d2-4a25-a68b-0c8e977694da'::uuid, 'Онгоцны буудлын ажилтан эцэг эхчүүдэд хамгаалагчгүй хүүхдийг үдэж, авахдаа ''оройтож явж, эрт ирэх'' зарчмыг баримтлахыг сануулсан бөгөөд тодруулбал үдэх эцэг эх хүүхдийн онгоц хөөрсний дараа л явах, авах эцэг эх онгоц буухаас хагас цагийн өмнө ирэх ёстойг тайлбарласан тул A зөв.'),
  ('939251c4-b9eb-48a8-b7d6-4cfcf0f55282'::uuid, 'Мэдээнд эцэг эх тасалбар авах үедээ хамгаалагчгүй хүүхдийн үйлчилгээг захиалах ёстой, урьдчилан захиалаагүй бол бүртгэл хийхэд ерөнхийдөө хүлээж авдаггүй гэж тодорхой хэлсэн тул A зөв. Тоо хязгаарлагдмал, компани бүрийн журам ялгаатай гэдгийг мэдээ дурдсан тул B, D буруу.'),
  ('324881dd-944f-4e90-93b9-812aec9d1d70'::uuid, 'Мэдээнд бараг бүх ургамал хөгжим сонсдог, хөнгөн тайван аялгуунд сайхан ургадаг гэж хэлж, эсрэгээр рок хөгжим тоглуулбал зарим ургамал хатаж, үхэж ч болно гэж дурдсан. Иймд ургалтыг дэмждэг хөгжим бол зөөлөн уянгалаг хөгжим тул C ''轻松舒缓的'' зөв.'),
  ('d4bea0fd-cba3-4bfb-96f3-0bbefd05c977'::uuid, 'Эрдэмтэд 20 төрлийн цэцгийг харьцуулан ажигласны эцэст чимээ шуугиан цэцгийн ургалтын хурдыг дунджаар 47%-иар удаашруулдаг, рок хөгжим тоглуулбал заримдаа ургамал хатаж үхдэг гэсэн дүгнэлтэд хүрсэн тул чимээ шуугиан ургалтыг дарангуйлдаг гэсэн A зөв.'),
  ('1f64370e-6cb7-4225-91b6-9882f7e9c454'::uuid, 'Мэдээний төгсгөлд зөөлөн хөгжмийн долгион ургамлын эсийн молекулуудыг өдөөж, бодисын солилцоог хурдасгадаг тул ургалт нь сайжирдаг гэж тайлбарласан тул D зөв.'),
  ('42a011fa-bb84-43a3-bc1c-d62c899e5943'::uuid, 'Мэдээнд нисдэг дугуйг (飞轮) хөдөлгөхийн тулд эхэндээ маш их хүч зарцуулж, тойрог тутамд дахин дахин түлхэх ёстой гэж тодорхой хэлсэн тул C ''用力反复推'' зөв.'),
  ('7720930e-617f-4d28-a20b-b5d37fec0a2b'::uuid, 'Мэдээнд эхлээд их хүчээр дахин дахин түлхэсний эцэст тодорхой ялгарлын цэгт хүрч, тэр цагаас хойш дугуйн өөрийнх нь жин ба хөдөлгөх хүч нь дугуйг цааш түлхэх хүчний нэг хэсэг болж хувирдаг тул нэмж хүч зарцуулах шаардлагагүй болно гэж тайлбарласан, тиймээс D зөв.'),
  ('a3606eb8-fb24-4816-95df-c45cfc63461b'::uuid, 'Мэдээ ''юу ч гэсэн эхлэл нь хэцүү, улам их хичээх тусам амжилт ойрхон байдаг'' гэсэн санаагаар төгссөн бөгөөд энэ нь ажлын эхэнд илүү их хичээл зүтгэл гаргах хэрэгтэйг сануулж буй тул D зөв.'),
  ('c083c044-112b-4811-a064-25a4ae65dff3'::uuid, 'Цахилгаан шат дотор хоёр хамтдаа явж байсан хүн байхад өвчтөн ухаангүй болоход нэг нь тайвшруулж, нөгөө нь эмнэлэгт утасдан тусламж дуудсан гэж хэлсэн - энэ нь үүрэг хуваарилан хамтдаа авардаг гэдгийг харуулж буй тул B зөв.'),
  ('a54d1efc-b007-4db3-80dd-6c04c8a2bad2'::uuid, 'Психологич энэ туршилтыг цахилгаан шатан дотор явуулсан гэж эхэнд нь шууд тодорхойлсон тул C зөв. Хамгийн ихдээ 4 хүн оролцсон гэсэн мэдээлэл байхгүй бөгөөд хүний тоо улам нэмэгдэхэд гарах хүн ч улам олон болсон гэж хэлсэн тул D буруу.'),
  ('167df7e8-5fa9-40a8-8f3e-014694032a8f'::uuid, 'Туршилтад оролцогчид явсан шалтгаанаа тайлбарлахдаа бусдыг дагасан, өөр хэн нэг нь тусалж чадна гэж бодсоноо хэлсэн бөгөөд энэ нь бусдыг дагах, түшиглэх сэтгэл зүй гэдгийг батласан тул C зөв.'),
  ('4669e64e-11af-4aa4-909d-1a111ecafd4c'::uuid, 'Мэдээ сайн сайхан, шударга үйлдлийг төлөвшүүлэхэд зөвхөн ёс суртахууны эргэцүүлэл хангалтгүй, эерэг хүчтэй сэтгэл зүйн хүчийг бас бий болгох хэрэгтэй гэж дүгнэсэн тул D ''正义之举不能仅靠道德'' зөв.'),
  ('3433dc68-144a-4f55-9973-6e7d76ea7615'::uuid, 'Мэдээнд хүний тархины зүүн, баруун хагас бөмбөрцгийн үйл ажиллагаа өөр өөр байдгийг тайлбарлаж, үүнийг тэрхүү нэр томьёогоор нэрлэсэн байна. Тодорхойлолт нь яг л ''зүүн, баруун хагас бөмбөрцгийн үйл ажиллагаа ялгаатай байдаг'' гэсэн санаа тул D зөв.'),
  ('ae23a1aa-21b5-4419-b8b8-a6f6c71dcae3'::uuid, 'Мэдээнд хэлний харилцаанд үг хэллэгийн цаана нуугдсан мэдээлэл, өөрөөр хэлбэл үгээр биш далд илэрхийлсэн санаа байдгийг тайлбарласан тул 言外之意 гэдэг нь C ''话中暗含的意思'' (үгийн дотор далдлагдсан утга) гэсэн утгатай.'),
  ('50721147-5dff-470d-b7be-b8a7937c559b'::uuid, 'Мэдээ бүхэлдээ тархины баруун хагас бөмбөрцөг нь ярианы далд утга, элэглэл зэрэг шууд бус илэрхийллийг хэрхэн боловсруулдгийг тайлбарлаж байгаа тул D ''大脑右半球的语言功能'' зөв.')
) as v(id, explanation)
 where t.id = v.id;

